window.__LEX={"G4300":"<h1>prokuroo</h1>\n<p>Strong n° 4300 <i>Prononciation [prok-oo-ro'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sanctionner, ratifier, ou établir d'avance</li>\n<li>valider d'avance, qui a reçu force de loi</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·κυρόω-ῶ</b> <span>[ῡ]</span> sanctionner auparavant, NT. <i>Gal. 3, 17 ;</i><br><b><i>Moy.</i></b> <i>m. sign</i>. RHÉT. <i>1, 605 W</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-κυροω - προκυρόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G4301":"<h1>prolambano</h1>\n<p>Strong n° 4301 <i>Prononciation [prol-am-ban'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prendre avant</li>\n<li>anticiper, devancer</li>\n<li>saisir quelqu'un en le devançant (c.à.d. avant qu'il ait pu fuir ou commettre un crime)\n<ol type=\"a\">\n<li>surprendre, découvrir, prendre sur le fait</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·λαμϐάνω</b> <span>(<i>f</i>. προλήψομαι, <i>ao.2</i> προὔλαϐον, <i>etc</i>.)</span><br><b>   I</b> (πρό, devant) :<br><b>      1</b> prendre et porter en avant, avancer : ἐξ οἴκων πόδα, EUR. <i>Ion 1253,</i> porter ses pas hors de la maison ;<br><b>      2</b> prendre les devants, THC. <i>7, 80 ;</i> XÉN. <i>Cyn. 6, 19 ; 7, 7 ;</i> PLUT. <i>Alex. 20, etc. ; fig. en parl. de l’intelligence,</i> ARSTT. <i>fr. 96 ;</i><br><b>      3</b> prendre de préférence : τι πρό τινος, SOPH. <i>O.C. 1141,</i> prendre une chose de préférence à une autre ;<br><b>      4</b> prendre en remontant à l’origine, reprendre dès l’origine, ISOCR. <i>119</i> a, <i>351</i> c ;<br><b>   II</b> (πρό, auparavant) :<br><b>      1</b> prendre d’abord : τὴν πόλιν, LYS. <i>176, 5,</i> la ville ; τὰ χωρία καὶ λιμένας, DÉM. <i>20, 21,</i> les territoires et les ports ;<br><b>      2</b> recevoir d’avance : ἀργύριον, DÉM. <i>1211, 5,</i> de l’argent ; τι παρά τινος, ESCHN. <i>50, 20,</i> recevoir d’avance qqe ch. de la main de qqn ;<br><b>      3</b> prendre d’avance : τὸν καιρόν, POL. <i>9, 14, 12,</i> prévenir l’occasion ; <i>avec le gén. :</i> τῆς ὁδοῦ, HDT. <i>3, 105,</i> prendre l’avance d’un bout de chemin ; τῆς φυγῆς, THC. <i>4, 33,</i> prendre l’avance dans la fuite ; <i>abs</i>. οἱ νόμοι προλαϐόντες ἐπιμέλονται ὅπως, XÉN. <i>Cyr. 1, 2, 3,</i> les lois veillent d’avance à ce que (<i>litt</i>. ayant pris les devants veillent à ce que) <i>etc. ; d’où</i> prendre d’avance ses précautions : ὅπως, DÉM. <i>29, 1,</i> pour que, <i>etc. ;</i><br><b>      4</b> prendre d’avance par l’esprit, <i>càd</i>. présumer, préjuger : μὴ πρότερον προλαμϐάνειν, DÉM. <i>44, 3,</i> ne pas apporter d’opinion préconçue ; <i>au pass</i>. être présumé, POL. <i>34, 6, 7, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-λαμβανω - προλαμβάνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G4302":"<h1>prolego</h1>\n<p>Strong n° 4302 <i>Prononciation [prol-eg'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>dire d'avance, prédire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·λέγω :<br>   I</b> (πρό, devant) :<br><b>      1</b> choisir de préférence à d’autres, IL. <i>13, 689 ;</i> THCR. <i>Idyl. 13, 18 ;</i><br><b>      2</b> désigner comme premier, mettre au premier rang, PD. <i>N. 2, 28 ;</i><br><b>   II</b> (πρό, auparavant) dire auparavant, <i>d’où :</i><br><b>      1</b> prédire, <i>acc. en parl. d’un oracle,</i> HDT. <i>1, 53 ; 8, 136 ;</i> ESCHL. <i>Pr. 1071 ;</i> PLAT. <i>Euthyphr. 3</i> c ; <i>en parl. d’un médecin,</i> pronostiquer, HPC. <i>Progn. 42 ;</i><br><b>      2</b> prévenir, avertir, <i>avec</i> ὅτι, PLAT. <i>Rsp. 337</i> a, <i>etc. ;</i><br><b>      3</b> annoncer, déclarer d’avance, <i>acc</i>. (une interdiction légale, LYCURG. <i>148, 16 ;</i> une guerre, POL. <i>13, 3, 5, etc.) ; avec une prop. inf</i>. ESCHL. <i>Sept. 336, etc. ;</i> τινί, <i>avec l’inf</i>. XÉN. <i>An. 7, 7, 3 ;</i> DIN. <i>99, 14 ;</i> τινὶ ὅτι, ANT. <i>126, 17 ; ou</i> ὡς, POL. <i>5, 57, 2,</i> ordonner à qqn de, <i>etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προλεγω - προλέγω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G4303":"<h1>promarturomai</h1>\n<p>Strong n° 4303 <i>Prononciation [prom-ar-too'-rom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>affirmer d'avance\n<ol type=\"a\">\n<li>rendre connu, prédire</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·μαρτύρομαι</b> <span>[ῡ]</span> attester d’avance, NT. <i>1Petr. 1, 11</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-μαρτυρομαι - προμαρτύρομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4304":"<h1>promeletao</h1>\n<p>Strong n° 4304 <i>Prononciation [prom-el-et-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>méditer d'avance, se soucier par avance de</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·μελετάω-ῶ :<br>      1</b> s’exercer d’avance à, <i>acc</i>. AR. <i>Eccl. 117 ;</i> PLAT. <i>Soph. 218</i> d ; <i>inf</i>. XÉN. <i>Ath. 1, 20 ;</i><br><b>      2</b> préluder, AR. <i>Th. 1178 ;</i> POL. <i>10, 47, 3</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προμελεταω - προμελετάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4305":"<h1>promerimnao</h1>\n<p>Strong n° 4305 <i>Prononciation [prom-er-im-nah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être inquiet, anxieux d'avance</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·μεριμνάω-ῶ</b>, s’inquiéter d’avance <i>ou</i> auparavant, NT. <i>Marc. 13, 11 ;</i> CLÉM. <i>595</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προμεριμναω - προμεριμνάω</font>\n<br><br>Voir définition 3209</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (2)</li>\n</ul>\n</td></tr>\n</table>","G4306":"<h1>pronoeo</h1>\n<p>Strong n° 4306 <i>Prononciation [pron-o-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>apercevoir avant, prévoir</li>\n<li>pourvoir, penser d'avance\n<ol type=\"a\">\n<li>pourvoir pour quelqu'un</li>\n<li>penser à, prendre soin de</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·νοέω-οῶ</b> <span>(<i>f</i>. -οήσω, <i>ao</i>. προὐνόησα, <i>etc</i>.)</span><br><b>   I</b> pressentir, prévoir, <i>acc</i>. IL. <i>18, 526 ;</i> PD. <i>P. 10, 98, etc. ;</i> THC. <i>3, 38, etc. ;</i> ὅτι, XÉN. <i>Cyr. 8, 1, 13,</i> que, <i>etc. ;</i><br><b>   II</b> penser d’avance, songer d’avance, <i>d’où :</i><br><b>      1</b> prendre d’avance soin de, veiller à, <i>gén</i>. XÉN. <i>Cyr. 8, 1, 1, etc. ;</i> ARR. <i>Epict. 2, 14, 11 ;</i><br><b>      2</b> pourvoir à : τι, OD. <i>5, 364 ;</i> XÉN. <i>Cyr. 4, 1, 6,</i> pourvoir à qqe ch. ; <i>abs</i>. être prévoyant, se pourvoir, prendre des mesures de précaution, THC. <i>3, 43, etc. ; joint à</i> προϐουλεύεσθαι, XÉN. <i>Mem. 2, 10, 3 ; avec un relat</i>. πρ. ὅτι, THC. <i>3, 58 ;</i> ὅπως, XÉN. <i>Hipp. 4, 1,</i> pourvoir à ce que, prendre des mesures pour que, <i>etc. ;</i> πρ. ὡς μή, XÉN. <i>Cyr. 1, 6, 24 ; ou simpl</i>. μή, XÉN. <i>Œc. 9, 11,</i> veiller à ce que… ne, <i>etc. ;</i><br><b><i>Moy.</i></b> <span>(<i>f</i>. προνοήσομαι, <i>ao</i>. προὐνοησάμην <i>ou</i> προὐνοήθην, <i>pf</i>. προνενόημαι)</span> prendre d’avance soin de, pourvoir à : τινος, THC. <i>6, 9, etc. ;</i> τι, THC. <i>4, 61 ;</i> XÉN. <i>Mem. 4, 3, 12, etc. ;</i> ὑπέρ τινος, DÉM. <i>179, 14, etc. ;</i> περί τινος, LYS. <i>99, 31,</i> à qqe ch. ; <i>avec l’inf</i>. ANT. <i>134, 25, etc</i>. veiller à, <i>etc. ;</i> prendre la résolution de, résoudre de, <i>inf</i>. EUR. <i>Hipp. 398</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao</i>. προὐνοησάμην, EUR. <i>Hipp. 399 ;</i> ANT. <i>134, 25 ;</i> προὐνοήθην, PLAT. <i>Crat. 395</i> c ; LYS. <i>98, 46, etc. ; au sens pass</i>. SEXT. <i>M. 9, 404</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-νοεω - προνοέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4307":"<h1>pronoia</h1>\n<p>Strong n° 4307 <i>Prononciation [pron'-oy-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>soin providentiel</li>\n<li>faire provision d'une chose, prévoyance, préoccupation</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρόνοια, ας (ἡ) :<br>   I.1</b> prévision, prescience, pressentiment, SOPH. <i>Tr. 823 ; au plur</i>. ESCHL. <i>Ag. 684 ;</i><br><b>      2</b> action de pronostiquer, pronostic, HPC. (GAL. <i>8, 585</i>) ;<br><b>      3</b> prescience d’un oracle, <i>d’où</i> oracle, SOPH. <i>Tr. 823 ;</i><br><b>   II</b> soin de pourvoir, <i>d’où :</i><br><b>      1</b> prévoyance, ATT. (SOPH. <i>Aj. 536, etc</i>.) ;<br><b>      2</b> précaution, HDT. <i>9, 144 ;</i> THC. <i>8, 95 ;</i> πρόνοιαν ἔχειν τινός, THC. <i>2, 89, etc. ; ou</i> περί τινος, SOPH. <i>Ant. 283 ;</i> ὑπέρ τινος, POL. <i>1, 57, 1 ; ou</i> πρόνοιαν ποιεῖσθαί τινος, DÉM. <i>546, 6, etc</i>. prendre d’avance soin de qqe ch., pourvoir d’avance à qqe ch. ; πρόνοιαν ἔχειν <i>avec l’inf</i>. EUR. <i>Hec. 569,</i> prendre soin de, <i>etc. ;</i><br><b>      3</b> acte réfléchi, ce qu’on fait par suite d’une décision arrêtée d’avance : ἐκ προνοίας, HDT. <i>1, 120, etc. ;</i> ANT. <i>113, 42 ;</i> LYS. <i>98, 43,</i> de propos délibéré, à dessein ; <i>en parl. de crimes,</i> préméditation, LYS. <i>100, 2 ;</i> ESCHN. <i>84, 21 ;</i> DIN. <i>90, 33, etc. ;</i><br><b>      4</b> providence, <i>particul</i>. τοῦ θείου ἡ πρ. HDT. <i>3, 108,</i> πρ. τοῦ θεοῦ, SOPH. <i>O.C. 1180 ;</i> ἡ θεία πρόνοια, EUR. <i>Ph. 640 ; ou simpl</i>. ἡ Πρόνοια, XÉN. <i>Mem. 1, 4, 6, etc</i>. la providence divine, la Providence ; Ἀθηνᾶ πρόνοια, DÉM. <i>780, 17 ;</i> DS. <i>11, 14 ;</i> PLUT. <i>M. 825</i> b, <i>etc</i>. Athèna Providence, <i>surn. d’Athèna, à Delphes</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. προνοίη, HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. πρόνοος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προνοια - πρόνοια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4308":"<h1>proorao</h1>\n<p>Strong n° 4308 <i>Prononciation [pro-or-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>voir avant (en considération de lieu ou de temps)</li>\n<li>garder devant ses yeux</li>\n<li>métaph. être toujours attentif à quelqu'un</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·οράω-ῶ</b> <span>(<i>f</i>. προόψομαι, <i>ao.2</i> προεῖδον, <i>pf</i>. πρόοιδα, <i>d’où inf</i>. προειδέναι)</span><br><b>   I</b> voir en avant :<br><b>      1</b> voir devant soi, <i>acc</i>. THC. <i>7, 44 ; abs</i>. XÉN. <i>Cyr. 4, 3, 21 ; avec</i> εἰς <i>et l’acc</i>. ARSTT. <i>H.A. 4, 1, 12 ;</i><br><b>      2</b> prévoir, connaître d’avance, <i>acc</i>. PD. <i>N. 1, 27 ;</i> HDT. <i>5, 24 ;</i> XÉN. <i>Cyr. 3, 2, 15 ; Conv. 4, 5 ;</i> DÉM. <i>52, 4, etc. ;</i><br><b>   II</b> pourvoir à, <i>gén</i>. HDT. <i>3, 159 ; d’où</i> prendre soin de, <i>gén</i>. HDT. <i>2, 121 ; 5, 39 ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> regarder devant soi, XÉN. <i>Cyr. 4, 3, 21 ;</i><br><b>      2</b> prévoir pour soi, THC. <i>5, 111 ;</i> DÉM. <i>63, 11 ;</i><br><b>      3</b> pourvoir à, <i>acc</i>. THC. <i>1, 17 ;</i> PLAT. <i>Rsp. 499</i> b, prendre ses précautions, <i>avec</i> πρός <i>et l’acc</i>. DS. <i>20, 102 ; avec</i> μή, DÉM. <i>773, 1</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. sbj. 2 pl</i>. προειδῆτε, THC. <i>1, 37</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-οραω - προοράω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4309":"<h1>proorizo</h1>\n<p>Strong n° 4309 <i>Prononciation [pro-or-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prédéterminer, décider d'avance</li>\n<li>dans le N.T : de Dieu annonçant l'éternité</li>\n<li>prédestiner, destiner d'avance</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·ορίζω</b>, déterminer <i>ou</i> fixer auparavant, <i>acc</i>. NT. <i>Eph. 1, 5 ; avec une prop. inf</i>. NT. <i>Ap. 4, 28</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-οριζω - προορίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4310":"<h1>propascho</h1>\n<p>Strong n° 4310 <i>Prononciation [prop-as'-kho]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>souffrir avant</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·πάσχω</b> <span>(<i>ao.2</i> προέπαθον, <i>pf</i>. προπέπονθα)</span><br><b>      1</b> souffrir auparavant <i>ou</i> le premier, <i>acc</i>. HDT. <i>7, 11 ;</i> THC. <i>3, 82 ;</i> SOPH. <i>O.C. 230 ;</i> PLAT. <i>Rsp. 376</i> a, <i>etc. ;</i> πρ. ὑπό τινος, THC. <i>3, 67,</i> être maltraité auparavant par qqn ;<br><b>      2</b> <i>en b. part :</i> éprouver le premier <i>ou</i> auparavant, <i>acc</i>. XÉN. <i>Mem. 2, 2, 5</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-πασχω - προπάσχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G4311":"<h1>propempo</h1>\n<p>Strong n° 4311 <i>Prononciation [prop-em'-po]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>envoyer à l'avant</li>\n<li>amener sur le chemin, accompagner ou escorter</li>\n<li>laisser partir, en donnant le nécessaire pour un voyage</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·πέμπω</b> <span>(<i>f</i>. -πέμψω, <i>ao</i>. προὔπεμψα, <i>pf</i>. προπέπομφα)</span><br><b>      1</b> envoyer auparavant, <i>acc</i>. HDT. <i>1, 60, etc. ;</i> THC. <i>1, 29, etc. ;</i><br><b>      2</b> envoyer en avant : ἄνδρας πρὸ τοῦ στρατεύματος, XÉN. <i>Cyr. 2, 4, 23,</i> des hommes en avant de l’armée, <i>d’où</i> simpl. envoyer, IL. <i>8, 367, etc. ;</i> OD. <i>17, 54, etc. ; avec un rég. de chose :</i> φήμας τινί, SOPH. <i>El. 1155,</i> des bruits aux oreilles de qqn ; ἄχη, SOPH. <i>Ant. 1287,</i> apporter des douleurs à qqn ; <i>avec un suj. de chose,</i> ESCHL. <i>Ag. 820, etc. ;</i> SOPH. <i>Ph. 105 ;</i><br><b>      3</b> escorter, faire cortège à, accompagner, <i>acc</i>. HDT. <i>1, 111, etc. ;</i> SOPH. <i>O.C. 1667 ;</i> XÉN. <i>Hell. 4, 1, 9 ;</i> τινὰ ἐς δόμους, ESCHL. <i>Pers. 530,</i> qqn à sa demeure ; τινὰ χθονός, EUR. <i>Hipp. 1099,</i> qqn hors d’un pays ; <i>particul</i>. accompagner un convoi funèbre, ESCHL. <i>Sept. 1059, etc. ;</i><br><b><i>Moy.</i></b> envoyer en avant, <i>acc</i>. XÉN. <i>Cyr. 5, 3, 53, etc. ;</i> voir partir, <i>acc</i>. ESCHL. <i>Pers. 138</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-πεμπω - προπέμπω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 6 livres bibliques (NT)\n<ul>\n<li>Actes (3)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Tite (1)</li>\n<li>3 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4312":"<h1>propetes</h1>\n<p>Strong n° 4312 <i>Prononciation [prop-et-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tomber en avant, la tête la première, qui agit précipitamment, étourdiment</li>\n<li>se précipiter, être téméraire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προπετής, ής, ές :<br>   I</b> qui tombe en avant, HPC. <i>Progn. 37, 41, etc. ; p. suite,</i> tombé en avant, jeté par terre, SOPH. <i>Tr. 701 ;</i><br><b>   II</b> qui se penche en avant ; <i>au propre, en parl. de la tête,</i> HPC. <i>Art. 780, etc. ; du cou d’un cheval,</i> XÉN. <i>Eq. 1, 8 ; de la démarche en gén</i>. ARSTT. <i>Inc. an. 14, 5 ; de pers</i>. ARSTT. <i>Physiogn. 3, 5 ; p. suite :</i><br><b>      1</b> qui tombe devant : τύμϐου, EUR. <i>Hec. 152,</i> devant le tombeau ; πολιὰς ἐπὶ χαίτας, EUR. <i>Alc. 913,</i> qui incline vers des cheveux blancs, <i>càd</i>. qui est sur le déclin de l’âge ;<br><b>      2</b> enclin, porté à : πρός τι, PLAT. <i>Leg. 792</i> d ; εἴς τι, XÉN. <i>Hell. 6, 5, 14 ;</i> ἐπί τι, XÉN. <i>Hell. 2, 3, 15 ;</i> ἐπί τινος, THPP. (ATH. <i>435</i> b) enclin à qqe ch. (aux plaisirs, <i>etc</i>.) ; εἰς χεῖρας, <i>avec un inf</i>. XÉN. <i>Hell. 2, 3, 30,</i> qui a un penchant à faire qqe ch. ;<br><b>      3</b> <i>abs</i>. qui se porte en avant, emporté, fougueux, ARSTT. <i>Nic. 3, 7, 12 ; H.A. 9, 1, 5, etc. ; en parl. de choses (intempérance,</i> ARSTT. <i>Nic. 7, 7, 8 ; sensualité,</i> ESCHN. <i>27, 8 ; rire,</i> ISOCR. <i>5</i> a) ;<br><b>   III</b> qui se porte en avant, proéminent : προπετεῖς ὀφθαλμοί, A. APHR. <i>Probl. 2, 22,</i> yeux saillants.<br><span>•<i> Cp</i>. προπετέστερος, HPC. <i>Art. 798 ;</i> ARSTT. <i>H.A. 9, 1, 5 ; Physiogn. 3, 5 ;</i> <i>• Sup</i>. προπετέστατος, XÉN. <i>Hell. 2, 3, 30</i>.<br><span><b>Étym</b>. προπίπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προπετης - προπετής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4313":"<h1>proporeuomai</h1>\n<p>Strong n° 4313 <i>Prononciation [prop-or-yoo'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>envoyer devant, faire précéder</li>\n<li>passer devant\n<ol type=\"a\">\n<li>d'un chef</li>\n<li>d'un messager ou d'un héraut</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>προ·πορεύω</b>, envoyer devant, EL. <i>N.A. 10, 22 ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> avancer, marcher en avant, XÉN. <i>Cyr. 4, 2, 23 ;</i> POL. <i>3, 52, 8 ; en parl. de l’avant-garde d’une troupe,</i> POL. <i>2, 27, 2 ; en parl. d’une servante,</i> ATH. <i>267</i> c ; <i>p. ext</i>. couler, s’écouler, <i>en parl. d’une rivière,</i> SPT. <i>Gen. 2, 14 ;</i><br><b>      2</b> marcher devant, <i>gén</i>. ARSTT. <i>Mir. 137 ; abs</i>. POL. <i>1, 80, 8, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προπορευομαι - προπορεύομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4314":"<h1>pros</h1>\n<p>Strong n° 4314 <i>Prononciation [pros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>à l'avantage de</li>\n<li>à, près de, par</li>\n<li>vers, envers, avec, en considération de</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρός</b>, <i>adv. et prép. :</i><br><b>A</b> <i>adv</i>., auprès, <i>d’où</i> à côté, en outre, DÉM. <i>47 fin ; 611, 12, etc. ; d’ord. avec une conj. ou une particule,</i> πρὸς δέ, IL. <i>5, 307 ; 10, 108, etc. ;</i> HDT. <i>1, 71, etc. ;</i> ATT. <i>etc</i>. et en outre ; πρὸς δὲ καί, HDT. <i>1, 164, 207, etc. ;</i> ATT. <i>m. sign. ;</i> πρὸς δ' ἔτι, HDT. <i>3, 74, m. sign. ;</i> καὶ πρός, HDT. <i>7, 154, 184 ;</i> ATT. <i>m. sign. ;</i> καὶ πρός γε, EUR. <i>Hel. 110 ;</i> καί γε πρός, PLAT. <i>Men. 90</i> e, <i>m. sign. ;</i> καὶ δὴ πρός, HDT. <i>5, 7, m. sign. ;</i> τε πρός, EUR. <i>Or. 622, m. sign. ;</i> πρὸς γάρ, HDT. car en outre ;<br><b>B</b> <i>prép. avec le gén., le dat. et l’acc. :</i><br><b>   I</b> <i>gén. :</i><br><b>      1</b> de, en venant de : ἠὲ πρὸς ἠοΐων ἢ ἑσπερίων ἀνθρώπων, OD. <i>8, 29,</i> qu’il soit issu des peuples de l’Orient ou de ceux de l’Occident ; ὁ πρὸς Σάρδεων ἤλεκτρος, SOPH. <i>Ant. 1037,</i> l’ambre venant de Sardes ; <i>p. suite</i> du côté de, <i>particul. pour désigner la région du ciel :</i> πρὸς Βορέαο…, πρὸς Νότου, OD. <i>13, 110,</i> du côté de Borée (le Nord), du côté de Notos (le Sud) ; πρὸς δύνοντος ἡλίου, ESCHL. <i>Suppl. 255,</i> du côté du couchant ; <i>qqf. avec le gén. et l’acc. à la fois :</i> πρὸς ἠῶ τε καὶ τοῦ Τανάϊδος, HDT. <i>4, 120,</i> du côté de l’Orient et du Tanaïs ; <i>cf</i>. HDT. <i>2, 121 ; 4, 17 ; ou, en gén. pour marquer une région quelconque :</i> πρὸς ἁλός, IL. <i>10, 428 ;</i> πρὸς θαλάσσης, HDT. <i>2, 114,</i> du côté de la mer ; νῆσοι πρὸς Ἤλιδος, OD. <i>21, 347,</i> les îles voisines de l’Élide ; <i>avec un n. de pers. :</i> γένος ἐξ Ἁλικαρνησσοῦ τὰ πρὸς πατρός, HDT. <i>7, 99,</i> originaire d’Halicarnasse par son père ; Ἀθηναῖον καὶ τὰ πρὸς πατρὸς καὶ τὰ πρὸς μητρός, DÉM. <i>1303 fin,</i> Athénien par son père et par sa mère ; πρόγονοι ἢ πρὸς ἀνδρῶν ἢ πρὸς γυναικῶν, PLAT. <i>Theæt. 173</i> d, les ancêtres du côté des hommes ou du côté des femmes ; <i>avec un n. de chose représentant un n. de pers. :</i> οἱ πρὸς αἵματος, SOPH. <i>Aj. 1305,</i> les parents par le sang ; <i>p. anal</i>. πρός τινος εἶναι, HDT. <i>1, 75, etc. ;</i> ESCHL. <i>Sept. 516 ;</i> THC. <i>3, 38, etc. ;</i> πρός τινος γίγνεσθαι, HDT. <i>1, 124 ; 8, 22,</i> être <i>ou</i> se mettre du côté de qqn, être favorable à qqn ; πρός τινος λέγειν, AR. <i>Vesp. 647,</i> parler en faveur de qqn ; <i>p. suite,</i> à l’égard de, par rapport à, concernant : δρᾶν οὐδὲν ἄδικον οὔτε πρὸς θεῶν οὔτε πρὸς ἀνθρώπων, THC. <i>1, 71,</i> ne commettre aucun méfait ni à l’égard des dieux ni à l’égard des hommes ;<br><b>      2</b> de la part de, par le fait de : ἔχειν τιμὴν πρὸς Διός, OD. <i>11, 302,</i> être récompensé <i>ou</i> honoré par Zeus ; κακόν τι πρός τινος λαμϐάνειν, HDT. <i>2, 139, 152,</i> éprouver du mal par le fait de qqn ; ἀκούειν τι πρός τινος, IL. <i>6, 525,</i> apprendre qqe ch. de qqn ; μανθάνειν πρός τινος, SOPH. <i>Ph. 959, O.C. 13,</i> savoir par qqn ; πρός τινος πάσχειν, HDT. <i>1, 73, etc. ;</i> ESCHL. <i>Pr. 92, etc. ;</i> SOPH. <i>Ph. 1343,</i> souffrir par le fait de qqn ; <i>avec un subst. ou un adj. :</i> πειθὼ πρὸς ἀνδρός, SOPH. <i>El. 562,</i> le fait d’être persuadée par un homme ; δόξα πρὸς ἀνθρώπων, EUR. <i>Her. 625,</i> la réputation qui vient des hommes ; ἔρημος πρὸς φίλων, SOPH. <i>Ant. 919,</i> abandonnée par mes amis ; <i>p. suite</i> πρός <i>s’emploie après un verbe passif comme synonyme de</i> ὑπό : πρός τινος λείπεσθαι, SOPH. <i>Ph. 1070,</i> être abandonné par qqn ; διδάσκεσθαί τι πρός τινος, IL. <i>11, 831,</i> apprendre qqe ch. par qqn ; λέγεσθαι πρός τινος, HDT. <i>3, 115, etc. ou</i> τετιμῆσθαι, HDT. <i>2, 75,</i> être vanté <i>ou</i> estimé par qqn ; πρός τινος ἀτιμάζεσθαι, HDT. <i>1, 61,</i> être déshonoré par qqn ; τὸ ποιεύμενον πρὸς Λακεδαιμονίων, HDT. <i>7, 209,</i> ce que font les Lacédémoniens ;<br><b>      3</b> par la volonté de, au nom de : πρὸς θεῶν, IL. <i>1, 239 ;</i> ESCHL. <i>Sept. 199, etc</i>. par la volonté <i>ou</i> au nom des dieux ; <i>particul. dans les formules de serments :</i> γουνάζομαί σε πρός τ' ἀλόχου καὶ πατρός, OD. <i>11, 67,</i> j’embrasse tes genoux en te suppliant au nom de ton épouse et de ton père ; ἐπιορκεῖν πρὸς δαίμονος, IL. <i>19, 188,</i> se parjurer après avoir juré par un dieu ; <i>rar. en parl. d’une divinité particulière :</i> πρὸς τῆς Ἀθηνᾶς, DIN. <i>95 fin,</i> au nom d’Athèna ; πρὸς Χαρίτων, LUC. <i>H. conscr. 14,</i> au nom des Grâces ; πρός τ' εἴ τί σοί ἐστι προσφιλές, SOPH. <i>Ph. 469,</i> au nom de ce que tu peux avoir de plus cher ; <i>qqf. séparé de son rég. par le pron</i>. σέ (<i>s.-e</i>. ἱκετεύω) : πρὸς νύν σε πατρὸς πρός τε μητρὸς ἱκνοῦμαι, SOPH. <i>Ph. 468,</i> eh bien donc, je te supplie au nom de ton père et de ta mère ; πρός σε θεῶν, EUR. <i>Ph. 1659, Med. 325,</i> je te supplie au nom des dieux ;<br><b>      4</b> <i>p. suite,</i> à cause de : πρὸς τίνος ποτ' αἰτίας (τέθνηκεν) ; SOPH. <i>O.R. 1236,</i> comment est-elle morte ? πρὸς ἀμπλακημάτων, SOPH. <i>Ant. 51,</i> par suite des égarements ;<br><b>      5</b> en venant de, en tenant à, sous la dépendance de : κεν πρὸς ἄλλης ἱστὸν ὑφαίνοις, IL. <i>6, 456,</i> tu tisserais de la toile sous les ordres d’une autre ;<br><b>      6</b> en faveur de, pour, HDT. <i>1, 75, 124 ;</i> SOPH. <i>O.R. 1434, Tr. 479, etc. ;</i> EUR. <i>Alc. 57 ;</i><br><b>      7</b> de la part de : πρὸς Διός εἰσι ξεῖνοί τε πτωχοί τε, OD. <i>6, 207,</i> les étrangers et les mendiants viennent de la part de Zeus, sont envoyés par Zeus ;<br><b>      8</b> comme venant de, à la façon de, comme il convient à : κακὸν τὸ κεύθειν κοὐ πρὸς ἀνδρὸς εὐγενοῦς, EUR. <i>Hel. 950,</i> c’est un acte vil de dissimuler et qui n’est pas d’un homme bien né ; ἄτοπα λέγεις καὶ οὐδαμῶς πρὸς σοῦ, XÉN. <i>Mem. 2, 3, 15,</i> tu dis d’étranges choses et qui vraiment ne sont pas dignes de toi ; πρὸς ἀτιμίας λαϐεῖν τι, PLUT. <i>Cic. 13,</i> prendre une chose comme un déshonneur ; πρὸς σοῦ ἐστιν, EUR. <i>H.f. 585,</i> c’est ton affaire, cela te convient ; πρὸς δίκης, SOPH. <i>O.R. 1014, etc</i>. selon la justice ; οὐκ ἦν πρὸς τοῦ Κύρου τρόπου, XÉN. <i>An. 1, 2, 11,</i> cela n’était pas dans le caractère de Cyrus ;<br><b>   II</b> <i>dat</i>. en touchant à, <i>càd. :</i><br><b>      1</b> contre, sur : ποτὶ γαίῃ, OD. <i>8, 190, etc. ;</i> contre terre ; ποτὶ γούνασι, IL. <i>5, 408,</i> sur les genoux ; πρὸς ἀλλήλῃσιν ἔχεσθαι, OD. <i>5, 329,</i> se tenir serrées les unes contre les autres ; πασσάλευε πρὸς πέτραις, ESCHL. <i>Pr. 56,</i> cloue (le) contre le rocher ; πρὸς βωμῷ σφαγείς, ESCHL. <i>Eum. 295,</i> égorgé sur l’autel ; <i>avec un verbe de mouvement suivi d’immobilité :</i> βάλλειν ποτὶ γαίῃ, IL. <i>1, 245 ;</i> OD. <i>2, 80,</i> jeter contre terre ; βάλλειν τινὰ ποτὶ πέτρῃ, OD. <i>5, 415,</i> lancer qqn contre un rocher ; <i>fig</i>. πρός τινι εἶναι, PLAT. <i>Phæd. 84</i> c, <i>ou</i> γίγνεσθαι, XÉN. <i>Hell. 4, 8, 22,</i> s’appliquer à qqe ch. ; τὴν διάνοιαν ἔχειν πρός τινι, PLAT. <i>Rsp. 500</i> b, appliquer sa pensée à qqe ch. ; τὴν γνώμην ἔχειν πρός τινι, ESCHN. <i>81, 32,</i> avoir son esprit appliqué à qqe ch. ; διατρίϐειν πρός τινι, ARSTT. <i>Pol. 5, 7, 10 ; ou</i> σχολάζειν πρός τινι, ARSTT. <i>Pol. 5, 7, 9,</i> être occupé à qqe ch. ;<br><b>      2</b> en s’ajustant à : πρὸς τοῖς ὤμοις εἶναι, XÉN. <i>Cyr. 1, 6, 31,</i> s’adapter aux épaules ;<br><b>      3</b> en face de, devant : πρὸς τοῖς θεσμοθέταις λέγειν, DÉM. <i>487, 8,</i> parler devant les thesmothètes ; ὅσα γέγονε πρὸς τοῖς κριταῖς, DÉM. <i>520, 22,</i> tout ce qui s’est passé devant les juges ;<br><b>      4</b> outre (<i>litt</i>. en touchant à, à la suite de) : ἄασάν μ' ἕταροί τε κακοί, πρὸς τοῖσί τε ὕπνος, OD. <i>10, 68,</i> ce qui m’a perdu ce sont mes imprudents compagnons et en outre le sommeil ; δέκα μῆνες πρὸς ἄλλοις πέντε, SOPH. <i>Tr. 45,</i> dix mois outre cinq autres ; ἄλλους πρὸς ἑαυτῷ, THC. <i>1, 90,</i> d’autres outre lui-même ; πρὸς τούτοις, HDT. <i>2, 51, ou</i> πρὸς τούτῳ, HDT. <i>1, 31, 41,</i> outre cela ; πρὸς τοῖς ἄλλοις, THC. <i>2, 61, etc</i>. outre le reste ; πρὸς τοῖς αὑτοῦ καὶ τὰ τῶν ἄλλων προσαναλίσκειν, DÉM. <i>40, 58 Baiter-Sauppe,</i> outre son bien perdre aussi celui des autres ;<br><b>   III</b> <i>acc</i>. vers, <i>d’ord. avec mouv. :</i> πέμπειν προτὶ ἄστυ, IL. <i>3, 116,</i> envoyer vers la ville ; ὀτρύνειν ποτὶ δῶμα, OD. <i>17, 75,</i> pousser vers la maison ; ἰέναι πρὸς Ὄλυμπον, IL. <i>1, 420,</i> aller vers l’Olympe ; ῥίπτειν ποτὶ νέφεα, OD. <i>8, 374,</i> jeter vers les nuages ; βάλλειν ποτὶ πέτρας, OD. <i>12, 71, etc</i>. lancer contre les rochers ; <i>de même avec les verbes de mouv</i>. ἔρχεσθαι, ἄγειν, <i>etc</i>. IL. <i>13, 538, 657 ; 14, 432 ; 17, 193 ;</i> OD. <i>7, 2, etc. ; avec des verbes de repos, mais impliquant l’idée d’un mouvement antérieur :</i> πρὸς τὰ ἱερὰ παρεῖναι, XÉN. <i>Cyr. 3, 3, 34,</i> venir assister au sacrifice ; ἐρείδειν πρὸς τεῖχος, IL. <i>22, 112,</i> appuyer contre un mur ; στῆσαι πρὸς κίονα, OD. <i>1, 127,</i> dresser contre une colonne ; ποτὶ βωμὸν ἵζεσθαι, OD. <i>22, 334,</i> s’asseoir près de l’autel ; πρὸς γοῦνά τινος καθίζεσθαι, OD. <i>18, 395,</i> s’asseoir devant les genoux (<i>càd</i>. aux pieds) de qqn ; <i>avec des verbes de repos, mais impliquant l’idée de direction vers :</i> κλαίειν πρὸς οὐρανόν, IL. <i>8, 364,</i> pleurer vers le ciel ; ἀκτὴ τῆς Σικελίης πρὸς Τυρσηνίην τετραμμένη, HDT. <i>6, 22,</i> le rivage de la Sicile tourné vers la Tyrrhénie ; ἰδεῖν πρός τινα, OD. <i>12, 244,</i> avoir les yeux tournés vers qqn ; ὁρᾶν <i>ou</i> ἀποϐλέπειν πρός τι, ESCHL. <i>Suppl. 725, etc.,</i> avoir les yeux tournés vers qqe ch. ; ναίειν πρὸς ἠῶ τ' ἠέλιόν τε, OD. <i>13, 240,</i> habiter les régions qui s’étendent dans la direction de l’aurore et du soleil ; πρὸς ἠῶ τε καὶ ἡλίου ἀνατολάς, HDT. <i>1, 201,</i> du côté de l’orient et des régions où se lève le soleil ; <i>avec idée d’hostilité, càd</i>. contre : πρὸς Τρῶας μάχεσθαι, IL. <i>17, 471,</i> combattre contre les Troyens ; πρὸς στῆθος βάλλειν, IL. <i>4, 108,</i> frapper à la poitrine ; ἰέναι πρὸς τοὺς πολεμίους, XÉN. <i>An. 2, 6, 10,</i> marcher contre l’ennemi ; ἡ πρὸς αὐτὸν ἐπιϐουλή, XÉN. <i>An. 1, 1, 8,</i> le complot contre lui ; ἡ πρός τινα ἔχθρα, ESCHL. <i>Pr. 492, etc</i>. l’inimitié contre qqn ; πρὸς δαίμονα, IL. <i>17, 98, 104,</i> contre la volonté divine ; ὁ πρὸς Λεπτίνην λόγος, DÉM. <i>Lept</i>. le discours contre Leptine, <i>pour marquer l’idée d’une simple réponse,</i> κατά τινος <i>marquant l’idée d’une accusation ; — avec idée de temps :</i> πρὸς ἑσπέραν, XÉN. <i>Hell. 4, 3, 22 ; An. 4, 5, 21,</i> vers le soir ; πρὸς ὄρθρον, AR. <i>Lys. 1089,</i> vers le point du jour ; πρὸς ἕω, AR. <i>Eccl. 312 ;</i> πρὸς ἠῶ, THCR. <i>Idyl. 18, 55,</i> vers l’aurore ; πρὸς ἡμέραν, PLAT. <i>Conv. 223</i> c, vers le jour ; πρὸς τὸ παρόν, LUC. <i>Sat. 18, etc</i>. pour le moment ; <i>à ce sens se rattachent les divers emplois de</i> πρός <i>avec idée de tendance, marqués en français par les prépos</i>. à <i>ou</i> avec : ἀγορεύειν, εἰπεῖν πρός τινα, IL. <i>3, 155 ; 5, 274, etc</i>. parler à qqn ; ἀγγέλλειν πρός τινα, ESCHL. <i>Ch. 267 ;</i> XÉN. <i>An. 1, 7, 13,</i> annoncer à qqn ; ἀμείϐεσθαι πρός τινα, ἀποκρίνεσθαι πρός τινα, HDT. <i>8, 60, etc</i>. répliquer à qqn, répondre à qqn ; <i>avec un subst</i>. ἡ πρός τινα ξυμμαχία, THC. <i>5, 22,</i> l’alliance avec qqn ; ἡ πρός τινα φιλία, XÉN. <i>Cyr. 3, 1, 39,</i> l’amitié avec qqn ; — à l’égard de, pour : φρονεῖν τὰ πρός τινα, XÉN. <i>An. 7, 7, 30,</i> avoir souci des intérêts de qqn ; πρός τινα ἔχειν τὴν γνώμην, XÉN. <i>An. 2, 5, 29,</i> avoir l’esprit porté vers qqn, être bien disposé pour qqn ; τὰ Κύρου οὕτως ἔχει πρὸς ἡμᾶς ὥσπερ τὰ ἡμέτερα πρὸς ἐκεῖνον, XÉN. <i>An. 1, 3, 9,</i> les dispositions de Cyrus sont les mêmes pour nous que les nôtres pour lui ; τὰ πρὸς τοὺς θεούς, SOPH. <i>Ph. 1441,</i> ce qui concerne les dieux ; τὰ πρὸς τὸν βασιλέα, DÉM. <i>178, 22,</i> nos relations avec le grand roi ; οὐδὲν ἐμοὶ πρὸς ἐκείνους, ISOCR. <i>4, 12 Baiter-Sauppe,</i> il n’y a rien de commun entre eux et moi ; ὁ λόγος οὐδὲν πρὸς ἐμέ, DÉM. <i>240, 25,</i> le discours ne me concerne en rien ; <i>cf</i>. DÉM. <i>16, 10 ; 18, 60 ; 21, 44, etc. Baiter-Sauppe ;</i> τὰ πρὸς τὸν πόλεμον, XÉN. <i>An. 4, 3, 10,</i> les choses de la guerre ; — en vue de, à cause de : τὰ πρὸς τὸ δεῖπνον, PLUT. <i>Alex. 23,</i> ce qui concerne le souper, les préparatifs du souper ; πρός τι ; ATT. en vue de quoi ? pourquoi ? — en présence de, devant : γράφεσθαι πρὸς τοὺς θεσμοθέτας, DÉM. <i>1054, 17,</i> être cité devant les thesmothètes ; <i>cf</i>. DÉM. <i>529, 16 ; 892, 3 ;</i> μαρτυρῆσαι πρὸς τοὺς δικαστάς, PLUT. <i>Arist. 25,</i> apporter un témoignage devant les juges ; — en rapprochant de, par comparaison avec : πρὸς τὸν πατέρα, HDT. <i>3, 34,</i> par comparaison avec son père ; πρὸς τὰς παρούσας συμφοράς, SOPH. <i>Ph. 885,</i> ces symptômes joints aux souffrances présentes ; πρὸς τὸ κλέος αὐτῶν, THC. <i>1, 10,</i> en proportion de leur réputation ; οὐδέν ἐστί τις πρός τινα, PLAT. <i>Prot. 328</i> c, l’un n’a aucune valeur auprès de l’autre, <i>càd</i>. en comparaison avec l’autre ; οὐδαμοῦ ἐστί τις παρά τινι πρός τινα, XÉN. <i>Mem. 1, 2, 52,</i> qqn n’a aucune valeur aux yeux de qqn en comparaison avec un autre ; πρὸς τὰς μεγίστας καὶ ἐλαχίστας ναῦς τὸ μέσον σκοπεῖν, THC. <i>1, 10,</i> prendre la moyenne entre les plus grands et les plus petits vaisseaux ; — en se conformant à, selon, d’après : πρὸς αὐλὸν ὀρχεῖσθαι, XÉN. <i>An. 5, 9, 5,</i> danser au son de la flûte ; πρὸς τὰς παρούσας πημονὰς ὀρθῶς φρονεῖν, ESCHL. <i>Pr. 1002,</i> avoir des sentiments conformes aux souffrances présentes ; πρὸς τὴν δύναμιν, DÉM. <i>199, 8,</i> selon son pouvoir ; πρὸς τὴν ἀξίαν, XÉN. <i>Cyr. 8, 4, 29,</i> selon la valeur ; πρὸς ταῦτα, PLAT. <i>Ap. 30</i> b, d’après cela. <i>À ce sens se rattachent les locutions formées de</i> πρός <i>avec un subst. ou un adj. employé substantiv. équivalentes à un adv. :</i> πρὸς βίαν, ESCHL. <i>Eum. 5,</i> selon la force, par force ; πρὸς ἀνάγκην, ESCHL. <i>Pers. 569,</i> par nécessité ; πρὸς ἡδονήν, THC. <i>2, 65, etc</i>. pour être agréable ; μήτε πρὸς ἔχθραν μήτε πρὸς χάριν, DÉM. <i>90, 1,</i> ni par inimitié ni par bienveillance ; πρὸς καιρόν, SOPH. <i>Ph. 1263,</i> au moment opportun ; πρὸς πάντα, XÉN. <i>Cyr. 3, 3, 20,</i> en tout, absolument.<br><span><b><span class=\"arrow\"></span><br>   I</b> πρός <i>se place qqf. en poésie après son rég</i>. IL. <i>17, 419 ;</i> ESCHL. <i>Pr. 653, Sept. 485 ;</i> SOPH. <i>O.R. 178, 525 ;</i> EUR. <i>Or. 9, etc. ;</i><br><b>   II</b> <i>poét</i>. προτί (<i>v. ci-dessus</i>) ;<br><b>   III</b> <i>en compos</i>. πρός <i>signifie :</i><br><b>      1</b> vers, à (<i>v</i>. προσάγω, προσέρχομαι, <i>etc</i>.) ;<br><b>      2</b> auprès (<i>v</i>. προόσειμι¹, <i>etc</i>.) ;<br><b>      3</b> en outre, encore (<i>v</i>. προσαδικέω, προστίθημι, <i>etc.) ; p. suite avec idée de :</i> addition, connexion (<i>v</i>. πρόσειμι, προσγίγνομαι, <i>etc</i>.) ;<br><b>      4</b> excessivement, tout à fait (<i>v</i>. προσθύμιος).<br><span><b>Étym</b>. <i>indo-europ</i>. *proti-, en face de ; <i>cf. sscr</i>. práti ; πρός <i>par assibilation de</i> *πρότϳ- <i>devant voyelle ; v</i>. πρό.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς - πρός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Préposition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n702 fois dans 653 versets de 26 livres bibliques (NT)\n<ul>\n<li>Matthieu (44)</li>\n<li>Marc (66)</li>\n<li>Luc (163)</li>\n<li>Jean (100)</li>\n<li>Actes (134)</li>\n<li>Romains (18)</li>\n<li>1 Corinthiens (24)</li>\n<li>2 Corinthiens (33)</li>\n<li>Galates (9)</li>\n<li>Ephésiens (16)</li>\n<li>Philippiens (4)</li>\n<li>Colossiens (6)</li>\n<li>1 Thessaloniciens (13)</li>\n<li>2 Thessaloniciens (4)</li>\n<li>1 Timothée (5)</li>\n<li>2 Timothée (7)</li>\n<li>Tite (5)</li>\n<li>Philémon (3)</li>\n<li>Hébreux (19)</li>\n<li>Jacques (3)</li>\n<li>1 Pierre (3)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (8)</li>\n<li>2 Jean (3)</li>\n<li>3 Jean (1)</li>\n<li>Apocalypse (9)</li>\n</ul>\n</td></tr>\n</table>","G4315":"<h1>prosabbaton</h1>\n<p>Strong n° 4315 <i>Prononciation [pros-ab'-bat-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>le jour avant le sabbat, le vendredi</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·σάϐϐατος, ος, ον</b> <span>[ϐᾰ]</span> qui précède le sabbat, NONN. <i>Jo. 19, 14 ;</i> τὸ προσάϐϐατον, NT. <i>Marc. 15, 42,</i> la veille du sabbat.<br><span><b>Étym</b>. προ, σάϐϐατον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσαββατον - προσάββατον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4316":"<h1>prosagoreuo</h1>\n<p>Strong n° 4316 <i>Prononciation [pros-ag-or-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>parler à, s'adresser, aborder, saluer</li>\n<li>spéc. s'adresser par un nom, appeler par le nom</li>\n<li>donner un nom en public, titrer, appeler, baptiser</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσαγορεύω</b> <span>[ᾰ]</span> adresser la parole à, <i>d’où :</i><br><b>      1</b> parler à, dire à : τινὰ χαίρειν, PLAT. <i>Leg. 771</i> a, <i>etc., litt</i>. dire à qqn de se réjouir, <i>càd</i>. saluer qqn ; <i>p. suite, abs</i>. saluer, <i>acc</i>. HDT. <i>1, 134 ; 2, 80 ;</i> PLAT. <i>Leg. 823</i> d, <i>etc. ; au pass</i>. THC. <i>6, 16 ; en parl. de salutations par lettres,</i> PLAT. <i>Ep. 315</i> b ;<br><b>      2</b> appeler de tel <i>ou</i> tel nom : τὸν Ἀγαμέμνονα πρ. ποιμένα λαῶν, XÉN. <i>Mem. 3, 2, 1,</i> appeler Agamemnon un pasteur de peuples ; τινὰ ὀνόματι, PLAT. <i>Pol. 291</i> e, appeler qqn par son nom ; <i>particul</i>. appeler d’un titre : βασιλέα πρ. τινά, PLUT. <i>Æmil. 8,</i> saluer qqn du titre de roi ; τοῦτο τοὔνομα πρ. σφᾶς αὐτούς, POL. <i>1, 8, 1,</i> s’appeler eux-mêmes de ce nom ; <i>avec une prop. inf. :</i> τι ἀγαθὸν εἶναι, PLAT. <i>Phil. 13</i> b, dire qu’une chose mérite le nom de bien ;<br><b>      3</b> <i>p. suite,</i> attribuer, assigner : τινί τι, PLAT. <i>Theæt. 147</i> d, qqe ch. à qqn ;<br><b>      4</b> <i>abs</i>. mentionner, <i>acc</i>. PLAT. <i>Leg. 719</i> e.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-αγορευω - προσαγορεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4317":"<h1>prosago</h1>\n<p>Strong n° 4317 <i>Prononciation [pros-ag'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mener, conduire, apporter\n<ol type=\"a\">\n<li>ouvrir une voie d'accès, pour quelqu'un à Dieu\n<ol>\n<li>rendre acceptable à Dieu</li>\n</ol>\n</li>\n<li>dans un sens judiciaire, convoquer, appeler (à procès ou châtiment)</li>\n</ol>\n</li>\n<li>s'approcher de\n<ol type=\"a\">\n<li>la terre vers laquelle va un marin semble s'approcher de lui</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·άγω</b> <span>(<i>f</i>. προσάξω, <i>ao</i>. προσῆξα, <i>ao.2</i> προσήγαγον, <i>pf</i>. προσῆχα)</span> <span>[ᾰγ]</span><br><b>A <i>tr</i>.<br>   I</b> (πρός, vers) conduire vers, <i>d’où :</i><br><b>      1</b> amener : στρατιὰν πρὸς πολεμίους, XÉN. <i>Cyr. 1, 6, 43,</i> conduire une armée à l’ennemi ; τῇ Ποτιδαίᾳ στρατόν, THC. <i>1, 64,</i> conduire une armée contre Potidée ; τῷ Κύρῳ τοὺς αἰχμαλώτους, XÉN. <i>Cyr. 3, 3, 12,</i> conduire les prisonniers à Cyrus ; πρὸς τὸν δῆμον, THC. <i>5, 61, etc</i>. amener devant le peuple ; πρ. τοὺς πρέσϐεις, DÉM. <i>234, 20,</i> amener, <i>càd</i>. introduire les ambassadeurs ; <i>particul</i>. introduire à la cour d’un roi, XÉN. <i>Cyr. 1, 3, 8 (cf</i>. προσαγωγή, προσαγωγεύς) ; <i>abs</i>. introduire, <i>càd</i>. admettre (parmi les citoyens) <i>acc</i>. IS. <i>70, 27 ;</i><br><b>      2</b> apporter : φόρον, THC. <i>2, 97,</i> un tribut ; τὰς εἰσφοράς, POL. <i>5, 30, 5,</i> les impôts ; δῶρά τινι, HH. <i>Ap. 272,</i> apporter des présents à qqn ; <i>fig. càd</i>. causer, procurer, être cause de, <i>acc. :</i> πῆμα, OD. <i>17, 446, litt</i>. apporter une douleur ; <i>cf</i>. PD. <i>I. 6, 101, etc. ;</i><br><b>      3</b> présenter, offrir : παροψίδας τινί, XÉN. <i>Cyr. 1, 3, 4,</i> présenter des mets à qqn ; ὕμνους ἢ χορείας τῳ θεῶν, PLAT. <i>Leg. 799</i> b, offrir des hymnes <i>ou</i> des chœurs de danse à qqn des dieux ; τινὶ ὅρκον, HDT. <i>6, 74,</i> déférer le serment à qqn, l’inviter à le prêter ;<br><b>      4</b> faire venir : ἁρμαμάξας, XÉN. <i>Cyr. 4, 3, 1,</i> des chariots ; πάντα ἱκανά, XÉN. <i>Cyr. 5, 2, 5,</i> tous les approvisionnements nécessaires, <i>càd</i>. des vivres ; approcher : τὴν χεῖρά τινι, AR. <i>Lys. 893,</i> porter la main sur qqn ; μηχανὰς τῇ πόλει, THC. <i>2, 76,</i> approcher les machines de siège de la ville ; <i>fig</i>. ἀνάγκας τινί, THC. <i>1, 99,</i> employer contre qqn des mesures de contrainte ; φόϐον, THC. <i>2, 97,</i> employer la menace pour effrayer ; πολλῶν φόϐων προσαγομένων, XÉN. <i>An. 4, 1, 23,</i> beaucoup de moyens d’épouvante étant mis en mouvement ;<br><b>      5</b> <i>fig</i>. amener par la parole : τινὰ πρὸς μάθησιν, ARSTT. <i>Pol. 7, 17, 4,</i> amener qqn à apprendre ; <i>d’où</i> pousser à, SOPH. <i>Ph. 236 ;</i> EUR. <i>Andr. 27 ; au pass</i>. se laisser amener à, <i>dat. :</i> οἴκτῳ, THC. <i>3, 47,</i> à la pitié ; <i>cf</i>. THC. <i>3, 95, etc. ;</i><br><b>   II</b> (πρός, outre) apporter en outre, ajouter (une prescription) <i>avec l’inf</i>. EPHOR. (MACR. <i>Sat. 5, 18</i>) ;<br><b>B <i>intr</i>.<br>      1</b> s’avancer, marcher en avant : πρὸς πολεμίους, XÉN. <i>An. 1, 10, 9 ; 4, 8, 11, etc</i>. marcher contre l’ennemi (<i>litt</i>. πρ. τὸν στρατόν, faire avancer l’armée, <i>etc</i>.) ;<br><b>      2</b> <i>t. de mar</i>. aborder (<i>litt</i>. πρ. τὴν ναῦν, conduire le vaisseau vers le rivage) POL. <i>1, 54, 5 ;</i> Ῥόδῳ, APD. <i>2, 1, 4,</i> à Rhodes ; <i>abs</i>. se laisser conduire, THC. <i>3, 43 ;</i> XÉN. <i>Hell. 6, 1, 7 ; p. suite,</i> se porter vers, s’attacher à qqn, <i>dat</i>. THC. <i>2, 77 ; 3, 63 ; 4, 87 ;</i><br><b>      3</b> s’approcher (<i>litt</i>. πρ. ἑαυτόν, se porter en avant) : κώμῃ, ARR. <i>An. 2, 3, 4,</i> d’un village ; τοῖς βασιλεῦσι, PLUT. <i>M. 800</i> a, <i>etc</i>. approcher les rois ; <i>fig</i>. τοῖς τεσσαράκοντα ἔτεσι, PLUT. <i>Pomp. 46,</i> approcher de la quarantaine ; <i>abs</i>. s’approcher, THCR. <i>Idyl. 15, 78 ; fig</i>. πόταγε (<i>dor</i>.) THCR. <i>Idyl. 1, 62,</i> approche ! <i>càd</i>. courage, à l’œuvre ! ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. προσάξομαι, <i>ao.2</i> προσηγαγόμην)</span><br><b>   I</b> approcher de soi, attirer à soi, <i>d’où :</i><br><b>      1</b> presser dans ses bras : πρ. τινα, XÉN. <i>Cyr. 7, 5, 39,</i> attirer qqn vers soi ; <i>particul</i>. pour l’embrasser, AR. <i>Av. 141 ;</i> XÉN. <i>Cyr. 8, 4, 26, etc. ; p. opp. à</i> ἀπωθεῖν, PLAT. <i>Rsp. 439</i> b ; <i>en parl. d’un cheval qu’on attire par la bride,</i> XÉN. <i>Eq. 9, 5 ; en parl. de choses :</i> τὰ ναυάγια, THC. <i>8, 106,</i> attirer à soi, <i>d’où</i> recueillir les débris de navires après une bataille navale ; ὀστᾶ, EUR. <i>Suppl. 949,</i> recueillir des ossements ; <i>p. suite,</i> se procurer (les choses dont on a besoin) XÉN. <i>Vect. 1, 7 ; fig</i>. attirer sur soi : ὄμματα, XÉN. <i>Conv. 1, 9,</i> les regards ;<br><b>      2</b> <i>fig</i>. attirer vers soi, amener à soi, se concilier : πρ. τινα, HDT. <i>2, 172 ;</i> XÉN. <i>Mem. 3, 4, 9 ;</i> PLAT. <i>Leg. 695</i> d, <i>etc</i>. se concilier qqn, se le rendre favorable, le faire entrer dans son parti ; τινα χρήμασι, PLAT. <i>Leg. 695</i> d ; <i>ou</i> ἀπάτῃ, THC. <i>3, 42,</i> gagner qqn à prix d’argent <i>ou</i> par fraude ;<br><b>      3</b> amener par sa parole <i>ou</i> ses efforts, <i>d’où</i> déterminer : τινα <i>avec l’inf</i>. qqn à (faire qqe ch.) SOPH. <i>O.R. 131 ;</i> EUR. <i>Ion 659 ;</i><br><b>      4</b> amener dans son intérêt (au tribunal), <i>càd</i>. produire : μάρτυρα, PLUT. <i>M. 1049</i> b, un témoin ;<br><b>      5</b> diriger vers : τὸν πόνον καὶ τὸν χρόνον, POL. <i>29, 6, 14,</i> appliquer sa peine et son temps à (qqe ch.).<br><span><b><span class=\"arrow\"></span></b> <i>Prés. impér. dor</i>. πόταγε, THCR. <i>Idyl. l. c</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-αγω - προσάγω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4318":"<h1>prosagoge</h1>\n<p>Strong n° 4318 <i>Prononciation [pros-ag-ogue-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>l'action d'apporter à, de se déplacer vers</li>\n<li>accès, entrée, approche\n<ol type=\"a\">\n<li>à Dieu, c.à.d. cette relation avec Dieu par laquelle nous lui sommes acceptable et avons l'assurance qu'il est favorablement disposé envers nous</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσαγωγή, ῆς (ἡ)</b> <span>[ᾰ]</span><br><b>A</b> <i>tr</i>. action d’amener vers, <i>d’où :</i><br><b>      1</b> introduction (auprès de qqn) XÉN. <i>Cyr. 7, 5, 45 ;</i><br><b>      2</b> action d’approcher (de la nourriture vers sa bouche, ARSTT. <i>P.A. 4, 10, 28 ;</i> des machines de siège, <i>etc</i>. POL. <i>1, 48, 2, etc</i>.) ;<br><b>      3</b> action d’amener (des alliés, <i>etc</i>.) THC. <i>1, 82 ;</i><br><b>B</b> <i>intr. :</i><br><b>      1</b> action de s’approcher : ἐκ προσαγωγῆς, ARSTT. <i>Meteor. 1, 13, 22, etc</i>. en avançant graduellement, peu à peu ; <i>joint à</i> κατὰ μικρόν, ARSTT. <i>Pol. 5, 6, 17 ; p. opp. à</i> ἁθρόως, ARSTT. <i>Pol. 5, 8, 12 ; particul</i>. action d’aller à une cérémonie, <i>d’où</i> cérémonie, HDT. <i>2, 58 ;</i><br><b>      2</b> accès, abord ; <i>particul</i>. lieu de débarquement, POL. <i>10, 1, 6 ;</i> DS. <i>13, 46 ;</i> PLUT. <i>Æmil. 13</i>.<br><span><b>Étym</b>. προσάγω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-αγωγη - προσαγωγή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Ephésiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4319":"<h1>prosaiteo</h1>\n<p>Strong n° 4319 <i>Prononciation [pros-ahee-teh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>demander pour obtenir</li>\n<li>s'approcher de quelqu'un avec supplications</li>\n<li>demander l'aumône</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·αιτέω-ῶ :<br>      1</b> demander en outre encore plus de, <i>acc</i>. PD. <i>fr. 166 ;</i> ESCHL. <i>Ch. 401 ;</i> μισθόν, XÉN. <i>An. 1, 3, 21,</i> réclamer une solde plus forte ;<br><b>      2</b> demander vers, <i>càd</i>. avec insistance, <i>d’où</i> prier, supplier : τινα, HDT. <i>3, 14 ;</i> ISOCR. <i>156</i> e, <i>etc</i>. qqn ; <i>particul</i>. mendier : τι, EUR. <i>Hel. 791 ;</i> AR. <i>Lys. 1141,</i> mendier qqe ch. ; τινά τι, EUR. <i>Hel. 512 ;</i> XÉN. <i>An. 7, 3, 21,</i> mendier qqe ch. à qqn ; <i>abs</i>. AR. <i>Ach. 429, 452 ;</i> XÉN. <i>Mem. 1, 2, 29, etc. ;</i> PLAT. <i>Conv. 203</i> b, <i>etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-αιτεω - προσαιτέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4320":"<h1>prosanabaino</h1>\n<p>Strong n° 4320 <i>Prononciation [pros-an-ab-ah'-ee-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>aller plus loin</li>\n<li>monter plus haut (à une place d'honneur)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·αναϐαίνω</b> <span>(<i>f</i>. -αναϐήσομαι, <i>ao.2</i> -ανέϐην, <i>etc</i>.)</span><br><b>      1</b> monter vers, <i>avec</i> πρός <i>et l’acc</i>. ARSTT. <i>H.A. 9, 21, etc. ; abs</i>. monter, grossir, <i>en parl. d’un fleuve,</i> POL. <i>3, 72, 4 ; fig</i>. remonter jusqu’à : τῷ Ῥομύλῳ, PLUT. <i>Thes. 1,</i> remonter jusqu’à Romulus ;<br><b>      2</b> monter encore, grossir une troupe, XÉN. <i>Hipp. 1, 12</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-αναβαινω - προσαναβαίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4321":"<h1>prosanalisko</h1>\n<p>Strong n° 4321 <i>Prononciation [pros-an-al-is'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>dépenser en excès</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·αναλίσκω</b> <span>[ᾰνᾱ]</span> dépenser <i>ou</i> épuiser en outre, XÉN. <i>An. 6, 2, 8 ;</i> PLAT. <i>Prot. 311</i> d ; DÉM. <i>460, 2 ; 1025, 20, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-αναλισκω - προσαναλίσκω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4322":"<h1>prosanapleroo</h1>\n<p>Strong n° 4322 <i>Prononciation [pros-an-ap-lay-ro'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>remplir par ajout à, compléter, suppléer à l'insuffisance de</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·αναπληρόω-ῶ</b>, suppléer à l’insuffisance de, compléter, suppléer, combler, <i>acc</i>. ARSTT. <i>Pol. 1, 8, 8 ;</i> DS. <i>5, 71 ;</i> NT. <i>2Cor. 9, 12 ;</i><br><b><i>Moy.</i></b> <i>m. sign</i>. PLAT. <i>Men. 84</i> d.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-ανα-πληροω - προσαναπληρόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4323":"<h1>prosanatithemi</h1>\n<p>Strong n° 4323 <i>Prononciation [pros-an-at-ith'-ay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>poser par dessus en addition à</li>\n<li>poser sur soi-même en ajout\n<ol type=\"a\">\n<li>entreprendre en outre</li>\n<li>s'imposer à un autre en allant vers lui</li>\n<li>se rendre vers un autre dans le but de le consulter</li>\n<li>consulter, prendre un conseil</li>\n</ol>\n</li>\n<li>communiquer, transmettre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·ανατίθημι</b> <span>(<i>f</i>. -αναθήσω, <i>ao</i>. -ανέθηκα, <i>etc</i>.)</span> <span>[τῐ]</span> reporter à, attribuer à, <i>rég. ind. au dat</i>. ES. <i>84.3 Chambry ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> se charger en outre de, <i>acc</i>. XÉN. <i>Mem. 2, 1, 8 ;</i><br><b>      2</b> contribuer : τινί τι, NT. <i>Gal. 2, 6,</i> en qqe ch. pour qqn ;<br><b>      3</b> en référer à, se confier <i>ou</i> demander conseil à, <i>dat</i>. DS. <i>17, 116 ;</i> NT. <i>Gal. 1, 16 ;</i> LUC. <i>J. tr. 1</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-ανα-τιθημι - προσανατίθημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Galates (2)</li>\n</ul>\n</td></tr>\n</table>","G4324":"<h1>prosapeileo</h1>\n<p>Strong n° 4324 <i>Prononciation [pros-ap-i-leh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ajouter des menaces, menacer davantage</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·απειλέω-ῶ</b> <span>[ᾰ]</span> menacer encore <i>ou</i> en outre, DÉM. <i>544, 26</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-απειλεω - προσαπειλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4325":"<h1>prosdapanao</h1>\n<p>Strong n° 4325 <i>Prononciation [pros-dap-an-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>dépenser en outre, par surcroît</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·δαπανάω-ῶ</b> <span>[ᾰᾰ]</span> dépenser en outre, LUC. <i>Ep. sat. 39 ;</i><br><b><i>Moy.</i></b> <i>m. sign</i>. THÉM. <i>289</i> b.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-δαπαναω - προσδαπανάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4326":"<h1>prosdeomai</h1>\n<p>Strong n° 4326 <i>Prononciation [pros-deh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>vouloir en outre, avoir besoin en plus</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·δέομαι, v. προσδέω²</b>.<br><br>\n<b>προσ·δέω :<br>   I</b> <i>act. (seul. prés. ind. et inf</i>.) avoir encore besoin de, <i>gén</i>. EUR. <i>H.f. 90 ; d’ord. impers</i>. προσδεῖ, besoin est : τινί τινος, THC. <i>3, 13 ;</i> XÉN. <i>An. 3, 2, 24,</i> besoin est à qqn de qqe ch. ; <i>avec l’inf</i>. PLAT. <i>Conv. 205</i> a, il faut encore, il est encore besoin de, <i>etc. ;</i><br><b>   II</b> <span><i>Moy</i>. προσδέομαι</span> <span>(<i>f</i>. δεήσομαι, <i>ao</i>. προσεδεήθην, <i>etc</i>.)</span><br><b>      1</b> avoir encore besoin : τινος, THC. <i>1, 102, etc. ;</i> XÉN. <i>An. 5, 9, 24, etc. ;</i> PLAT. <i>Phil. 63</i> c, <i>etc</i>. de qqe ch. ; τινος εἴς τι, XÉN. <i>Cyr. 6, 2, 39,</i> d’une ch. en vue d’une autre ; τι, XÉN. <i>Cyr. 1, 3, 17,</i> avoir besoin de qqe autre ch. ; <i>avec un inf</i>. avoir encore besoin de, XÉN. <i>Hell. 7, 4, 35 ;</i><br><b>      2</b> <i>p. suite,</i> demander <i>ou</i> solliciter encore : τινός τι, HDT. <i>6, 35 ; ou</i> τινός τινος, HDT. <i>5, 40,</i> qqe ch. de qqn ; τινος <i>avec l’inf</i>. HDT. <i>8, 40,</i> qqn de faire qqe ch. ; <i>avec une prop. inf</i>. HDT. <i>1, 36 ; 6, 41,</i> prier encore <i>ou</i> en outre que, <i>etc. ;</i><br><b>   III</b> <i>pass. impers</i>. προσδεῖται, besoin est, XÉN. <i>Ages. 1, 5 ;</i> PLAT. <i>Demod. 384</i> b ; δοκεῖ σοι προμηθείας προσδεῖσθαι ὅπως, PLAT. <i>2 Alc. 188</i> b, il semble que tu aies besoin de prévoyance pour que, <i>etc</i>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-δεομαι - προσδέομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4327":"<h1>prosdechomai</h1>\n<p>Strong n° 4327 <i>Prononciation [pros-dekh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>recevoir pour soi-même, laisser entrer, donner accès à soi-même\n<ol type=\"a\">\n<li>admettre, recevoir pour relation et camaraderie</li>\n<li>recevoir quelqu'un (venant de quelque lieu)</li>\n<li>accepter (ne pas rejeter) une chose offerte</li>\n</ol>\n</li>\n<li>s'attendre à : l'accomplissement des promesses</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·δέχομαι :<br>   I</b> recevoir, accueillir (un hôte, <i>etc.) acc</i>. ESCHL. <i>Eum. 656 ;</i> SOPH. <i>O.R. 1428, etc. ;</i> EUR. <i>Ph. 1706, etc. ;</i> THC. <i>2, 12 ;</i> XÉN. <i>Cyr. 7, 5, 37, etc. ; particul</i>. admettre comme citoyen, accorder le droit de cité à, <i>acc</i>. PLAT. <i>Leg. 708</i> a ; DÉM. <i>1317, 6 ; particul. :</i><br><b>      1</b> faire bon accueil à, agréer volontiers (l’alliance, l’amitié de qqn, <i>etc</i>.) XÉN. <i>Hell. 7, 4, 2 ;</i> POL. <i>1, 16, 8, etc</i>. admettre un argument, une raison, PLAT. <i>Rsp. 485</i> c, <i>561</i> b ;<br><b>      2</b> supporter, accepter, <i>acc</i>. ARSTT. <i>H.A. 6, 23, 7, etc. ;</i><br><b>      3</b> se charger de, prendre sur soi, <i>acc</i>. POL. ;<br><b>      4</b> être capable de, <i>acc</i>. PLAT. <i>Phil. 15</i> b, <i>etc. ;</i><br><b>   II</b> attendre : σὴν ποτιδέγμενος (<i>ion</i>.) ὁρμήν, OD. <i>2, 403,</i> attendant ton élan, <i>càd</i>. ton impulsion ; <i>cf</i>. IL. <i>19, 234, 336 ;</i> OD. <i>2, 186 ;</i> espérer <i>ou</i> craindre, <i>acc</i>. THC. <i>4, 19 ;</i> SOPH. <i>Tr. 15, etc. ; avec une prop. inf</i>. HDT. <i>5, 34, etc. ;</i> XÉN. <i>Cyr. 4, 5, 22 ; avec</i> ὁπότ' ἄν <i>et l’opt</i>. IL. <i>7, 415 ; ou</i> εἰ <i>et l’opt</i>. OD. <i>23, 91 ; ou</i> εἰ <i>et l’indic</i>. CALL. <i>Dian. 147,</i> attendre que, attendre si ; <i>particul</i>. attendre de pied ferme, <i>acc</i>. POL. <i>2, 69, 6, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao</i>. προσεδέχθην <i>au sens pass</i>. DS. <i>15, 70. Ion</i>. προσδέκομαι, HDT. <i>1, 48, etc. ; épq. part</i>. ποτιδέγμενος, HOM. <i>ll. cc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-δεχομαι - προσδέχομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 14 versets de 8 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (5)</li>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>Philippiens (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (2)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G4328":"<h1>prosdokao</h1>\n<p>Strong n° 4328 <i>Prononciation [pros-dok-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>s'attendre à (que ce soit en pensées, en espérance, ou en crainte)</li>\n<li>chercher à, attendre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·δοκάω-ῶ</b>, attendre, s’attendre à : τι, ESCHL. <i>Pr. 1026 ;</i> SOPH. <i>Ph. 784,</i> à qqe ch. ; τινα, EUR. <i>Alc. 363,</i> attendre qqn ; <i>abs</i>. AR. <i>Th. 846, etc. ; avec l’inf. fut</i>. HDT. <i>1, 42, etc. ;</i> ESCHL. <i>Pr. 930, etc</i>. s’attendre à ce que, <i>etc. ; avec l’inf. ao. avec</i> ἄν, PLAT. <i>Crat. 438</i> e, <i>etc. ; ou sans</i> ἄν, ESCHL. <i>Ag. 674,</i> penser qu’une chose peut arriver ; <i>avec l’inf. prés</i>. XÉN. <i>An. 5, 9, 16 ;</i> PLAT. <i>Leg. 803</i> e, penser qu’une chose arrive ; <i>au pass</i>. τὸ προσδοκώμενον, EUR. <i>fr. 554 Nauck ;</i> LYS. <i>156, 7,</i> ce à quoi l’on s’attend, ce qu’on espère <i>ou</i> ce qu’on craint.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. προσδοκέω, HDT. <i>l. c., etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-δοκαω - προσδοκάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 15 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (6)</li>\n<li>Actes (5)</li>\n<li>2 Pierre (3)</li>\n</ul>\n</td></tr>\n</table>","G4329":"<h1>prosdokia</h1>\n<p>Strong n° 4329 <i>Prononciation [pros-dok-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>attente, expectative (que ce soit en bien ou en mal)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσδοκία, ας (ἡ)</b> attente (d’un bien, XÉN. <i>Cyr. 1, 6, 19 ;</i> DÉM. <i>319, 9, etc. ;</i> d’un mal, PLAT. <i>Lach. 198</i> b,<i>Tim. 70</i> c, <i>etc. ; en gén</i>. ARSTT. <i>P.A. 3, 6, 5, etc.) ; au plur</i>. DÉM. <i>348, 23 ;</i> DS. <i>20, 78 ;</i> προσδοκία ἦν μή, THC. <i>2, 93,</i> on craignait que, <i>etc. ; ou</i> μὴ οὐ, THC. <i>5, 14,</i> on craignait que… ne pas, <i>etc. ;</i> πρὸς τὴν προσδοκίαν, THC. <i>6, 63,</i> κατὰ τὴν προσδοκίαν, PLAT. <i>Soph. 264</i> b, selon l’attente, comme on s’y attendait ; παρὰ προσδοκίαν, D. PHAL. § <i>152,</i> contrairement à ce qu’on attendait.<br><span><b>Étym</b>. προσδοκάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσδοκια - προσδοκία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4330":"<h1>proseao</h1>\n<p>Strong n° 4330 <i>Prononciation [pros-eh-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>permettre à quelqu'un de s'approcher ou d'arriver</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·εάω-εῶ</b>, permettre en outre, NT. <i>Ap. 27, 7</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-εαω - προσεάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4331":"<h1>proseggizo</h1>\n<p>Strong n° 4331 <i>Prononciation [pros-eng-ghid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>s'approcher de très près</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·εγγίζω :<br>      1 <i>tr.</i></b> approcher : τί τινι, LUC. <i>Am. 53,</i> une chose d’une autre ;<br><b>      2 <i>intr.</i></b> s’approcher de, <i>dat</i>. ANTH. <i>7, 422 ;</i> DS. <i>3, 16 ; abs</i>. POL. <i>39, 1, 4</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-εγγιζω - προσεγγίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4332":"<h1>prosedreuo</h1>\n<p>Strong n° 4332 <i>Prononciation [pros-ed-ryoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être assis près de, siéger</li>\n<li>servir assidûment</li>\n<li>être au service de, ne pas quitter ses côtés, se consacrer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>παρ·εδρεύω</b> (<i>pf</i>. παρήδρευκα) :<br><b>      1</b> être assis <i>ou</i> siéger auprès de, <i>dat</i>. EUR. <i>Alc. 746 ;</i> POL. <i>29, 10, 11, etc. ;</i> DS. <i>14, 71 ; particul</i>. être assesseur, DÉM. <i>572, 10 ; avec le dat</i>. ISOCR. <i>192</i> a ;<br><b>      2</b> <i>t. de gr</i>. être voisin de la finale, être pénultième, DYSC. <i>Adv. 589, 5, etc. ; au pass</i>. être avoisiné dans la pénultième : τινι, ATH. <i>392</i> a, par qqe lettre.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσεδρευω - παρεδρεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4333":"<h1>prosergazomai</h1>\n<p>Strong n° 4333 <i>Prononciation [pros-er-gad'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>produire en outre</li>\n<li>faire un gain plus élevé par ouvrage ou commerce</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·εργάζομαι :<br>      1</b> faire <i>ou</i> accomplir en outre : τί τινι, HDT. <i>6, 61,</i> qqe ch. pour qqn ; τι τοῖς δεδραμένοις, EUR. <i>H.f. 1013,</i> faire qqe ch. de plus que ce qui est fait ; <i>p. suite</i> ajouter à, appliquer à : χρυσίον ἀγάλματι, PLUT. <i>Per. 31,</i> appliquer de l’or à une statue ;<br><b>      2</b> acquérir <i>ou</i> se procurer en outre par son travail, XÉN. <i>Hell. 3, 1, 28</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσεργαζομαι - προσεργάζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4334":"<h1>proserchomai</h1>\n<p>Strong n° 4334 <i>Prononciation [pros-er'-khom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>venir à, s'approcher de</li>\n<li>aller près de</li>\n<li>consentir à</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·έρχομαι</b> <span>(<i>ao.2</i> προσῆλθον, <i>etc</i>.)</span><br><b>A</b> aller vers <i>ou</i> auprès, <i>d’où :</i><br><b>   I</b> s’avancer, s’approcher, HDT. <i>1, 86, etc. ; particul</i>. πρ. Σωκράτει, XÉN. <i>Mem. 1, 2, 47,</i> fréquenter Socrate, suivre les leçons de Socrate ; γυναικί, XÉN. <i>Conv. 4, 38,</i> avoir commerce avec une femme ; τινι, ESCHL. <i>Eum. 285 ;</i> SOPH. <i>O.C. 1104, etc. ;</i> πρός τινα <i>ou</i> τι, HDT. <i>2, 121, etc</i>. de qqn <i>ou</i> de qqe ch. ; πέλας τινός, EUR. <i>Andr. 589 ; ou</i> ἐπί τινα, XÉN. <i>Hell. 6, 3, 3,</i> s’approcher de qqn ; τι, EUR. <i>Alc. 171, etc</i>. s’approcher de qqe ch. ; <i>fig. avec un suj. de chose</i> (événement, douleur, <i>etc</i>.) SOPH. <i>Ph. 788 ;</i> EUR. <i>Or. 857 ; particul. :</i><br><b>      1</b> s’avancer (en ennemi) : πρὸς ἱππέας, XÉN. <i>Cyr. 6, 2, 16,</i> marcher contre une troupe de cavalerie ;<br><b>      2</b> s’approcher, s’avancer : τοῖς θεοῖς, DC. <i>56, 9,</i> s’approcher des dieux en suppliant ; τῷ δήμῳ, DÉM. <i>229, 13 ; ou</i> πρὸς τὸν δῆμον, ESCHN. <i>85, 17,</i> s’avancer en public, se présenter au peuple pour parler ;<br><b>      3</b> entrer en arrangement, capituler, THC. <i>3, 59 ;</i><br><b>   II</b> se donner à, se mêler de, s’occuper de : τοῖς δημοσίοις πράγμασι, PLUT. <i>M. 1059</i> d ; πρὸς τὰ κοινά, DÉM. <i>312 fin ;</i> τῇ πολιτείᾳ, PLUT. <i>Cato mi. 12 ; ou</i> πρὸς τὴν πολιτείαν, DIN. <i>107, 1 ;</i> πρὸς τὴν πόλιν, DÉM. <i>1331, 18,</i> s’occuper des affaires publiques ;<br><b>   III</b> se comporter : πρός τινα, DÉM. <i>614 fin ; 755, 5,</i> envers qqn ;<br><b>B</b> venir en outre, <i>d’où</i> être un produit, un revenu, etc. HDT. <i>7, 144 ;</i> XÉN. <i>Mem. 3, 6, 12 ;</i> DÉM. <i>141, 16</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσερχομαι - προσέρχομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n86 fois dans 84 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (50)</li>\n<li>Marc (5)</li>\n<li>Luc (10)</li>\n<li>Jean (1)</li>\n<li>Actes (10)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (8)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4335":"<h1>proseuche</h1>\n<p>Strong n° 4335 <i>Prononciation [pros-yoo-khay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prière adressée à Dieu</li>\n<li>un lieu mis à part ou convenable pour offrir la prière\n<ol type=\"a\">\n<li>une synagogue</li>\n<li>un lieu en plein air où les Juifs avaient coutume de prier, au dehors des cités qui n'avaient pas de synagogue\n<ol>\n<li>de tels lieux se trouvaient sur la berge de rivières ou en bordure de mer, pour trouver l'eau nécessaire au lavage des mains avant la prière</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσευχή, ῆς (ἡ) :<br>      1</b> prière, SPT. <i>Esaï. 56, 7 ;</i> NT. <i>Matth. 21, 13 ;</i><br><b>      2</b> lieu de prière, temple, JOS. <i>A.J. 14, 10, 23 :</i> PHIL. <i>2, 523, etc. ;</i> NT. <i>Ap. 16, 10</i>.<br><span><b>Étym</b>. προσεύχομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-ευχη - προσευχή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n37 fois dans 37 versets de 15 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (2)</li>\n<li>Luc (3)</li>\n<li>Actes (9)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (2)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Timothée (2)</li>\n<li>Philémon (2)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (2)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G4336":"<h1>proseuchomai</h1>\n<p>Strong n° 4336 <i>Prononciation [pros-yoo'-khom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>offrir des prières, prier</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·εύχομαι :<br>      1</b> adresser une prière : τῷ θεῷ, ESCHL. <i>Ag. 317 ;</i> PLAT. <i>Conv. 220</i> d ; <i>ou</i> τὸν θεόν, EUR. <i>Tr. 887 ;</i> AR. <i>Pl. 958,</i> à la divinité ; <i>avec un inf</i>. XÉN. <i>Cyr. 2, 1, 1 ;</i> PLAT. <i>Criti. 106</i> a, demander aux dieux de, <i>etc. ; abs</i>. adorer, prier, supplier, HDT. <i>1, 48 ;</i> ESCHL. <i>Pr. 937 ; en prose att</i>. XÉN. <i>Mem. 3, 8, 10 ;</i><br><b>      2</b> demander par une prière, <i>acc</i>. XÉN. <i>Hell. 3, 2, 28</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσευχομαι - προσεύχομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n89 fois dans 82 versets de 15 livres bibliques (NT)\n<ul>\n<li>Matthieu (16)</li>\n<li>Marc (12)</li>\n<li>Luc (20)</li>\n<li>Actes (16)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (8)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (3)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (4)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G4337":"<h1>prosecho</h1>\n<p>Strong n° 4337 <i>Prononciation [pros-ekh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>apporter, amener vers\n<ol type=\"a\">\n<li>amener un navire à la terre, toucher terre</li>\n</ol>\n</li>\n<li>fixer son esprit, être attentif\n<ol type=\"a\">\n<li>à une personne ou une chose : prendre soin</li>\n</ol>\n</li>\n<li>prendre garde à soi-même, c.à.d. faire attention à soi\n<ol type=\"a\">\n<li>prêter attention, se mettre en garde</li>\n</ol>\n</li>\n<li>s'appliquer à, s'attacher à\n<ol type=\"a\">\n<li>être donné ou ajouté à</li>\n<li>consacrer sa pensée et son effort à</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·έχω</b> <span>(<i>f</i>. προσέξω, <i>ao.2</i> προσέσχον, <i>etc</i>.)</span><br><b>A <i>tr</i>.<br>   I</b> tenir <i>ou</i> diriger vers, approcher : μαζόν, ESCHL. <i>Ch. 524,</i> approcher le sein ; ὄμμα, EUR. <i>H.f. 941,</i> diriger ses yeux vers qqe ch. ;<br><b>   II</b> <i>particul. t. de mar. :</i> τὰς νῆας, HDT. <i>9, 99,</i> diriger les navires vers (la terre) ; τινά, SOPH. <i>Ph. 236,</i> faire aborder qqn ; <i>d’où en s.-e</i>. ναῦν, aborder : πρὸς γῆν, POL. <i>2, 11, 8,</i> atterrir, aborder ; γῆν, SOPH. <i>Ph. 244, ou</i> ἐς γῆν, HDT. <i>1, 2 ; 3, 48, etc. ;</i> DÉM. <i>56, 9, ou</i> κατὰ γῆν, PLUT. <i>Sert. 7, ou</i> γῇ, HDT. <i>4, 157 ;</i> POL. <i>1, 24, 2, m. sign. ;</i><br><b>   III</b> <i>fig</i>. πρ. τὸν νοῦν τινι, XÉN. <i>An. 7, 8, 16 ; Mem. 4, 7, 2 ;</i> PLAT. <i>Crit. 47</i> b, <i>etc. ou</i> πρός τινι, AR. <i>Nub. 1010 ; ou</i> πρός τι, POL. <i>15, 36, 9,</i> appliquer son esprit à qqe ch. ; <i>avec</i> μή, PLAT. <i>Rsp. 432</i> b, <i>etc</i>. veiller à ce que… ne ; <i>abs</i>. ἑαυτῷ πρ. τὸν νοῦν, PLAT. <i>Conv. 174</i> d, méditer en soi-même ; <i>abs</i>. XÉN. <i>An. 1, 5, 9 ;</i> PLAT. <i>Pol. 259</i> d, <i>etc. ; ou</i> προσέχειν τὴν γνώμην, THC. <i>1, 95 ; 2, 11 ; 5, 26 ;</i> AR. <i>Eccl. 600 ; ou simpl</i>. προσέχειν (<i>s.-e</i>. νοῦν <i>ou</i> γνώμην) :<br><b>      1</b> appliquer son esprit à, s’appliquer à, être attentif à, se préoccuper de, <i>dat</i>. XÉN. <i>An. 7, 6, 5 ;</i> PLAT. <i>Demod. 384</i> e, <i>etc. ;</i> ἑαυτῷ, XÉN. <i>Mem. 3, 7, 9 ;</i> AR. <i>Eccl. 294 ;</i> PLUT. <i>M. 150</i> b, prendre garde à soi-même ; ἑαυτῷ ἀπό τινος, NT. <i>Luc. 12, 1,</i> se tenir en garde contre qqe ch. ;<br><b>      2</b> s’attacher à, s’adonner à, <i>dat</i>. HDT. <i>9, 33 ;</i> THC. <i>1, 15, etc. ;</i><br><b>      3</b> obéir à, être dévoué à, <i>dat</i>. POL. <i>6, 37, 7 ;</i> PLUT. <i>Pomp. 48, Cic. 5, etc. ;</i><br><b>      4</b> s’attacher à, faire fondement sur, se fier à, <i>dat</i>. XÉN. <i>An. 2, 4, 2 ; joint à</i> πιστεύειν, PLUT. <i>Galb. 13, etc. ;</i><br><b>   IV</b> avoir en outre, posséder de plus : δεῖ καὶ τοῦτο προσέχειν τὸ μάθημα, PLAT. <i>Rsp. 521</i> d, il faut que cette science ait encore cet avantage ; <i>cf</i>. DÉM. <i>877, 26, etc. ;</i><br><b>B <i>intr.</i></b> s’attacher à, se fixer dans, <i>en parl. de maladies, d’infirmités, dat</i>. HPC. <i>194, 29, etc. ;</i><br><b><i>Moy.</i></b> s’attacher à, adhérer fortement à, <i>dat</i>. HDT. <i>2, 136 ;</i> EUR. <i>Med. 1213 ;</i> AR. <i>Vesp. 105 ;</i> XÉN. <i>Cyn. 8, 8 ;</i> ARSTT. <i>H.A. 5, 23, etc. ; fig</i>. se consacrer au service d’un dieu, PD. <i>P. 6, 51</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσεχω - προσέχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n25 fois dans 24 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Luc (4)</li>\n<li>Actes (7)</li>\n<li>1 Timothée (4)</li>\n<li>Tite (1)</li>\n<li>Hébreux (2)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4338":"<h1>proseloo</h1>\n<p>Strong n° 4338 <i>Prononciation [pros-ay-lo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>fixer avec des clous, clouer à</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·ηλόω-ῶ :<br>      1</b> fixer avec des clous, clouer : τί τινι, DS. <i>4, 29 ; 4, 47 ;</i> PLUT. <i>M. 426</i> b ; LUC. <i>Prom. 2,</i> clouer une ch. à une autre ; <i>particul</i>. attacher <i>ou</i> clouer à une planche, DÉM. <i>549, 1 ; ou</i> crucifier, PHIL. <i>1, 231, 687, etc. ;</i> PLUT. <i>M. 206</i> a ;<br><b>      2</b> <i>fig</i>. clouer à, attacher à, <i>avec</i> πρός <i>et l’acc</i>. PLAT. <i>Phæd. 83</i> d ; PLUT. <i>M. 718</i> d.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-ηλοω - προσηλόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4339":"<h1>proselutos</h1>\n<p>Strong n° 4339 <i>Prononciation [pros-ay'-loo-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un nouveau venu\n<ol type=\"a\">\n<li>un étranger</li>\n</ol>\n</li>\n<li>un prosélyte\n<ol type=\"a\">\n<li>celui qui vient d'une autre religion au Judaïsme</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσήλυτος, ος, ον</b> <span>[ῠ]</span><br><b>      1</b> étranger établi dans un pays, SPT. <i>Ex. 12, 49 ;</i><br><b>      2</b> <i>fig</i>. prosélyte, nouveau converti, NT. <i>Matth. 23, 15 ; Ap. 2, 10</i>.<br><span><b>Étym</b>. προσελεύσομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσηλυτος - προσήλυτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G4340":"<h1>proskairos</h1>\n<p>Strong n° 4340 <i>Prononciation [pros'-kahee-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>pour une saison</li>\n<li>endurant seulement pour un temps</li>\n<li>temporaire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρόσ·καιρος, ος, ον :<br>      1</b> temporaire, momentané, DH. <i>Rhet. 7, 4 et 6 ;</i> NT. <i>2Cor. 4, 18 ;</i><br><b>      2</b> passager, rapide, court, PLUT. <i>Pel. 15 ;</i> LUC. <i>Dem. enc. 31 ;</i> DC. <i>Exc. p. 63, 10</i>.<br><span><b>Étym</b>. π. καιρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσκαιρος - πρόσκαιρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4341":"<h1>proskaleomai</h1>\n<p>Strong n° 4341 <i>Prononciation [pros-kal-eh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>appeler, convoquer, citer en justice</li>\n<li>appeler à soi</li>\n<li>inviter à venir à soi</li>\n<li>métaph.\n<ol type=\"a\">\n<li>Il est dit que Dieu appelle à lui les Gentils, les étrangers, en les invitant à se joindre à son royaume, à travers la prédication de la Parole</li>\n<li>Il est dit que Christ et le Saint-Esprit appellent à eux les prédicateurs de l'évangile à qui ils ont décidé de confier une mission de développement de l'évangile</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·καλέω-ῶ</b> <span>(<i>f</i>. -καλέσω, <i>ao</i>. προσεκάλεσα, <i>etc</i>.)</span> <span>[κᾰ]</span><br><b>      1</b> appeler pour faire venir, mander, <i>acc</i>. THC. <i>8, 98 ;</i> PLAT. <i>Men. 82</i> a, <i>etc. ;</i><br><b>      2</b> citer, <i>acc</i>. LUC. <i>Pisc. 39 ;</i><br><b><i>Moy.</i></b> :<br><b>   I</b> appeler à soi, <i>d’où :</i><br><b>      1</b> mander auprès de soi, <i>acc</i>. XÉN. <i>An. 7, 7, 2, etc. ;</i><br><b>      2</b> appeler à son secours, <i>acc</i>. HDT. <i>1, 69 ;</i><br><b>      3</b> inviter, LUC. <i>As. 51 ;</i><br><b>   II</b> <i>t. de barreau :</i><br><b>      1</b> appeler pour témoigner en sa faveur, <i>acc</i>. PLAT. <i>Leg. 936</i> e ; DÉM. <i>850, 14 ;</i> PLUT. <i>M. 205</i> b ;<br><b>      2</b> citer en justice, <i>acc</i>. AR. <i>Vesp. 1334 ;</i> δίκην ἀσεϐείας πρ. τινα πρὸς τὸν βασιλέα, LYS. <i>104, 13,</i> citer qqn pour impiété devant l’archonte-roi ; τινα εἰς δίκην δημοσίαν, XÉN. <i>Mem. 2, 9, 5,</i> citer qqn pour un procès d’intérêt public ; τινα ὕϐρεως, AR. <i>Vesp. 1417,</i> citer qqn en justice pour insulte ; <i>au pass</i>. λιποταξίου πρ. DÉM. <i>999, 12,</i> être poursuivi pour désertion ; προσκληθεὶς δίκην εἰς Ἄρειον πάγον, ARSTT. <i>Pol. 5, 12, 2,</i> ayant été cité devant l’Aréopage.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσκαλεομαι - προσκαλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n30 fois dans 30 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Marc (9)</li>\n<li>Luc (4)</li>\n<li>Actes (10)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4342":"<h1>proskartereo</h1>\n<p>Strong n° 4342 <i>Prononciation [pros-kar-ter-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>adhérer à quelqu'un, être son adhérent, être dévoué ou constant à une cause</li>\n<li>être constamment attentif à, donner un soin incessant à une chose</li>\n<li>continuer tout le temps dans un lieu</li>\n<li>persévérer et ne pas faiblir</li>\n<li>se montrer courageux pour</li>\n<li>être d'un empressement constant pour quelqu'un</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·καρτερέω-ῶ</b>, s’attacher fortement, <i>d’où :</i><br><b>      1</b> persévérer dans, <i>dat</i>. POL. <i>1, 55, 4 ;</i> DS. <i>14, 87 ;</i> NT. <i>Ap. 1, 14 ; abs</i>. XÉN. <i>Hell. 7, 5, 14 ; au pass</i>. προσκαρτερούμενος χρόνος, DS. <i>2, 29,</i> temps qu’on emploie assidûment à qqe ch. ;<br><b>      2</b> rester fermement <i>ou</i> fidèlement attaché à, <i>dat</i>. DÉM. <i>1386, 6 ;</i> POL. <i>24, 5, 3 ;</i> NT. <i>Ap. 8, 13</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσκαρτερεω - προσκαρτερέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 10 versets de 4 livres bibliques (NT)\n<ul>\n<li>Marc (2)</li>\n<li>Actes (6)</li>\n<li>Romains (2)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4343":"<h1>proskarteresis</h1>\n<p>Strong n° 4343 <i>Prononciation [pros-kar-ter'-ay-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>persévérance, assiduité constante, fort attachement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσκαρτέρησις, εως (ἡ)</b> constance, assiduité, NT. <i>Eph. 6, 18</i>.<br><span><b>Étym</b>. προσκαρτερέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσκαρτερησις - προσκαρτέρησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4344":"<h1>proskephalaion</h1>\n<p>Strong n° 4344 <i>Prononciation [pros-kef-al'-ahee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un oreiller, un coussin</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·κεφάλαιον, ου (τὸ)</b> <span>[ᾰ]</span><br><b>      1</b> oreiller, coussin, PLAT. <i>Rsp. 328</i> c ; AR. <i>Ach. 1090, Pl. 542 ;</i> LYS. <i>121, 37, etc. ; p. ext</i>. coussin, <i>en gén</i>. CRAT. (POLL. <i>10, 40</i>) ;<br><b>      2</b> πρ. βασιλικόν, CHARÈS (ATH. <i>514</i> f) chambre où étaient déposés les trésors du grand roi.<br><span><b>Étym</b>. π. κεφαλή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσκεφαλαιον - προσκεφάλαιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4345":"<h1>proskleroo</h1>\n<p>Strong n° 4345 <i>Prononciation [pros-klay-ro'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ajouter ou attribuer par lot, par tirage au sort, accorder, répartir</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·κληρόω-ῶ</b>, attribuer par la voie du sort à, <i>rég. ind. au dat</i>. PLUT. <i>M. 738</i> d ; LUC. <i>Am. 3 ; au pass</i>. PHIL. <i>2, 366, 381 ;</i> NT. <i>Ap. 17, 4</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσκληροω - προσκληρόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4346":"<h1>prosklisis</h1>\n<p>Strong n° 4346 <i>Prononciation [pros'-klis-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une inclination, un penchant de l'esprit</li>\n<li>celui qui rejoint un parti, qui donne sa faveur, invitation</li>\n<li>partialité</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρόσκλισις, εως (ἡ)</b> <span>[λῐ]</span><br><b>      1</b> action de s’appuyer contre, <i>avec</i> πρός <i>et l’acc</i>. DS. <i>3, 26 ;</i><br><b>      2</b> <i>fig</i>. inclinaison, penchant, POL. <i>6, 10, 10 ;</i> SEXT. <i>P. 1, 16 ;</i> τινι, POL. <i>5, 51, 8,</i> vers qqn ; κατὰ πρόσκλισιν, NT. <i>1Tim. 5, 21,</i> avec partialité.<br><span><b>Étym</b>. προσκλίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσκλισις - πρόσκλισις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4347":"<h1>proskollao</h1>\n<p>Strong n° 4347 <i>Prononciation [pros-kol-lah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>coller à, adhérer avec, unir à soi</li>\n<li>se joindre étroitement, adhérer à, se coller avec, s'unir (sexuellement)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·κολλάω-ῶ :<br>      1 <i>tr.</i></b> coller à, fixer solidement à : τι πρός τι, HPC. <i>Art. 799,</i> coller une chose à une autre ; <i>au pass</i>. être collé à, être fortement attaché à, <i>dat</i>. PLAT. <i>Phæd. 82, etc. ;</i> NT. <i>Matth. 19, 5 ; ou</i> πρός <i>et l’acc</i>. SPT. <i>Gen. 2, 24 ;</i> NT. <i>Marc. 10, 7 ; Eph. 5, 31 ;</i><br><b>      2 <i>intr.</i></b> être compact, massif, solide, <i>en parl. du style,</i> DH. <i>Dem. 43</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσκολλαω - προσκολλάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Actes (1)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4348":"<h1>proskomma</h1>\n<p>Strong n° 4348 <i>Prononciation [pros'-kom-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un bloc qui fait trébucher\n<ol type=\"a\">\n<li>un obstacle sur le chemin, contre lequel bute le pied, ce qui fait trébucher ou tomber</li>\n<li>ce qui fait trébucher une âme, c.à.d. par quoi elle est attirée à pécher</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρόσκομμα, ατος (τὸ) :<br>      1</b> <i>pass</i>. obstacle contre lequel on se heurte, PLUT. ; <i>fig</i>. objet de scandale, SPT. <i>Ex. 23, 33 ;</i> NT. <i>Rom. 14, 13, etc. ;</i><br><b>      2</b> <i>act</i>. heurt, choc, achoppement, PLUT. <i>M. 1048</i> c ; <i>p. suite,</i> dommage <i>ou</i> lésion résultant d’un choc, ATH. <i>97</i> f.<br><span><b>Étym</b>. προσκόπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσκομμα - πρόσκομμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (4)</li>\n<li>1 Corinthiens (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4349":"<h1>proskope</h1>\n<p>Strong n° 4349 <i>Prononciation [pros-kop-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une occasion de trébucher, occasion de chute</li>\n<li>faire quelque chose qui fera trébucher les autres\n<ol type=\"a\">\n<li>c.à.d. les conduire dans l'erreur ou le péché</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>προσκοπή, ῆς (ἡ)</b> action de s’avancer en reconnaissance, THC. <i>1, 116 ;</i> DC. <i>Exc. 82, 57</i>.<br><span><b>Étym</b>. προσκέπτομαι.</span><br><br>\n➁ <b>προσκοπή, ῆς (ἡ) :<br>      1</b> <i>c</i>. πρόσκομμα, NT. <i>2Cor. 6, 3 ;</i><br><b>      2</b> heurt, <i>fig</i>. haine, inimitié, <i>joint à</i> φθόνος, POL. <i>6, 7, 8, etc. ; à</i> μῖσος, POL. <i>30, 20, 8 ; à</i> ἀλλοτριότης, POL. <i>31, 18, 4, etc</i>.<br><span><b>Étym</b>. προσκόπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσκοπη - προσκοπή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4350":"<h1>proskopto</h1>\n<p>Strong n° 4350 <i>Prononciation [pros-kop'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>frapper contre\n<ol type=\"a\">\n<li>de ceux qui frappent contre une pierre ou autre obstacle dans le chemin, trébucher</li>\n<li>frapper son pied contre une pierre\n<ol>\n<li>c.à.d. rencontrer quelque mal</li>\n</ol>\n</li>\n<li>se précipiter sur, se battre contre</li>\n<li>être amené à trébucher par une chose\n<ol>\n<li>c.à.d. métaph. être induit à pécher</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·κόπτω</b> (<i>pf</i>. προσκέκοφα) ;<br><b>   I <i>tr.</i></b> heurter contre : δάκτυλον, AR. <i>Vesp. 275,</i> se heurter <i>ou</i> se blesser le doigt ; πρὸς λίθον τὸν πόδα, NT. <i>Matth. 4, 6 ; Luc. 4, 11,</i> se heurter <i>ou</i> se blesser le pied contre une pierre ;<br><b>   II <i>intr. :</i><br>      1</b> se heurter contre, <i>dat</i>. XÉN. <i>Eq. 7, 6 ;</i> ARSTT. <i>Probl. 5, 17, etc. ;</i><br><b>      2</b> <i>fig</i>. faire un faux pas, commettre une faute : εἴς τι, ARÉT. se tromper sur qqe ch. ;<br><b>      3</b> heurter, choquer, offenser, mécontenter, <i>dat</i>. POL. <i>5, 49, 5 ; 7, 5, 6 ;</i> SYN. <i>301</i> a ;<br><b>      4</b> se buter contre, s’impatienter de, <i>dat</i>. TH. <i>H.P. 4, 8, 8, etc. ;</i> se dégoûter de : τινί, DS. <i>4, 61,</i> de qqe ch. ; <i>avec un rég. de pers. :</i> τινί, POL. <i>5, 7, 5,</i> se brouiller avec qqn ;<br><b><i>Moy.</i></b> se buter contre, être mécontent de, <i>dat</i>. APP. <i>Civ. 2, 27</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσκοπτω - προσκόπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n<li>Jean (2)</li>\n<li>Romains (2)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4351":"<h1>proskulio</h1>\n<p>Strong n° 4351 <i>Prononciation [pros-koo-lee'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>rouler, faire rouler une chose</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·κυλίω</b> <span>[ῠῑ]</span> faire rouler vers, AR. <i>Vesp. 202 ;</i> NT. <i>Matth. 27, 60 ; Marc. 15, 46, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ῐ]</span> <i>au part. ao. fém</i>. προσκυλίσασα, MAN. <i>5, 200</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσκυλιω - προσκυλίω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4352":"<h1>proskuneo</h1>\n<p>Strong n° 4352 <i>Prononciation [pros-koo-neh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>baiser la main de quelqu'un, en signe de révérence</li>\n<li>parmi les Orientaux, surtout les Perses, tomber sur les genoux et toucher le sol avec le front en expression de profonde révérence</li>\n<li>dans le N.T par agenouillement ou prosternation, rendre hommage, marquer son obéissance, aussi bien comme marque de respect que pour faire une supplication\n<ol type=\"a\">\n<li>utilisé de l'hommage montré aux hommes et aux êtres de rang supérieur\n<ol>\n<li>aux souverains sacrificateurs Juifs</li>\n<li>à Dieu</li>\n<li>à Christ</li>\n<li>aux êtres célestes</li>\n<li>aux démons</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·κυνέω-ῶ</b> <span>(<i>f</i>. -ήσομαι, <i>rar</i>. -ήσω, <i>ao</i>. προσεκύνησα, <i>pf</i>. προσκεκύνηκα)</span> <span>[ῠ]</span> saluer en se prosternant, <i>ou p.-ê</i>. en portant la main à sa bouche comme pour la baiser, HDT. <i>2, 121, etc. ; avec un rég</i>. θεόν, SOPH. <i>Ph. 657, etc., postér</i>. θεῷ, NT. <i>Matth. 2, 2 et 11 ; Joh. 4, 23, etc</i>. se prosterner devant un dieu, devant la divinité ; <i>de même,</i> se prosterner devant un lieu sacré, <i>acc</i>. SOPH. <i>El. 1374 ;</i> PLAT. <i>Rsp. 469</i> a, <i>etc. ; particul. en parl. de suppliants,</i> SOPH. <i>O.R. 327 ;</i> EUR. <i>Or. 1507, etc. ; ou des Perses devant le grand roi,</i> HDT. <i>1, 119, etc. ; d’où</i> conjurer (la jalousie des dieux) SOPH. <i>Ph. 776</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. poét</i>. προσέκυσα <span>[ῠ]</span> AR. <i>Eq. 640 ; impér</i>. πρόσκυσον, SOPH. <i>Ph. 776, etc. ; inf</i>. προσκύσαι, SOPH. <i>Ph. 657 ; part</i>. προσκύσας, SOPH. <i>Ph. 533, 1408 ; pf. réc</i>. προσκεκύνηκα, PLUT. <i>Alex. 54, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσκυνεω - προσκυνέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n61 fois dans 54 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (13)</li>\n<li>Marc (2)</li>\n<li>Luc (3)</li>\n<li>Jean (11)</li>\n<li>Actes (4)</li>\n<li>1 Corinthiens (1)</li>\n<li>Hébreux (2)</li>\n<li>Apocalypse (25)</li>\n</ul>\n</td></tr>\n</table>","G4353":"<h1>proskunetes</h1>\n<p>Strong n° 4353 <i>Prononciation [pros-koo-nay-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un adorateur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσκυνητής, οῦ (ὁ)</b> <span>[ῠ]</span> adorateur, NT. <i>Joh. 4, 23</i>.<br><span><b>Étym</b>. προσκυνέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσκυνητης - προσκυνητής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4354":"<h1>proslaleo</h1>\n<p>Strong n° 4354 <i>Prononciation [pros-lal-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>parler à, adresser la parole à</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·λαλέω-ῶ</b> <span>[ᾰ]</span> s’entretenir avec, <i>dat</i>. TH. <i>Char. 7 ;</i> τινί τι, PLUT. <i>M. 602</i> e, avec qqn de qqe ch.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσλαλεω - προσλαλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4355":"<h1>proslambano</h1>\n<p>Strong n° 4355 <i>Prononciation [pros-lam-ban'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prendre, prendre en addition, prendre pour soi\n<ol type=\"a\">\n<li>prendre comme compagnon</li>\n<li>prendre par la main pour amener ailleurs</li>\n<li>prendre ou recevoir dans sa maison, avec l'idée de bonté</li>\n<li>recevoir, c.à.d. permettre à quelqu'un l'accès à son cœur\n<ol>\n<li>prendre en amitié et comme relation</li>\n</ol>\n</li>\n<li>prendre pour soi, prendre : c.à.d. de la nourriture</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·λαμϐάνω</b> <span>(<i>f</i>. προσλήψομαι, <i>ao.2</i> προσέλαϐον, <i>pf</i>. προσείληφα)</span><br><b>   I</b> prendre en outre : ὄψον, XÉN. <i>Mem. 3, 14, 4,</i> un aliment (avec son pain) ; <i>fig</i>. δόξαν γελοίαν, XÉN. <i>Conv. 4, 8,</i> acquérir une gloire ridicule ; αἰσχύνην αἰσχίω, THC. <i>5, 111,</i> s’attirer une plus grande honte ;<br><b>   II</b> prendre en attirant à soi, <i>d’où :</i><br><b>      1</b> prendre en attirant pour soi : τροφῆς, NT. <i>Ap. 27, 34,</i> prendre de la nourriture ;<br><b>      2</b> prendre avec soi, emmener avec soi : ἱππέας, XÉN. <i>Cyr. 1, 4, 16,</i> des cavaliers ; τινὰ σύμμαχον, XÉN. <i>An. 7, 6, 27,</i> prendre qqn comme allié ; <i>cf</i>. SOPH. <i>O.C. 378, etc. ;</i><br><b>      3</b> fixer à : δεσμοῖς, ARSTT. <i>P.A. 2, 9, 6, etc</i>. fixer avec des liens une ch. à une autre ; <i>fig</i>. attirer à soi, se concilier : τινὰς τῶν πολιτῶν, DÉM. <i>194, 13,</i> qqes-uns des citoyens ; τὸν δῆμον, ARSTT. <i>Pol. 5, 10, 32,</i> le peuple ; <i>avec idée de violence :</i> soumettre, conquérir : πόλεις, XÉN. <i>Hell. 4, 4, 1,</i> des villes ;<br><b>      4</b> prendre sous sa protection, aider, assister : τινά, SOPH. <i>Tr. 1024,</i> qqn ;<br><b><i>Moy.</i></b> :<br><b>   I <i>tr</i>.<br>      1</b> prendre pour soi, prendre, saisir, <i>gén</i>. AR. <i>Ach. 1215, etc. ;</i><br><b>      2</b> se procurer : γνώμην τινός, POL. <i>3, 70, 2,</i> prendre l’avis de qqn ; <i>et avec idée de violence,</i> soumettre : πόλιν, POL. <i>1, 37, 5,</i> une ville ;<br><b>      3</b> prendre une part de : τινος, XÉN. <i>An. 2, 3, 11 et 12,</i> prendre part à une entreprise, s’y associer ; <i>abs</i>. venir en aide, assister, AR. <i>Pax 9 ;</i> τινα τῆς ἀποκρίσεως, PLAT. <i>Leg. 897</i> d, aider qqn à trouver la réponse ;<br><b>   II</b> <i>t. de log</i>. se rattacher à, ARSTT. <i>An. post. 1, 12, 9 ;</i> τὰ προσλαμϐανόμενα, ARSTT. <i>An. pr. 2, 6, 3, etc</i>. mineure d’un raisonnement, <i>litt</i>. ce qui rattache la majeure à la conclusion.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσλαμβανω - προσλαμβάνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 12 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Actes (6)</li>\n<li>Romains (4)</li>\n<li>Philémon (1)</li>\n</ul>\n</td></tr>\n</table>","G4356":"<h1>proslepsis</h1>\n<p>Strong n° 4356 <i>Prononciation [pros'-lape-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une réception : dans le royaume de Dieu</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>προσληπτικός, ή, όν</b>, qui reçoit en outre, DYSC. <i>Conj. 518</i>.<br><span><b>Étym</b>. προσλαμϐάνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσλημψις - πρόσλημψις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4357":"<h1>prosmeno</h1>\n<p>Strong n° 4357 <i>Prononciation [pros-men'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rester avec, continuer avec quelqu'un</li>\n<li>retenir : la grâce de Dieu reçue dans l'Evangile</li>\n<li>rester tranquille, s'attarder, séjourner</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·μένω</b> <span>(<i>f</i>. -μενῶ, <i>ao</i>. προσέμεινα, <i>etc</i>.)</span><br><b>   I <i>intr</i>.<br>      1</b> rester auprès, demeurer, HDT. <i>1, 199 ; 5, 19 ;</i> SOPH. <i>O.R. 620, El. 1236 ;</i><br><b>      2</b> <i>avec un suj. de chose,</i> attendre, <i>d’où</i> être réservé à, <i>dat</i>. ESCHL. <i>Eum. 497 ; avec le dat</i>. persévérer dans, NT. <i>1Tim. 5, 5 ;</i><br><b>   II <i>tr</i>.<br>      1</b> attendre en résistant à, attendre de pied ferme, PD. <i>N. 3, 105 ;</i><br><b>      2</b> attendre, <i>en gén. acc</i>. THGN. <i>1140 ;</i> SOPH. <i>O.R. 837, etc. ;</i> ἔστ' ἄν, HDT. <i>8, 4 ;</i> ἕως, XÉN. <i>Hell. 2, 4, 7,</i> attendre que ; <i>avec une prop. inf. au fut</i>. SOPH. <i>El. 303, m. sign</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσμενω - προσμένω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Actes (2)</li>\n<li>1 Timothée (2)</li>\n</ul>\n</td></tr>\n</table>","G4358":"<h1>prosormizo</h1>\n<p>Strong n° 4358 <i>Prononciation [pros-or-mid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>amener un navire à l'amarrage</li>\n<li>se mettre au mouillage près de la côte</li>\n<li>amarrer, venir à l'ancre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·ορμίζω :<br>      1 <i>tr.</i></b> faire aborder, <i>d’où au pass</i>. aborder à, <i>rég. ind. au dat</i>. ARR. <i>An. 6, 20 ;</i> EL. <i>V.H. 8, 5, etc. ;</i><br><b>      2 <i>intr.</i></b> aborder à, <i>dat</i>. LUC. <i>Am. 11 ;</i> JAMBL. <i>V. Pyth. 3 ;</i><br><b><i>Moy.</i></b> <span>(<i>f. att</i>. -ιοῦμαι)</span> aborder au port, jeter l’ancre, mouiller près de, πρός <i>et l’acc</i>. HDT. <i>6, 97 ;</i> DÉM. <i>795, 15 ; dat</i>. PLUT. <i>Æmil. 26 ; fig</i>. PHILSTR. <i>717</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσορμιζω - προσορμίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4359":"<h1>prosopheilo</h1>\n<p>Strong n° 4359 <i>Prononciation [pros-of-i'-lo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>devoir à côté de, être débiteur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·οφείλω</b>, devoir en outre, <i>càd</i>. être encore redevable de, <i>acc</i>. THC. <i>7, 48 ;</i> PLUT. <i>Alex. 15, etc. ; abs</i>. DÉM. <i>825, 19 ; au pass</i>. rester dû, THC. <i>8, 45 ; particul</i>. être redevable en outre d’une amende ; <i>fig</i>. χάριτάς τινι, XÉN. <i>Cyr. 3, 2, 16,</i> devoir encore de la reconnaissance à qqn ; πολύ τι, POL. <i>39, 2, 6,</i> être fort en reste avec qqn, lui être fort inférieur.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσοφειλω - προσοφείλω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philémon (1)</li>\n</ul>\n</td></tr>\n</table>","G4360":"<h1>prosochthizo</h1>\n<p>Strong n° 4360 <i>Prononciation [pros-okh-thid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>avoir du déplaisir avec, se fâcher contre, s'irriter, s'emporter contre</li>\n<li>détester</li>\n<li>rejeter</li>\n<li>être dégoûté de</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·οχθίζω</b> <span>(<i>f</i>. ιῶ)</span><br><b>      1</b> s’irriter contre, en vouloir à, <i>dat</i>. SPT. <i>Ps. 94, 10, etc. ;</i> SIB. <i>3, 272 ; avec</i> ἐν <i>et le dat</i>. SPT. <i>Ezech. 36, 31 ;</i><br><b>      2</b> traiter outrageusement, <i>au pass</i>. SPT. <i>2Reg. 1, 21</i>.<br><span><b>Étym</b>. π. ὀχθέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσοχθιζω - προσοχθίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G4361":"<h1>prospeinos</h1>\n<p>Strong n° 4361 <i>Prononciation [pros'-pi-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>très affamé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρόσ·πεινος, ος, ον</b>, affamé, NT. <i>Ap. 10, 10</i>.<br><span><b>Étym</b>. π. πεῖνα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσπεινος - πρόσπεινος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4362":"<h1>prospegnumi</h1>\n<p>Strong n° 4362 <i>Prononciation [pros-payg'-noo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>attacher, fixer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·πήγνυμι :<br>      1 <i>tr.</i></b> fixer <i>ou</i> attacher à : τινί τι, EUR. <i>fr. 680 ;</i> DC. <i>63, 2 ;</i> τι πρός τι, DC. <i>40, 9,</i> une chose à une autre ; <i>abs</i>. attacher à une croix, crucifier, NT. <i>Ap. 2, 23 ;</i><br><b>      2</b> <i>intr. (au pf</i>. προσπέπηγα) être fixé <i>ou</i> attaché à, CLÉM. <i>45 ; avec</i> περί <i>et l’acc</i>. DC. <i>45, 17</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσπηγνυμι - προσπήγνυμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4363":"<h1>prospipto</h1>\n<p>Strong n° 4363 <i>Prononciation [pros-pip'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tomber en avant, se prosterner devant, en hommage ou supplication : se jeter aux pieds</li>\n<li>se précipiter sur, battre contre\n<ol type=\"a\">\n<li>des vents qui battent une maison</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·πίπτω</b> <span>(<i>f</i>. -προσπεσοῦμαι, <i>ao.2</i> προσέπεσον, <i>etc</i>.)</span> tomber auprès <i>ou</i> sur, <i>d’où :</i><br><b>      1</b> tomber contre, <i>dat</i>. XÉN. <i>Eq. 7, 6 ; p. anal</i>. τῇ Τυρρηνίᾳ, PLUT. <i>Rom. 1,</i> aborder en Tyrrhénie ; ἐσθὴς τῷ σώματι προσπεσοῦσα, PLUT. <i>M. 100</i> c, vêtement se collant au corps ;<br><b>      2</b> courir vers, <i>dat</i>. XÉN. <i>An. 7, 1, 21 ;</i><br><b>      3</b> se jeter contre : βωμοῖσι, SOPH. <i>Tr. 904,</i> se jeter aux pieds des autels ; γόνασί τινος, EUR. <i>Or. 1332, etc. ;</i> πρὸς γόνυ, EUR. <i>H.f. 79 ; ou</i> τοῖς ποσί τινος, PLUT. <i>Cor. 36,</i> se jeter aux pieds de qqn ; <i>en poésie avec un simple acc</i>. πρ. τινά, EUR. <i>Andr. 537, Tr. 757 ;</i> πρ. βρέτη δαιμόνων, ESCHL. <i>Sept. 95,</i> se jeter aux pieds de qqn, devant les statues des dieux ; <i>postér. en prose :</i> πρ. τὸν Ἀχιλλέα, LUC. <i>Par. 46,</i> se jeter aux genoux d’Achille ; <i>abs</i>. προσπίπτειν, se jeter à genoux, HDT. <i>1, 134, etc. ;</i> XÉN. <i>Cyr. 4, 6, 2 ;</i> PLAT. <i>Ep. 349</i> a, <i>etc. ;</i><br><b>      4</b> se jeter dans la direction de, <i>en parl. d’un cours d’eau :</i> πρὸς τὸν Ἐρύμανθον, POL. <i>4, 70, 9,</i> se jeter dans l’Érymanthe ;<br><b>      5</b> se jeter <i>ou</i> tomber sur, attaquer <i>dat</i>. THC. <i>1, 5 ;</i> XÉN. <i>Hell. 3, 2, 3, etc. ;</i> πρός <i>et l’acc</i>. PLAT. <i>Leg. 907</i> b ; <i>abs</i>. THC. <i>3, 30, etc. ;</i><br><b>      6</b> tomber du côté de, se ranger du côté de : τινί, XÉN. <i>Hell. 7, 1, 42 ;</i> PLAT. <i>Phædr. 270</i> a, du côté de qqn, se ranger à l’avis de qqn, approuver qqn ;<br><b>      7</b> tomber sur, rencontrer : <i>avec l’acc. :</i> τινά, EUR. <i>Her. 339 ; ou</i> πρός τινα, AR. <i>Eq. 31,</i> qqn ; <i>avec le dat</i>. δυστυχεστάτῳ κλήρῳ, EUR. <i>Tr. 291,</i> un sort très malheureux ; XÉN. <i>Ap. 30 ;</i> PLAT. <i>Leg. 637</i> a, <i>etc. ;</i> πρ. δήγματι, EL. <i>N.A. 6, 51,</i> être mordu ; <i>avec un suj. de ch. :</i> ἡ ἀτιμία φιλοσοφίᾳ διὰ ταῦτα προσπέπτωκεν, PLAT. <i>Rsp. 535</i> c, la philosophie a éprouvé, par suite, de la déconsidération ; αἱ προσπίπτουσαι τύχαι, THC. <i>1, 84, ou</i> σύμφοραι, HDT. <i>1, 46,</i> les événements qui surviennent ; ἄν τινες νόσοι προσπέσωσιν, PLAT. <i>Phæd. 66</i> c, s’il survient certaines maladies ; <i>très souv. en parl. de bruits, de nouvelles :</i> ἡ φήμη προσπίπτει αὐτοῖς, POL. <i>5, 101, 3,</i> le bruit parvient à leurs oreilles ; <i>abs</i>. προσέπεσε παραγενέσθαι τοὺς πρεσϐευτάς, POL. <i>25, 4, 10,</i> le bruit se répandit, sur ces entrefaites, que les ambassadeurs étaient arrivés ; <i>cf</i>. SPT. <i>2Macc. 5, 11 ; 2, 9, 3, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσπιπτω - προσπίπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 8 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (4)</li>\n<li>Luc (5)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4364":"<h1>prospoieomai</h1>\n<p>Strong n° 4364 <i>Prononciation [pros-poy-eh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>soutenir ou prétendre une chose à soi-même</li>\n<li>se conformer à une chose, ou mieux se l'approprier\n<ol type=\"a\">\n<li>prétendre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·ποιέω-ῶ :<br>      1</b> faire en outre, ajouter, adjoindre : χάριν προσποιεῖν, DÉM. <i>1393, 15,</i> rendre en outre service ;<br><b>      2</b> disposer en faveur de, gagner, concilier : προσποιοῦσιν αὐτοῖς τὴν Κέρκυραν, THC. <i>1, 55,</i> ils gagnent Corcyre à leur cause ; <i>cf</i>. XÉN. <i>Hell. 4, 8, 28 ;</i><br><b>      3</b> feindre : ὡς, X. ÉPH. <i>1, 5,</i> feindre que ;<br><b><i>Moy.</i></b> <span>(<i>ao</i>. προσεποιησάμην <i>ou</i> προσεποιήθην)</span><br><b>   I</b> se faire faire en outre, se faire ajouter : ξύλινον πόδα, HDT. <i>9, 37,</i> une jambe de bois ;<br><b>   II</b> attirer à soi, <i>d’où :</i><br><b>      1</b> se concilier, gagner : φίλον τινά, HDT. <i>1, 6,</i> se concilier l’amitié de qqn ; τὸν δῆμον, AR. <i>Eq. 215,</i> se concilier le peuple ;<br><b>      2</b> se rendre maître de, s’approprier, <i>gén. :</i> κληρονομιάς, <i>etc</i>. IS. <i>46, 36 ; 47, 11,</i> un héritage ; χρημάτων, AR. <i>Eccl. 871,</i> de l’argent ; <i>qqf. avec l’acc</i>. DIN. <i>1, 71 ;</i> DS. <i>16, 4 ;</i><br><b>   III</b> se donner l’air de : ὅσοι πολιτικοὶ προσποιοῦνται εἶναι, PLAT. <i>Gorg. 519</i> c, tous ceux qui se donnent des airs d’hommes d’État ; <i>p. suite :</i><br><b>      1</b> faire semblant de, feindre : εἰδέναι, PLAT. <i>Ap. 23</i> d, feindre de savoir ; <i>ou avec l’inf. fut</i>. XÉN. <i>An. 4, 3, 20,</i> feindre de, <i>etc. ; avec</i> ὡς <i>et un part</i>. POL. <i>31, 22, 1,</i> feindre de ; <i>qqf. avec un acc. de ch. :</i> ψευδῶς τὴν τῶν γεφυρῶν διάλυσιν, THC. <i>1, 137,</i> feindre mensongèrement d’avoir rompu les ponts ;<br><b>      2</b> simuler, figurer, représenter : τὸν Ἀριστοτέλην, LUC. <i>Pisc. 50,</i> figurer le personnage d’Aristote ;<br><b>      3</b> se figurer à soi-même : οὐ πρ. ne pas se figurer (qu’une chose est), tenir pour non avenu, ignorer : δεῖ καὶ εἰ ἠδίκησαν, μὴ προσποιεῖσθαι, THC. <i>3, 47,</i> il faut, même s’ils ont des torts, feindre de les ignorer.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσποιεομαι - προσποιέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4365":"<h1>prosporeuomai</h1>\n<p>Strong n° 4365 <i>Prononciation [pros-por-yoo'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>venir près de, s'approcher de</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·πορεύομαι</b>, s’approcher :<br><b>      1</b> (<i>avec idée de lieu</i>) : εἴς τι, PHLÉG. TR. <i>Mir. 1,</i> de qqe ch. ; τινι, POL. <i>4, 3, 13,</i> de qqn ; <i>abs</i>. ARSTT. <i>H.A. 9, 40, 24 ;</i><br><b>      2</b> (<i>avec idée de temps</i>) ARSTT. <i>Œc. 2, 40 ;</i><br><b>      3</b> <i>fig. :</i> πρ. πρός τι, POL. <i>10, 4, 1,</i> tendre vers qqe ch. ; <i>particul</i>. solliciter <i>ou</i> briguer qqe ch. (une charge) ; <i>abs</i>. s’attacher à qqn, SPT. <i>Jos. 8, 35 ; Sir. 12, 14</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσπορευομαι - προσπορεύομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4366":"<h1>prosregnumi</h1>\n<p>Strong n° 4366 <i>Prononciation [pros-rayg'-noo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>se briser contre, rompre par des coups impétueux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·ρήσσω</b>, <i>c</i>. προσρήγνυμι, M. ANT. <i>4, 49</i>.<br>\n<b>προσ·ρήγνυμι</b> <span>(<i>ao</i>. προσέρρηξα)</span><br><b>      1 <i>tr.</i></b> briser contre, <i>dat</i>. JOS. <i>A.J. 9, 4, 6 ;</i><br><b>      2 <i>intr.</i></b> se briser contre, <i>dat</i>. NT. <i>Luc. 6, 48</i>.<br><span><b>Étym</b>. <i>cf</i>. προσρήσσω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσρηγνυμι - προσρήσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G4367":"<h1>prostasso</h1>\n<p>Strong n° 4367 <i>Prononciation [pros-tas'-so]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>assigner ou attribuer, joindre à</li>\n<li>enjoindre, ordonner, prescrire, commander\n<ol type=\"a\">\n<li>désigner, définir</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·τάσσω</b>, <i>att</i>. <b>προσ·τάττω :<br>      1</b> préposer : τινὰ πύλαις, ESCHL. <i>Sept. 527,</i> confier à qqn la garde des portes ;<br><b>      2</b> <i>p. suite,</i> assigner, attribuer : πρὸς τοῖσι ἔθνεσι τοὺς πλησιοχώρους, HDT. <i>3, 89,</i> rattacher à certaines tribus les tribus voisines ; πρ. τινάς τινι, THC. <i>5, 8,</i> mettre des troupes sous le commandement de qqn ; <i>au pass</i>. HDT. <i>7, 65 ;</i> THC. <i>6, 42 ;</i> τινὰ ἄρχοντα, THC. <i>3, 16 ; 8, 23, etc</i>. désigner qqn comme chef ; <i>p. ext</i>. ordonner, prescrire : τι, ARSTT. <i>Pol. 4, 15, 8, etc</i>. qqe ch. ; τί τινι, HDT. <i>1, 114 ;</i> XÉN. <i>Cyr. 4, 5, 25, etc</i>. qqe ch. à qqn ; τινί, <i>avec l’inf</i>. HDT. <i>5, 105, etc. ;</i> SOPH. <i>O.C. 494, etc. ; ou</i> τινά <i>avec l’inf</i>. EUR. <i>Hel. 890 ;</i> XÉN. <i>Cyr. 8, 6, 3,</i> ordonner à qqn de faire qqe ch. ; τινὶ περί τινος, DÉM. <i>363, 26,</i> donner un ordre à qqn au sujet. de qqe ch. ; τὸ προστεταγμένον, HDT. <i>9, 104 ;</i> τὸ προσταχθέν, HDT. <i>1, 114 ;</i> SOPH. <i>Ph. 1010,</i> l’ordre donné ; τὰ προσταχθέντα, HDT. <i>2, 121,</i> les ordres donnés ; <i>abs</i>. προσταχθέν μοι, LYS. <i>183, 12 ;</i> DÉM. <i>1210, 5,</i> ce qui m’a été commandé ;<br><b><i>Moy.</i></b> prescrire pour soi, PLAT. <i>Leg. 818</i> e.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προστασσω - προστάσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4368":"<h1>prostatis</h1>\n<p>Strong n° 4368 <i>Prononciation [pros-tat'-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une femme responsable des autres</li>\n<li>une gardienne, protectrice, patronne, prenant soin des affaires des autres et les aidant par ses ressources</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προστάτις, ιδος</b>, <i>acc</i>. <b>-ιν (ἡ)</b> <span>[ᾰῐδ]</span> <i>fém. de</i> προστάτης, SOPH. <i>O.C. 458 ;</i> LUC. <i>Bis acc. 29, etc</i>.<br><br>\n<b>προστάτης, ου (ὁ)</b> <span>[ᾰ]</span><br><b>   I</b> qui se tient en avant, <i>d’où :</i><br><b>      1</b> celui qui se tient le premier dans une ligne de bataille, chef de file, XÉN. <i>Cyr. 3, 3, 41 ; Hipp. 2, 2 et 6 ;</i><br><b>      2</b> <i>p. suite,</i> chef, <i>particul</i>. chef de parti <i>dans les États démocratiques,</i> HDT. <i>1, 127, etc. ;</i> THC. <i>3, 75, etc. ;</i> PLAT. <i>Rsp. 565</i> d, <i>etc. ; en gén</i>. président, chef, celui qui dirige, <i>gén</i>. ESCHL. <i>Sept. 1026, etc. ;</i> EUR. <i>Her. 964, etc. ;</i> HDT. <i>2, 178 ;</i> XÉN. <i>Cyr. 7, 2, 23, etc. ; joint à</i> ἐπιμελητής, PLAT. <i>Leg. 766</i> b, <i>etc. ;</i><br><b>      3</b> <i>p. suite,</i> protecteur, défenseur, SOPH. <i>Tr. 209 ;</i> ESCHL. <i>Sept. 408 ; particul</i>. protecteur <i>ou</i> patron des métèques, <i>à Athènes,</i> SOPH. <i>O.R. 882 ;</i> AR. <i>Pax 684, etc. ;</i> ARSTT. <i>Pol. 3, 1, 4 ;</i> LUC. <i>Per. 11, etc. ;</i> ἐπὶ προστάτου οἰκεῖν, LYS. <i>187, 29 ; 188, 9 ;</i> LYCURG. <i>168, 29 ;</i> résider sous la protection du patron ; τινὸς προστάτου γράφεσθαι, SOPH. <i>O.R. 411,</i> se faire inscrire sous le nom d’un patron, <i>càd</i>. s’attacher à un patron, être le protégé de qqn ; <i>à Rome,</i> patron, PLUT. <i>Rom. 13, Mar. 5, etc. ;</i><br><b>      4</b> <i>t. de méd., autre n. de l’</i>os hyoïde (<i>v</i>. ὑοειδής) GAL. <i>4, 647 ;</i><br><b>   II</b> qui se tient devant <i>ou</i> s’approche de : θεοῦ, SOPH. <i>O.C. 1278, etc.,</i> qui se tient devant l’autel d’un dieu, <i>càd</i>. suppliant.<br><span><b>Étym</b>. προΐστημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-στατις - προστάτις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4369":"<h1>prostithemi</h1>\n<p>Strong n° 4369 <i>Prononciation [pros-tith'-ay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>poser dessus</li>\n<li>ajouter, additionner\n<ol type=\"a\">\n<li>c.à.d. joindre à, rassembler dans une compagnie le nombre des suivants, ou compagnons\n<ol>\n<li>il a rejoint ses pères, c.à.d. il est mort</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·τίθημι</b> <span>(<i>f</i>. προσθήσω, <i>ao</i>. προσέθηκα, <i>ao.2</i> προσέθην ; <i>pass. ao.1</i> προσετέθην, <i>etc</i>.)</span> <span>[τῐ]</span><br><b>   I</b> (πρός, auprès) :<br><b>      1</b> placer auprès <i>ou</i> contre, apposer, appliquer sur : κλίμακας πύργοις, THC. <i>3, 23,</i> appliquer des échelles contre des tours ; γόνασίν τινος ὠλένας, EUR. <i>Andr. 896,</i> poser ses bras sur les genoux de qqn ; τὸ στόμα πρὸς τὸ στόμα, XÉN. <i>Mem. 2, 6, 39,</i> appliquer sa bouche sur celle d’un autre ; <i>avec un seul rég. :</i> λίθον, OD. <i>9, 305,</i> appliquer une pierre contre, <i>etc. ;</i> τὰς θύρας, HDT. <i>3, 78 ;</i> τὴν θύραν, LYS. <i>92, 42, etc. ;</i> τὰς πύλας, THC. <i>4, 67,</i> appliquer et fermer les portes, la porte (de la maison), les portes (de la ville) ; τὴν φιλανθρωπίαν εἰς τὰ τῆς πόλεως πράγματα, DÉM. <i>384, 23,</i> appliquer son esprit d’humanité aux affaires de la ville ; <i>fig</i>. attribuer, assigner : μέτρον, ESCHL. <i>Ch. 796,</i> fixer la mesure ; <i>d’où :</i> imputer : αἰτίαν τινί, THC. <i>3, 39 ;</i> EUR. <i>Ion 1525,</i> imputer à qqn la cause (de qqe ch.) ; conférer, accorder : γυναῖκά τινι, HDT. <i>6, 126,</i> accorder une jeune fille pour femme à qqn ; γέρας τινί, HH. <i>Merc. 129,</i> accorder une récompense à qqn ; <i>fig</i>. νᾶσον ἐϋκλέϊ λόγῳ, PD. <i>N. 3, 120,</i> joindre le nom d’une île à un discours glorieux, <i>càd</i>. rendre une île célèbre ;<br><b>      2</b> <i>en mauv. part</i>. imposer : ἀτιμίην τινί, HDT. <i>7, 11,</i> infliger un déshonneur à qqn ; πόνους τινί, EUR. <i>Her. 505,</i> imposer des épreuves à qqn ; τὸ καρτερόν, ESCHL. <i>Suppl. 612,</i> faire violence ;<br><b>      3</b> remettre, livrer, abandonner : πόλιν, THC. <i>4, 86,</i> livrer une ville ; Ἅιδῃ δέμας, EUR. <i>Hec. 368,</i> livrer un corps à Hadès ;<br><b>      4</b> causer, produire : λύπην τινί, EUR. <i>Suppl. 946,</i> causer du chagrin à qqn ; ὄκνον πολύν, SOPH. <i>Ant. 243,</i> causer une grande hésitation ;<br><b>   II</b> (πρός, outre) placer en outre, <i>d’où</i> ajouter : φερνάς, EUR. <i>Hipp. 628,</i> donner une dot outre (la femme) ; πίστιν, DÉM. <i>1270, 9,</i> ajouter le serment ; χάριτι χάριν, EUR. <i>H.f. 327,</i> ajouter un bienfait à un autre ; νοσοῦντι νόσον, EUR. <i>Alc. 1051,</i> envoyer une nouvelle maladie à un malade ; <i>p. opp. à</i> ἐλλείπω, PLAT. <i>Crat. 431</i> d, <i>à</i> ἐξαιρέω, PLAT. <i>Crat. 418</i> a, <i>à</i> ἀφαιρέω, PLAT. <i>Crat. 432</i> a ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. προσθήσομαι, <i>ao</i>. προσεθηκάμην, <i>etc</i>.)</span><br><b>   I <i>tr</i>.<br>      1</b> poser vers <i>ou</i> contre, porter vers : ψῆφόν τινι, ESCHL. <i>Eum. 735,</i> donner son suffrage à qqn, voter en faveur de qqn ; <i>cf</i>. DÉM. <i>1320, 16 ;</i> ψῆφον πρ. ἐναντίαν τινί, THC. <i>1, 40,</i> voter contre qqn ; πόλεμόν τινι, HDT. <i>4, 65,</i> porter la guerre à qqn ; μῆνίν τινι, HDT. <i>7, 229,</i> décharger sa colère sur qqn ;<br><b>      2</b> approcher de soi, attirer vers soi <i>ou</i> sur soi : στέρνα τινός, EUR. <i>H.f. 1408,</i> serrer sur sa poitrine la poitrine de qqn ; <i>fig</i>. δάμαρτα, SOPH. <i>Tr. 1224,</i> prendre une épouse ; τὸν δῆμον, HDT. <i>5, 69,</i> se concilier le peuple ; φίλον τινά, HDT. <i>1, 35, etc</i>. se concilier l’amitié de qqn ; <i>en mauv. part :</i> ἄχθος, EUR. <i>Andr. 396 ;</i> ἄλγος, EUR. <i>Hec. 742,</i> s’attirer une peine, une douleur ;<br><b>      3</b> ajouter : πρὸς κακοῖσι κακόν, ESCHL. <i>Pers. 531,</i> un nouveau mal à d’autres maux ; τινὰ πολέμιον πρὸς τοῖς ἄλλοις, XÉN. <i>Cyr. 2, 4, 12,</i> se faire de qqn un ennemi ajouté aux autres ; ἔχθρας ἑκουσίους πρὸς ταῖς ἀναγκαίαις, PLAT. <i>Prot. 346</i> b, ajouter des inimitiés volontaires à celles qui s’imposent ;<br><b>      4</b> faire de nouveau, <i>hébraïsme,</i> SPT. <i>Gen. 8, 12 ; 8, 21 ; 18, 29 ; Ex. 14, 13 etc. ;</i><br><b>   II <i>intr.</i></b> s’adjoindre à, s’associer à, prendre parti pour : τινί, SOPH. <i>O.C. 1332 ;</i> THC. <i>3, 11 ; 8, 48, etc. ;</i> DÉM. <i>68, 27, etc</i>. se mettre du parti de qqn ; ψήφῳ τινί, THC. <i>1, 20,</i> se ranger, par son vote, du côté de qqn ; <i>avec un rég. de chose :</i> τῇ γνώμῃ, HDT. <i>1, 109 ; 3, 83 ;</i> THC. <i>6, 50 ;</i> XÉN. <i>An. 1, 6, 10,</i> donner son assentiment à l’opinion de qqn, approuver l’avis de qqn ; <i>cf</i>. HDT. <i>2, 120 ;</i> PLAT. <i>Leg. 675</i> a.<br><span><b><span class=\"arrow\"></span></b> <i>Ao.2 sbj</i>. προσθῶ ; <i>pass. ao.1</i> προσετέθην, THC. <i>3, 82 ; d’ord. on emploie pour le pf. et le pl.q.pf. pass. le prés. et l’impf. de</i> πρόσκειμαι ; <i>ao. moy</i>. προσθῶμαι (<i>non</i> πρόσθωμαι) ; <i>opt. 3 sg</i>. προσθεῖτο (<i>vulg</i>. πρόσθοιτο) DÉM. <i>68, 27 ; 154, 1. Dor</i>. ποτιτίθημι, PD. <i>l. c</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προστιθημι - προστίθημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n18 fois dans 18 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (7)</li>\n<li>Actes (6)</li>\n<li>Galates (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4370":"<h1>prostrecho</h1>\n<p>Strong n° 4370 <i>Prononciation [pros-trekh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>courir à</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·τρέχω</b> <span>(<i>f</i>. προσδραμοῦμαι, <i>ao.2</i> προσέδραμον, <i>etc</i>.)</span> courir vers : τινί, AR. <i>Av. 759 etc. ;</i> XÉN. <i>An. 4, 3, 10 ; ou</i> πρός τινα, PLAT. <i>Rsp. 440</i> a, vers qqn ; <i>abs</i>. XÉN. <i>Cyr. 7, 1, 15, etc. ;</i> DÉM. <i>586, 4, etc. ; avec idée d’hostilité,</i> s’élancer contre, <i>avec</i> πρός <i>et l’acc</i>. XÉN. <i>Cyr. 5, 4, 47 ; fig</i>. se mettre du côté de, <i>dat</i>. POL. <i>26, 3, 4, etc. ;</i> πρὸς τὴν ἀλήθειαν, POL. <i>17, 15, 2,</i> se rapprocher de la vérité.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-τρεχω - προστρέχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (2)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4371":"<h1>prosphagion</h1>\n<p>Strong n° 4371 <i>Prononciation [pros-fag'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>toute chose mangée avec du pain\n<ol type=\"a\">\n<li>se dit de poissons bouillis ou grillés</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσφάγιον, ου (τὸ)</b> <span>[ᾰ]</span> <i>c</i>. προσφάγημα NT. <i>Joh. 21, 5</i>.<br><br>\n<b>προσφάγημα, ατος (τὸ)</b> <span>[φᾰ]</span> ce qu’on mange en outre du pain, pitance, ES. <i>64 Halm</i>.<br><span><b>Étym</b>. προσφαγεῖν, <i>inf. ao.2 de</i> προσέδω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσφαγιον - προσφάγιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4372":"<h1>prosphatos</h1>\n<p>Strong n° 4372 <i>Prononciation [pros'-fat-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dernièrement abattu, fraîchement tué</li>\n<li>récemment fabriqué, nouveau, neuf</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρόσ·φατος, ος, ον</b> <span>[ᾰ]</span><br><b>      1</b> qui vient d’être tué, récemment tué, IL. <i>24, 757 ;</i> HDT. <i>2, 89 et 121 ;</i><br><b>      2</b> <i>p. suite,</i> frais, récent, nouveau, <i>en parl. de poisson, de viandes, etc</i>. ANTIPH. (<i>Com. fr. 3, 128</i>) ; MÉN. (<i>Com. fr. 4, 206</i>) ; DS. <i>3, 31 ; de fruits,</i> ARSTT. <i>Probl. 20, 30 ; d’eau,</i> PLUT. <i>M. 690</i> c, <i>etc. ; fig. en parl. de châtiment,</i> ESCHL. <i>Ch. 804 ; de lettres,</i> SOPH. <i>fr. 130, etc. ; en parl. de pers</i>. DÉM. <i>551, 15, etc. ; p. opp. à</i> παλαιός, ARSTT. <i>Rhet. 1, 15, 13, etc. ; abs</i>. jeune, EL. <i>N.A. 7, 47 ; adv</i>. πρόσφατον, PD. <i>P. 4, 533,</i> nouvellement, récemment.<br><span><b>Étym</b>. πρός, θείνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσφατος - πρόσφατος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4373":"<h1>prosphatos</h1>\n<p>Strong n° 4373 <i>Prononciation [pros-fat'-oce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>dernièrement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσφάτως</b> <span>[ᾰ]</span> <i>adv</i>., récemment, nouvellement, MACH. (ATH. <i>581</i> e) ; POL. <i>3, 37, 11</i>.<br><span><b>Étym</b>. πρόσφατος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσφατως - προσφάτως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4374":"<h1>prosphero</h1>\n<p>Strong n° 4374 <i>Prononciation [pros-fer'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>apporter, mener, conduire\n<ol type=\"a\">\n<li>quelqu'un à une personne qui peut le guérir ou est prêt à lui manifester quelque bonté, ou à quelqu'un qui doit le juger</li>\n<li>apporter un présent ou une chose, tendre une chose à quelqu'un</li>\n<li>présenter, poser</li>\n</ol>\n</li>\n<li>être conduit vers, attaquer, assaillir\n<ol type=\"a\">\n<li>se conduire envers quelqu'un, traiter avec quelqu'un</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·φέρω</b> <span>(<i>f</i>. προσοίσω, <i>ao</i>. προσήνεγκα, <i>etc</i>.)</span><br><b>   I</b> porter auprès, vers <i>ou</i> contre :<br><b>      1</b> porter auprès : πύργοις κλιμάκων προσαμϐάσεις, EUR. <i>Ph. 488,</i> appliquer le long des tours des échelles pour l’escalade ; <i>fig</i>. rapprocher, <i>càd</i>. rendre semblable : τινί τι, PD. <i>fr. 154 Bgk,</i> une chose à une autre ;<br><b>      2</b> porter vers <i>ou</i> à : τροφὴν τῷ σώματι, PLAT. <i>Phædr. 270</i> b, porter de la nourriture au corps ; <i>fig</i>. τί τινι, SOPH. <i>O.C. 781, etc. ;</i> EUR. <i>Med. 298, etc</i>. dire qqe ch. à qqn ; τινὶ λόγον, HDT. <i>3, 134, etc</i>. adresser la parole à qqn ; λόγον πρ. ὅτι, DÉM. <i>1168, 22,</i> dire qqe ch. ; λόγον πρ. περί τινος, THC. <i>3, 109,</i> parler sur qqe ch. ; λόγους πρ. περί τινός τινι, THC. <i>2, 70,</i> entrer en pourparlers <i>ou</i> négocier avec qqn au sujet de qqe ch. ; πρ. λόγους τινί <i>avec un inf</i>. THC. <i>1, 57,</i> tenir des discours pour, <i>etc. ; p. suite,</i> apporter, présenter ; <i>avec un inf. :</i> τινὶ πρ. ἐμπιεῖν καὶ φαγεῖν, XÉN. <i>Cyr. 7, 1, 1,</i> présenter à qqn à boire et à manger ; τὰ προσφερόμενα, ce que l’on prend (nourriture, aliment, remède) HPC. <i>959</i> a, <i>1086</i> a, <i>etc. ;</i> XÉN. <i>Cyn. 6, 2, etc. ; avec idée de contrainte :</i> δῶρα, THC. <i>2, 97,</i> apporter de force, <i>càd</i>. livrer des présents ; <i>d’où</i> payer des contributions : μετοίκιον, XÉN. <i>Vect. 2, 1,</i> payer la taxe des métèques ; <i>en gén</i>. contribuer pour : ἑκατὸν τάλαντα, HDT. <i>3, 91,</i> pour cent talents ; <i>cf</i>. THC. <i>1, 138 ;</i><br><b>      3</b> porter contre : χεῖράς τινι, XÉN. <i>Mem. 2, 6, 31 ;</i> POL. <i>3, 79, 4,</i> mettre la main sur qqn <i>ou</i> sur qqe ch., <i>càd</i>. employer la force ; τινὶ ἀνάγκην, HDT. <i>7, 136 ; ou</i> βίην, HDT. <i>3, 19,</i> employer la contrainte <i>ou</i> la force contre qqn ; πόλεμόν τινι, HDT. <i>7, 9,</i> porter la guerre contre qqn ;<br><b>   II.1 <i>tr.</i></b> porter en outre, ajouter : μέθυ, SOPH. <i>O.C. 481,</i> du vin (à l’eau et au miel d’un sacrifice) ; κακὸν νέον παλαιῷ, EUR. <i>Med. 78,</i> ajouter un mal nouveau à un ancien ; τι πρός τι, HDT. <i>6, 125 ;</i> DÉM. <i>937, 16,</i> ajouter une chose à une autre ;<br><b>      2 <i>intr.</i></b> se rapprocher de, avoir du rapport avec, être analogue <i>ou</i> semblable à, PD. <i>N. 6, 4 ;</i><br><b><i>Pass.</i></b> <span>(<i>ao</i>. προσηνέχθην)</span><br><b>   I</b> se porter vers, <i>càd. :</i><br><b>      1</b> s’approcher de, s’avancer vers : <i>avec</i> πρός <i>et l’acc</i>. XÉN. <i>Hell. 4, 3, 20 ; avec le dat. :</i> τοῖσι Κορινθίοισι, HDT. <i>8, 94,</i> aller chez les Corinthiens ; τῷ σκοπέλῳ, LUC. <i>J. tr. 15,</i> se porter contre un écueil ; εἰς λιμένα, XÉN. <i>Cyr. 5, 4, 6,</i> entrer dans un port ; <i>avec double construct. :</i> ἑτέροισι ὑπηρέτῃσι πρ. καὶ πρὸς ἵππον, HDT. <i>5, 111,</i> s’avancer vers les autres serviteurs et vers le cheval ; <i>avec idée d’hostilité :</i> τινι, HDT. <i>5, 109 ;</i> THC. <i>4, 126, etc</i>. se jeter sur qqn <i>ou</i> qqe ch. ; πρός τινα, HDT. <i>5, 34, etc</i>. s’élancer contre qqn ; τινι πρὸς τὸ πρόσωπον, XÉN. <i>Cyn. 10, 9,</i> se jeter à la face d’un animal, <i>en parl. de chiens ; abs</i>. τοὺς προσφερόμενους δέχεσθαι, THC. <i>7, 44,</i> résister à (<i>litt</i>. recevoir) ceux qui s’avancent contre ; <i>en parl. d’un sanglier,</i> XÉN. <i>Cyr. 1, 4, 8 ;</i><br><b>      2</b> <i>avec un suj. de ch</i>. se présenter, se produire : τὰ προσφερόμενα πρήγματα, HDT. <i>2, 173,</i> les événements qui se produisent ;<br><b>   II</b> se comporter à l’égard de (qqn) : ὀλιγώρως, LYS. <i>115, 33,</i> avec dédain ; <i>avec le dat. de la pers. envers laquelle on se comporte de telle ou telle façon :</i> ἀπὸ τοῦ ἴσου τινί, THC. <i>1, 140,</i> traiter qqn sur un pied d’égalité ; <i>cf</i>. THC. <i>5, 111 ;</i> XÉN. <i>Cyr. 8, 1, 21 ; ou</i> πρός <i>et l’acc. :</i> πρός τινα μετὰ πρᾳότητος, ISOCR. <i>33</i> c, se conduire à l’égard de qqn avec douceur ; πρός τινα φιλανθρωπίᾳ, DÉM. <i>1428 fin,</i> à l’égard de qqn avec humanité ; <i>avec une locut. adv. :</i> ὡς φίλοι προσεφέροντο ἡμῖν, XÉN. <i>An. 5, 5, 19,</i> ils se conduisaient à notre égard en amis ; <i>de même avec</i> φίλοι <i>sans</i> ὡς ; <i>cf</i>. EUR. <i>Cycl. 176 ; p. suite,</i> user de, manier : ὀρθότατα ἵπποις προσφέρεσθαι, XÉN. <i>Eq. 1, 1,</i> gouverner très bien des chevaux ; ταῖς ξυμφοραῖς THC. <i>4, 18 ;</i> πρὸς τὰ πράγματα, THC. <i>6, 44,</i> se comporter (de telle <i>ou</i> telle façon) à l’égard des événements, des affaires ; ῥᾳθύμως καὶ ἀνάνδρως τοῖς πολεμικοῖς, HDN <i>6, 8, 7,</i> se conduire à la guerre mollement et sans énergie ;<br><b>   III</b> se rapprocher de, avoir du rapport avec, être analogue <i>ou</i> semblable : ἔς τινα, HDT. <i>1, 116,</i> à qqn ;<br><b>   IV</b> se produire en outre, s’ajouter, LGN <i>fr. 4, 4 ;</i><br><b><i>Moy.</i></b> <span>(<i>ao</i>. προσηνεγκάμην)</span><br><b>   I <i>intr.</i></b> se comporter : φιλανθρώπως τινί, DS. <i>16, 8,</i> avec bonté à l’égard de qqn ;<br><b>   II <i>tr</i>.<br>      1</b> porter à sa bouche : σῖτον καὶ ποτόν, XÉN. <i>Cyr. 4, 2, 41 ;</i> ESCHN. <i>20, 26, etc</i>. de la nourriture et de la boisson ;<br><b>      2</b> produire à l’égard de, <i>càd</i>. témoigner : χάριν τινί, PHILIPP. (DÉM. <i>284, 1</i>) témoigner sa reconnaissance envers qqn ; employer : πᾶσαν σπουδὴν καὶ μηχανὴν πρ. τινι, POL. <i>1, 18, 11, etc</i>. appliquer à une ch. toute sorte de soins et de ressources ;<br><b>      3</b> contribuer : εἴς τι, ATHÉNION (ATH. <i>660</i> e) à qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. pass. ion</i>. προσενείχθην (<i>var</i>. προσηνείχθην) HDT. <i>9, 71. Dor</i>. ποτιφέρω, PD. <i>ll. cc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-φερω - προσφέρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n48 fois dans 45 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (15)</li>\n<li>Marc (3)</li>\n<li>Luc (5)</li>\n<li>Jean (2)</li>\n<li>Actes (3)</li>\n<li>Hébreux (20)</li>\n</ul>\n</td></tr>\n</table>","G4375":"<h1>prosphiles</h1>\n<p>Strong n° 4375 <i>Prononciation [pros-fee-lace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>acceptable, plaisant</li>\n<li>aimé, chéri, agréable</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·φιλής, ής, ές</b> <span>[ῐ]</span><br><b>      1</b> <i>act</i>. plein d’amitié <i>ou</i> de bienveillance pour, <i>dat</i>. SOPH. <i>Ph. 587 ;</i> THC. <i>1, 92, etc. ;</i><br><b>      2</b> <i>pass</i>. aimé, chéri, agréable à, <i>dat</i>. HDT. <i>1, 163 ;</i> SOPH. <i>Ph. 532, etc. ;</i> ARSTT. <i>Pol. 8, 5, 15, etc. gén</i>. HDT. <i>1, 123 ;</i> THC. <i>5, 40</i>.<br><span><b><span class=\"arrow\"></span></b> <i>• Cp</i>. -έστερος, XÉN. <i>l. c. ;</i> <i>• Sup</i>. -έστατος, HDT. <i>1, 123 ;</i> ATT.<br><span><b>Étym</b>. π. φιλέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσφιλης - προσφιλής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4376":"<h1>prosphora</h1>\n<p>Strong n° 4376 <i>Prononciation [pros-for-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>l'action d'offrir, d'apporter</li>\n<li>ce qui est offert, un don, un présent. Dans le N.T. un sacrifice, qu'il soit avec du sang ou non, pour le péché, l'offrande expiatoire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσφορά, ᾶς (ἡ) :<br>   I</b> <i>act. :</i><br><b>      1</b> action de porter vers <i>ou</i> auprès, d’apporter (des échelles) POL. <i>5, 16, 7 ;</i><br><b>      2</b> action de mettre à portée, de présenter, d’offrir, PLAT. <i>Leg. 792</i> a ; SPT. <i>3Reg. 7, 34 ; Sir. 46, 16 ;</i> NT. <i>Rom. 15, 16, etc. ;</i><br><b>      3</b> action de porter en outre, d’ajouter, <i>d’où</i> accroissement, SOPH. <i>O.C. 1270 ;</i><br><b>   II</b> <i>pass. :</i><br><b>      1</b> ce qu’on apporte, <i>d’où</i> bienfait, gain, profit, SOPH. <i>O.C. 581 ; p. suite,</i> présent, TH. <i>Char. 30 ; d’où</i> offrande, SPT. <i>Ps. 39, 7, etc. ;</i> NT. <i>Ap. 21, 26, etc. ; particul</i>. offrande eucharistique, célébration de l’eucharistie, BAS. <i>4, 724, etc. ;</i> CHRYS. <i>1, 500, etc. edd. Migne ;</i><br><b>      2</b> ce qu’on porte (à sa bouche), nourriture, <i>particul</i>. aliment solide, HPC. <i>Aph. 1245 ;</i> TH. <i>C.P. 4, 9, 6 ;</i> PLUT. <i>M. 129</i> e ;<br><b>      3</b> ce qui se répand, <i>particul</i>. odeur, TH. <i>Od. 2, 5 ;</i><br><b>      4</b> revenu, ANT. (HARP.) ; JOS. <i>A.J. 19, 8, 2 ;</i> ATH. <i>33</i> f.<br><span><b>Étym</b>. προσφέρω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσφορα - προσφορά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>Ephésiens (1)</li>\n<li>Hébreux (5)</li>\n</ul>\n</td></tr>\n</table>","G4377":"<h1>prosphoneo</h1>\n<p>Strong n° 4377 <i>Prononciation [pros-fo-neh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>appeler à, adresser la parole à, interpeller</li>\n<li>appeler à soi, convoquer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·φωνέω-ῶ :<br>      1</b> adresser la parole à : τινα, IL. <i>2, 22, etc. ;</i> OD. <i>4, 69, etc. ;</i> ESCHL. <i>Ch. 1015 ;</i> SOPH. <i>O.R. 238, etc. ;</i> EUR. <i>Or. 47 ; postér</i>. τινι, DL. <i>7, 7 ;</i> NT. <i>Ap. 22, 2, etc</i>. à qqn ; <i>avec un acc. de chose :</i> πρ. τι, SOPH. <i>El. 1213,</i> prononcer une parole ; <i>avec double rég. :</i> τινά τινι, OD. <i>22, 69 ; ou</i> τινά τι, IL. <i>1, 332 ;</i> ESCHL. <i>fr. 155 ;</i> EUR. <i>Med. 664,</i> dire qqe ch. à qqn ; <i>avec l’inf</i>. DL. <i>7, 185,</i> prier qqn de, <i>etc</i>.<br><b>      2</b> appeler d’un nom <i>ou</i> d’un titre : ὀνόματι πρ. τινά, EUR. <i>Tr. 942,</i> appeler qqn par son nom ; τινὰ βασιλέα, POL. <i>10, 38, 3,</i> proclamer qqn roi ; <i>p. suite,</i> dédier : τινί τι, ATH. <i>313</i> f ; PLUT. <i>Luc. 1, etc</i>. qqe ch. à qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. épq. 3 sg</i>. προσεφώνεε, OD. <i>22, 69 ; 3 pl</i>. προσεφώνεον, IL. <i>1, 332</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προς-φωνεω - προσφωνέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (4)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4378":"<h1>proschusis</h1>\n<p>Strong n° 4378 <i>Prononciation [pros'-khoo-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>verser ou asperger sur, une effusion</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρόσχυσις, εως (ἡ)</b> <span>[ῠ]</span> action de verser sur, effusion, NT. <i>Hebr. 11, 28</i>.<br><span><b>Étym</b>. προσχέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσχυσις - πρόσχυσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4379":"<h1>prospsauo</h1>\n<p>Strong n° 4379 <i>Prononciation [pros-psow'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>toucher</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσ·ψαύω</b>, <i>dor. et poét</i>. <b>ποτι·ψαύω</b>, toucher à, <i>dat</i>. PD. <i>fr. 86, 2 ; abs</i>. toucher, SOPH. <i>O.C. 330, Tr. 1214, Ph. 1054</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσψαυω - προσψαύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4380":"<h1>prosopolepteo</h1>\n<p>Strong n° 4380 <i>Prononciation [pros-o-pol-ape-teh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>respecter la personne (c'est-à-dire la condition extérieure de l'homme)</li>\n<li>avoir du respect pour des personnes, différencier, distinguer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσωποληπτέω-ῶ</b>, avoir égard aux personnes, NT. <i>Jac. 2, 9</i>.<br><span><b>Étym</b>. προσωπολήπτης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσωπολημπτεω - προσωπολημπτέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4381":"<h1>prosopoleptes</h1>\n<p>Strong n° 4381 <i>Prononciation [pros-o-pol-ape'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>celui qui considère les personnes</li>\n<li>quelqu'un qui distingue, qui discerne, qui fait une différence, partial</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσωπο·λήπτης, ου</b>, <i>adj. m</i>. qui a égard aux personnes, partial, NT. <i>Ap. 10, 34 ;</i> CHRYS. <i>1, 137 Migne</i>.<br><span><b>Étym</b>. πρόσωπον, λαμϐάνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσωποληπτης - προσωπολήμπτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4382":"<h1>prosopolepsia</h1>\n<p>Strong n° 4382 <i>Prononciation [pros-o-pol-ape-see'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>considération pour les personnes</li>\n<li>partialité, qui a des préférences, qui accorde l'avantage à certains\n<ol type=\"a\">\n<li>la faute de celui qui doit porter un jugement en considération des circonstances extérieures à l'homme et non selon les mérites intrinsèques, et ainsi préfère celui qui est riche, de haute naissance, puissant, à un autre qui n'a pas ces qualités</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προσωποληψία, ας (ἡ)</b> partialité, NT. <i>Rom. 2, 11 ; Col. 3, 25, etc</i>.<br><span><b>Étym</b>. προσωπολήπτης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσωποληψια - προσωπολημψία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4383":"<h1>prosopon</h1>\n<p>Strong n° 4383 <i>Prononciation [pros'-o-pon]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la face\n<ol type=\"a\">\n<li>le front du corps humain</li>\n<li>contenance, aspect\n<ol>\n<li>la face où se trouve l'organe de la vue, et par ses mouvements variés est le reflet des pensées intérieures et sentiments</li>\n</ol>\n</li>\n<li>l'apparence que quelqu'un présente par ses biens ou ses richesses, son rang, ou bien une condition inférieure\n<ol>\n<li>circonstances extérieures, condition externe</li>\n<li>utilisé dans des expressions qui dénotent le regard de la personne dans son jugement et sa manière de traiter les hommes</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>l'apparence externe de choses inanimées</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρόσ·ωπον, ου (τὸ) :<br>   I</b> face, figure : <i>en parl. de l’homme,</i> IL. <i>18, 24, etc. ; d’ord. au pl. en parl. d’une seule pers</i>. IL. <i>7, 212, etc. ;</i> OD. <i>18, 192, etc. ;</i> XÉN. <i>An. 2, 6, 11, etc. ; rar. en parl. d’animaux (d’ord</i>. προτομή) : <i>de l’ibis,</i> HDT. <i>2, 76 ; de chiens,</i> XÉN. <i>Cyn. 4, 2 ; de chevaux,</i> ARSTT. <i>H.A. 9, 47, 2, etc. ; ou d’objets inanimés (la lune,</i> SOPH. <i>fr. 713 Dind. etc</i>.) : βλέπειν τινὰ εἰς πρόσωπον, EUR. <i>Hipp. 280,</i> regarder qqn en face ; εἰς πρ. τινος ἀφικέσθαι, EUR. <i>Hipp. 720,</i> venir en présence de qqn ; κατὰ πρόσωπον ἔντευξις, PLUT. <i>Cæs. 17,</i> rencontre <i>ou</i> entretien face à face, un tête-à-tête ; <i>p. ext</i>. aspect, air, ESCHL. <i>Ag. 639, etc. ;</i> SOPH. <i>O.R. 448 ; p. anal. :</i><br><b>      1</b> face <i>ou</i> front d’une armée, THC. <i>1, 106 ;</i> XÉN. <i>Cyr. 1, 6, 43, etc. ;</i> κατὰ πρόσωπον ἄγειν, POL. <i>11, 14, 6,</i> faire avancer le front ;<br><b>      2</b> avant d’un navire, A. TAT. <i>3, 1, 2 ;</i><br><b>      3</b> devant <i>ou</i> frontière d’un pays <i>ou</i> d’une ville, SPT. <i>Gen. 33, 18 ;</i><br><b>   II</b> figure artificielle, <i>particul. :</i><br><b>      1</b> masque de théâtre, DÉM. <i>432, 22 ;</i> ARSTT. <i>Poet. 5, 2 et 4, etc. ; p. suite,</i> rôle, personnage de théâtre, ARR. <i>Epict. 1, 29, 45 et 57 ; d’où</i> personne, <i>en gén</i>. POL. <i>8, 13, 5 ; 12, 27, 10 ;</i> NT. <i>1Thess. 2, 17, etc. ; t. de gr</i>. personne, D. THR. <i>638 ;</i> DYSC. <i>Pron. 262</i> a, <i>282</i> a ;<br><b>      2</b> <i>à Rome, au plur</i>. images des ancêtres, POL. <i>6, 53, 5</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Plur. épq</i>. προσώπατα, OD. <i>18, 192 ; dat</i>. προσώπασι, IL. <i>7, 212</i>.<br><span><b>Étym</b>. π. ὤψ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προσωπον - πρόσωπον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n77 fois dans 72 versets de 15 livres bibliques (NT)\n<ul>\n<li>Matthieu (10)</li>\n<li>Marc (3)</li>\n<li>Luc (14)</li>\n<li>Actes (12)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (12)</li>\n<li>Galates (3)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (3)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (10)</li>\n</ul>\n</td></tr>\n</table>","G4384":"<h1>protasso</h1>\n<p>Strong n° 4384 <i>Prononciation [prot-as'-so]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>placer avant</li>\n<li>désigner avant, définir d'avance, fixer, régler, décider</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·τάσσω :<br>      1</b> ranger en avant, placer au premier rang : σφῶν αὐτῶν τινα, THC. <i>3, 52,</i> placer qqn à leur tête (pour parler en leur nom) ; τινὰ πρό τινος, AND. <i>14, 31,</i> placer une personne devant une autre (pour la protéger) ; <i>abs</i>. XÉN. <i>Cyr. 5, 3, 37 ;</i> οἱ προτεταγμένοι, XÉN. <i>Hell. 2, 4, 15,</i> les combattants du premier rang ; <i>t. de gr</i>. placer devant, D. THR. <i>631, 640 ;</i> DH. <i>5, 88, 156, 157, 166 Reiske ;</i> PLUT. <i>M. 737</i> f ; DYSC. <i>Pron. 276</i> b, <i>303</i> c, <i>408</i> a ;<br><b>      2</b> fixer d’avance, <i>acc</i>. (un délai, SOPH. <i>Tr. 164 ;</i> une récompense, ARSTT. <i>Probl. 30, 11</i>) ;<br><b><i>Moy.</i></b> :<br><b>   I <i>intr.</i></b> se placer devant, <i>d’où</i> protéger, ESCHL. <i>Suppl. 835 ;</i><br><b>   II <i>tr</i>.<br>      1</b> ranger des troupes devant, <i>rég. ind. au gén</i>. XÉN. <i>Hell. 6, 4, 10 ;</i><br><b>      2</b> mettre devant ses yeux, <i>càd</i>. prendre comme exemple, PLAT. <i>Soph. 218</i> e, <i>ou</i> se proposer (un but) <i>acc</i>. PLAT. <i>Soph. 224</i> d.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-τασσω - προτάσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4385":"<h1>proteino</h1>\n<p>Strong n° 4385 <i>Prononciation [prot-i'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>étendre, exposer\n<ol type=\"a\">\n<li>celui qui est étendu et lié d'une courroie c.à.d. prêt à recevoir les coups de fouet, (en étant lié à une poutre ou un pilier)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·τείνω</b> <span>(<i>f</i>. -τενῶ, <i>ao</i>. προὔτεινα, <i>etc</i>.)</span><br><b>A <i>tr</i>.<br>   I</b> tendre en avant, allonger, <i>acc</i>. XÉN. <i>Eq. 6, 11 ;</i> ARSTT. <i>H.A. 4, 1, 29 ;</i> δεξιάν, SOPH. <i>Ph. 1292, etc. ;</i> EUR. <i>Alc. 1118, etc</i>. tendre la main pour confirmer une promesse ;<br><b>   II</b> <i>fig. càd. :</i><br><b>      1</b> exposer : ψυχήν, SOPH. <i>Aj. 1270,</i> sa vie ;<br><b>      2</b> produire, développer, <i>acc</i>. PLAT. <i>Phædr. 230</i> d ;<br><b>      3</b> mettre en avant, proposer (un gain, une espérance, <i>etc.) acc</i>. ESCHL. <i>Pr. 777 ;</i> PLAT. <i>Rsp. 382</i> a ; ANT. <i>135, 16 ;</i> δέλεαρ πρ. τὴν ἡδονήν, PLUT. <i>M. 13</i> a, offrir comme amorce le plaisir ; πρ. τινί <i>avec un inf</i>. XÉN. <i>Œc. 5, 8,</i> proposer à qqn de, <i>etc. ;</i> proposer (une recherche, une question, <i>etc.) acc</i>. PLUT. <i>M. 737</i> d ; ARR. <i>Epict. 3, 8, 1 ;</i> donner à résoudre (une énigme) <i>acc</i>. DL. <i>2, 70, etc. ;</i><br><b>      4</b> mettre en avant, alléguer, <i>acc</i>. HDT. <i>1, 156 ;</i> SOPH. <i>Ph. 992 ;</i> EUR. <i>Andr. 428 ;</i><br><b>      5</b> <i>t. de log</i>. formuler comme proposition, ARSTT. <i>An. pr. 1, 32, 4, etc. ;</i><br><b>B <i>intr.</i></b> s’avancer : εἰς τὸ πέλαγος, PLAT. <i>Criti. 111</i> a, dans la mer, <i>en parl. d’un promontoire ;</i><br><b><i>Moy</i>. προτείνομαι</b>, <i>f</i>. προτενοῦμαι :<br><b>   I <i>tr</i>.<br>      1</b> tendre en avant (la main comme suppliant) <i>acc</i>. HDT. <i>4, 136 ;</i> mettre en avant, proposer, offrir, <i>acc</i>. HDT. <i>5, 24 ;</i> PLAT. <i>Phædr. 266</i> a ; DÉM. <i>179, 17, etc. ;</i><br><b>      2</b> alléguer, <i>acc</i>. PLAT. <i>Ep. 317</i> c ;<br><b>      3</b> prétendre <i>ou</i> réclamer pour soi : μισθόν, HDT. <i>9, 34,</i> comme récompense ;<br><b>   II <i>intr.</i></b> établir en principe, formuler comme proposition (<i>v</i>. πρότασις) <i>t. de log</i>. ARSTT. <i>An. pr. 1, 27, 9</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προτεινω - προτείνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4386":"<h1>proteron</h1>\n<p>Strong n° 4386 <i>Prononciation [prot'-er-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>avant, antérieur\n<ol type=\"a\">\n<li>de temps, précédent, le premier</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρότερος, α, ον :<br>A</b> <i>adj</i>. premier de deux :<br><b>   I</b> (<i>avec idée de lieu</i>) πρότεροι πόδες, OD. <i>19, 228,</i> les pieds de devant ;<br><b>   II</b> (<i>avec idée de temps</i>) :<br><b>      1</b> <i>en gén. en parl. du temps passé, p. opp. au temps présent :</i> πρότεροι ἄνδρες <i>ou</i> ἄνθρωποι, HOM. <i>ou simpl</i>. οἱ πρότεροι, IL. <i>4, 308 ; ou sans art</i>. πρότεροι, ESCHL. <i>Ag. 1338, Eum. 934, etc</i>. les hommes d’autrefois, les anciens, les ancêtres ; προτέρη γενεή, IL. <i>23, 790,</i> la génération antérieure ;<br><b>      2</b> <i>en parl. de deux pers. ou de deux choses, ou de deux groupes de pers. ou de choses :</i> le premier de deux, <i>càd. avec idée d’âge,</i> le plus âgé, IL. <i>2, 707 ; p. opp. à</i> ὁπλότερος, OD. <i>19, 184 ;</i> πρότερος γενεῇ, IL. <i>15, 166, 182, m. sign. ; avec idée de temps en gén</i>. ὁ πρ. Διονύσιος, XÉN. <i>Hell. 7, 4, 12,</i> Dionysios (Denys) l’ancien ; πρότεροι παῖδες, OD. <i>15, 22,</i> enfants d’un premier mariage <i>ou</i> d’un mariage antérieur ; ἤματι τῷ προτέρῳ, IL. <i>21, 5 ;</i> τῇ προτέρῃ (<i>s.-e</i>. ἡμέρᾳ) OD. <i>16, 50 ;</i> THC. <i>7, 51,</i> le jour précédent ; <i>avec un gén. :</i> ἐμέο πρότερος, IL. <i>10, 124,</i> plus tôt que moi ; οἱ παλαιοὶ καὶ πρότεροι ἡμῶν, PLAT. <i>Hipp. ma. 282</i> b, les anciens, ceux qui nous ont précédés ; τῇ προτέρᾳ ἡμέρᾳ τῆς μάχης, THC. <i>5, 75,</i> la veille du combat ; <i>ou avec</i> ἤ : τῷ προτέρῳ ἔτει ἤ, HDT. <i>3, 47,</i> l’année avant que, <i>etc. ;</i> τῇ προτέρᾳ ἤ (<i>s.-e</i>. ἡμέρᾳ) ARSTT. <i>H.A. 6, 2,</i> le jour avant que ; πρότερος γενεῇ, IL. <i>15, 166, 182 ; 23, 790 ;</i> HÉS. <i>O. 159,</i> le premier par la naissance, le plus âgé ; <i>joint à un verbe au sens d’un attribut :</i> ὅ με πρότερος κάκ' ἔοργεν, IL. <i>3, 351,</i> qui m’a fait du mal le premier ; πρότερος ἢ ὑμεῖς ἐποιησάμην, PLAT. <i>Gorg. 523</i> a, avant vous j’ai fait, <i>etc. ;</i><br><b>   III</b> (<i>avec idée de rang</i>) qui va avant un autre, supérieur : πρότεροι ἡμῶν πρὸς τὰ τοῦ πολέμου, PLAT. <i>Lach. 183</i> b, supérieurs à nous en ce qui regarde les choses de la guerre ; <i>cf</i>. DÉM. <i>32, 19, etc. ; neutre adv</i>. πρότερον, HDT. <i>4, 45, etc., ou</i> τὸ πρότερον, XÉN. <i>An. 4, 4, 14 ;</i> PLAT. <i>Rsp. 522</i> a, <i>etc</i>. auparavant ; πρότερον τούτων, HDT. <i>8, 95 et 96,</i> avant ces choses <i>ou</i> avant ceux-ci ; <i>cf</i>. PLAT. <i>Leg. 642</i> d ; DÉM. <i>126, 10, etc. ;</i> ὁ πρότερον βασιλεύς, HDT. <i>1, 84,</i> le roi précédent ; ὁ πρότερον χρόνος, THC. <i>6, 9,</i> le temps antérieur ; Κῦρος ὁ πρότερον, LUC. <i>Sacr. 5,</i> Cyrus l’ancien ; πρότερον ἤ, <i>avec l’ind</i>. HDT. <i>6, 45 ; 8, 8 ; avec le sbj</i>. HDT. <i>7, 54 ; avec l’inf</i>. HDT. <i>7, 2 ;</i> THC. <i>1, 69, etc. ;</i> avant que <i>ou</i> de ; πρότερον πρὶν ἤ <i>avec l’ind</i>. HDT. <i>6, 45 ; 8, 8 ; avec le sbj</i>. HDT. <i>7, 8, etc. ; avec l’inf</i>. HDT. <i>6, 116 ; 9, 16,</i> avant que… ; πρότερον πρίν <i>avec l’ind</i>. XÉN. <i>An. 3, 1, 16 ;</i> πρὶν ἄν <i>avec le sbj</i>. HDT. <i>1, 82, m. sign. ;</i> οὐ πρότερον μή <i>avec le sbj</i>. HDT. <i>4, 127 ;</i> DIPH. (ATH. <i>291</i> f) ; PLUT. <i>M. 312</i> f, <i>etc</i>. pas avant que ; οὐ πρ. εἰ μή <i>avec l’inf</i>. PLUT. <i>Lys. 10 ; avec l’opt</i>. DL. <i>6, 46, etc. ;</i> οὐ πρ. ἕως <i>avec l’ind</i>. LYS. <i>126, 35, etc. ou</i> ἕως ἄν, <i>avec le sbj</i>. DS. <i>5, 18, etc. ;</i> μὴ πρ. ἀλλ' ὅταν, POL. <i>9, 13, 3,</i> pas plus tôt que quand, que jusqu’à ce que, <i>etc</i>.<br><span><b>Étym</b>. <i>cp. de</i> πρό.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προτερον - πρότερος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 6 livres bibliques (NT)\n<ul>\n<li>Jean (3)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (3)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4387":"<h1>proteros</h1>\n<p>Strong n° 4387 <i>Prononciation [prot'-er-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>d'avant, antérieur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρότερος, α, ον :<br>A</b> <i>adj</i>. premier de deux :<br><b>   I</b> (<i>avec idée de lieu</i>) πρότεροι πόδες, OD. <i>19, 228,</i> les pieds de devant ;<br><b>   II</b> (<i>avec idée de temps</i>) :<br><b>      1</b> <i>en gén. en parl. du temps passé, p. opp. au temps présent :</i> πρότεροι ἄνδρες <i>ou</i> ἄνθρωποι, HOM. <i>ou simpl</i>. οἱ πρότεροι, IL. <i>4, 308 ; ou sans art</i>. πρότεροι, ESCHL. <i>Ag. 1338, Eum. 934, etc</i>. les hommes d’autrefois, les anciens, les ancêtres ; προτέρη γενεή, IL. <i>23, 790,</i> la génération antérieure ;<br><b>      2</b> <i>en parl. de deux pers. ou de deux choses, ou de deux groupes de pers. ou de choses :</i> le premier de deux, <i>càd. avec idée d’âge,</i> le plus âgé, IL. <i>2, 707 ; p. opp. à</i> ὁπλότερος, OD. <i>19, 184 ;</i> πρότερος γενεῇ, IL. <i>15, 166, 182, m. sign. ; avec idée de temps en gén</i>. ὁ πρ. Διονύσιος, XÉN. <i>Hell. 7, 4, 12,</i> Dionysios (Denys) l’ancien ; πρότεροι παῖδες, OD. <i>15, 22,</i> enfants d’un premier mariage <i>ou</i> d’un mariage antérieur ; ἤματι τῷ προτέρῳ, IL. <i>21, 5 ;</i> τῇ προτέρῃ (<i>s.-e</i>. ἡμέρᾳ) OD. <i>16, 50 ;</i> THC. <i>7, 51,</i> le jour précédent ; <i>avec un gén. :</i> ἐμέο πρότερος, IL. <i>10, 124,</i> plus tôt que moi ; οἱ παλαιοὶ καὶ πρότεροι ἡμῶν, PLAT. <i>Hipp. ma. 282</i> b, les anciens, ceux qui nous ont précédés ; τῇ προτέρᾳ ἡμέρᾳ τῆς μάχης, THC. <i>5, 75,</i> la veille du combat ; <i>ou avec</i> ἤ : τῷ προτέρῳ ἔτει ἤ, HDT. <i>3, 47,</i> l’année avant que, <i>etc. ;</i> τῇ προτέρᾳ ἤ (<i>s.-e</i>. ἡμέρᾳ) ARSTT. <i>H.A. 6, 2,</i> le jour avant que ; πρότερος γενεῇ, IL. <i>15, 166, 182 ; 23, 790 ;</i> HÉS. <i>O. 159,</i> le premier par la naissance, le plus âgé ; <i>joint à un verbe au sens d’un attribut :</i> ὅ με πρότερος κάκ' ἔοργεν, IL. <i>3, 351,</i> qui m’a fait du mal le premier ; πρότερος ἢ ὑμεῖς ἐποιησάμην, PLAT. <i>Gorg. 523</i> a, avant vous j’ai fait, <i>etc. ;</i><br><b>   III</b> (<i>avec idée de rang</i>) qui va avant un autre, supérieur : πρότεροι ἡμῶν πρὸς τὰ τοῦ πολέμου, PLAT. <i>Lach. 183</i> b, supérieurs à nous en ce qui regarde les choses de la guerre ; <i>cf</i>. DÉM. <i>32, 19, etc. ; neutre adv</i>. πρότερον, HDT. <i>4, 45, etc., ou</i> τὸ πρότερον, XÉN. <i>An. 4, 4, 14 ;</i> PLAT. <i>Rsp. 522</i> a, <i>etc</i>. auparavant ; πρότερον τούτων, HDT. <i>8, 95 et 96,</i> avant ces choses <i>ou</i> avant ceux-ci ; <i>cf</i>. PLAT. <i>Leg. 642</i> d ; DÉM. <i>126, 10, etc. ;</i> ὁ πρότερον βασιλεύς, HDT. <i>1, 84,</i> le roi précédent ; ὁ πρότερον χρόνος, THC. <i>6, 9,</i> le temps antérieur ; Κῦρος ὁ πρότερον, LUC. <i>Sacr. 5,</i> Cyrus l’ancien ; πρότερον ἤ, <i>avec l’ind</i>. HDT. <i>6, 45 ; 8, 8 ; avec le sbj</i>. HDT. <i>7, 54 ; avec l’inf</i>. HDT. <i>7, 2 ;</i> THC. <i>1, 69, etc. ;</i> avant que <i>ou</i> de ; πρότερον πρὶν ἤ <i>avec l’ind</i>. HDT. <i>6, 45 ; 8, 8 ; avec le sbj</i>. HDT. <i>7, 8, etc. ; avec l’inf</i>. HDT. <i>6, 116 ; 9, 16,</i> avant que… ; πρότερον πρίν <i>avec l’ind</i>. XÉN. <i>An. 3, 1, 16 ;</i> πρὶν ἄν <i>avec le sbj</i>. HDT. <i>1, 82, m. sign. ;</i> οὐ πρότερον μή <i>avec le sbj</i>. HDT. <i>4, 127 ;</i> DIPH. (ATH. <i>291</i> f) ; PLUT. <i>M. 312</i> f, <i>etc</i>. pas avant que ; οὐ πρ. εἰ μή <i>avec l’inf</i>. PLUT. <i>Lys. 10 ; avec l’opt</i>. DL. <i>6, 46, etc. ;</i> οὐ πρ. ἕως <i>avec l’ind</i>. LYS. <i>126, 35, etc. ou</i> ἕως ἄν, <i>avec le sbj</i>. DS. <i>5, 18, etc. ;</i> μὴ πρ. ἀλλ' ὅταν, POL. <i>9, 13, 3,</i> pas plus tôt que quand, que jusqu’à ce que, <i>etc</i>.<br><span><b>Étym</b>. <i>cp. de</i> πρό.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προτερος - πρότερος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4388":"<h1>protithemai</h1>\n<p>Strong n° 4388 <i>Prononciation [prot-ith'-em-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>placer devant, disposer, destiner\n<ol type=\"a\">\n<li>destiné à être vu, exposé aux regards</li>\n<li>exposer à la vue du public\n<ol>\n<li>du corps d'un mort</li>\n<li>laisser disposé en l'état</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>mettre devant soi, se proposer à soi-même\n<ol type=\"a\">\n<li>former le projet, déterminer</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·τίθημι</b> <span>(<i>f</i>. προθήσω, <i>ao.1</i> προὔθηκα, <i>etc. ; au pass. pour le pf. et le pl.q.pf. les Att. emploient de préférence le prés. et l’impf. de</i> πρόκειμαι ; <i>ao</i>. προὐτέθην)</span><br><b>   I</b> placer devant, <i>càd. :</i><br><b>      1</b> placer devant : τραπέζας, OD. <i>1, 112,</i> des tables ; δαῖτά τινι, HDT. <i>1, 207 ;</i> δεῖπνόν τινι, SOPH. <i>Aj. 1303,</i> offrir un repas à qqn ; <i>en mauv. part,</i> exposer, livrer : τινὰ κυσίν, IL. <i>24, 409,</i> livrer qqn aux chiens ; τινὰ θανάτῳ, EUR. <i>Ph. 804 ; ou abs</i>. τινά, HDT. <i>1, 112 ;</i> SOPH. <i>Ph. 268,</i> livrer qqn à la mort ;<br><b>      2</b> exposer, offrir aux regards : ἀγοράν, LUC. <i>Bis acc. 4,</i> des marchandises ; τὴν ἀρετὴν ὤνιον, LUC. <i>Nigr. 25,</i> exposer la vertu en vente ; νεκρόν, HDT. <i>5, 8, etc</i>. exposer un mort ; <i>p. suite,</i> publier, faire connaître : γνώμην ὑπέρ τινος, THC. <i>3, 42,</i> son avis sur qqe ch. ; νόμον, PLUT. <i>Cam. 11,</i> promulguer une loi ; κρίσιν τινί, DS. <i>14, 13, etc. ;</i> PLUT. <i>Agis 11, etc</i>. intenter une action contre qqn ;<br><b>      3</b> ordonner, prescrire : τινί τι, SOPH. <i>Tr. 1049,</i> qqe ch. à qqn ; τινί <i>avec un inf</i>. SOPH. <i>Ant. 216,</i> ordonner à qqn de, <i>etc. ; cf</i>. HDT. <i>3, 38 ; 9, 27 ;</i><br><b>      4</b> proposer : πρῆγμα ἐς μέσον, HDT. <i>1, 206,</i> une affaire dans l’assemblée ; ἑαυτῷ νόμον, EUR. <i>Hipp. 1046,</i> proposer une loi, une punition contre soi-même ; σκοπόν, POL. <i>7, 8, 9,</i> un but ; πρ. ἀγῶνα, proposer une lutte, LUC. <i>Anach. 8 ; fig</i>. THC. <i>3, 67 ;</i> PLAT. <i>Phæd. 90</i> b, <i>etc. ;</i> πρ. τινὶ ἀέθλους, HDT. <i>7, 197,</i> proposer à qqn des épreuves ; ἆθλα, XÉN. <i>Cyr. 1, 6, 18,</i> des prix ; παραδείγματα, PLAT. <i>Soph. 226</i> c, des exemples ; τὰ ἔσχατα ἐπιτίμια, DÉM. <i>918, 4,</i> menacer des derniers châtiments ; θάνατον ζημίαν, THC. <i>3, 44,</i> infliger la peine de mort ;<br><b>   II</b> placer devant pour cacher <i>ou</i> couvrir : πέπλον ὀμμάτων, EUR. <i>I.A. 1550,</i> voiler ses yeux d’un manteau ; <i>fig</i>. αἰτίαν, SOPH. <i>Aj. 1051,</i> mettre en avant une raison, un prétexte ;<br><b>   III</b> placer devant, mettre avant, préférer : τί τινος, HDT. <i>3, 53 ;</i> THC. <i>1, 76, etc. ;</i> EUR. <i>Med. 963, etc. ; ou</i> τι ἀντί τινος, EUR. <i>Hipp. 381,</i> une ch. à une autre chose <i>ou</i> à qqn ;<br><b>   IV</b> placer en avant, faire mouvoir en avant, EUR. <i>Hec. 67 ;</i><br><b><i>Moy</i>. προτίθεμαι</b> <span>(<i>f</i>. προθήσομαι, <i>ao.1</i> προὐθηκάμην, <i>etc</i>.)</span><br><b>   I</b> placer qqe ch. (à soi) devant ; <i>particul</i>. placer qqe ch. à soi devant soi, <i>d’où fig</i>. se retrancher derrière, prétexter : τὴν συγγένειαν, POL. <i>2, 19, 1,</i> sa parenté ;<br><b>   II</b> placer devant soi : δαῖτα, HDT. <i>1, 133 ;</i> δεῖπνον, HDT. <i>4, 26,</i> un repas, un souper ; κλίνας καὶ τραπέζας, PLUT. <i>M. 99</i> e, des lits et des tables ; <i>fig</i>. se mettre devant les yeux, se proposer : τι, PLAT. <i>Phædr. 259</i> d, qqe ch. ; <i>avec un inf</i>. PLAT. <i>Rsp. 352</i> d, <i>Leg. 638</i> c, <i>etc. ;</i> αἵρεσιν, PLAT. <i>Leg. 858</i> a, se proposer à soi-même le choix ; εὐλάϐειάν τινος, SOPH. <i>El. 1334,</i> prendre des précautions à l’égard de qqe ch. ; θνητοὺς ἐν οἴκτῳ, ESCHL. <i>Pr. 239,</i> regarder les mortels en s’apitoyant (<i>litt</i>. se mettre devant les yeux les mortels) ;<br><b>   III</b> mettre en avant, <i>d’où :</i><br><b>      1</b> produire, exposer : ποτήρια χρύσεα, HDT. <i>3, 148,</i> des coupes d’or ; νεκρόν, THC. <i>2, 34 ;</i> EUR. <i>Alc. 664, etc</i>. un mort ;<br><b>      2</b> déclarer : πένθος μέγα, HDT. <i>6, 21,</i> prescrire un grand deuil public ; σύγκλητον λέσχην, SOPH. <i>Ant. 160,</i> convoquer une assemblée ;<br><b>      3</b> proposer : πρός τινα, <i>avec l’inf</i>. PLUT. <i>Rom. 5,</i> à qqn de, <i>etc. ;</i> τινὶ ἔχθραν, THC. <i>8, 55,</i> déclarer à qqn son inimitié ; τὰς αἰτίας, POL. <i>4, 25, 6,</i> produire ses raisons ; <i>abs</i>. πρ. ὡς περί, <i>etc</i>. POL. <i>8, 13, 1,</i> mettre en avant qqe ch. comme de, <i>etc.,</i> parler (de qqn) comme si, <i>etc. ;</i><br><b>   IV</b> placer en avant, envoyer en avant, faire prendre les devants à, <i>acc</i>. POL. <i>1, 33, 9 ;</i> fixer (un délai) <i>acc</i>. HDT. <i>1, 74 ; fig</i>. préférer, πάρος προτίθεσθαί τί τινος, SOPH. <i>O.C. 419,</i> faire passer une ch. avant une autre.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. ind. 3 pl. épq</i>. προθέουσι, IL. <i>1, 291 ; impf. 3 pl. épq</i>. πρότιθεν (<i>p</i>. προετίθεσαν) OD. <i>1, 112 ; moy. prés. ind. 3 pl. ion</i>. προτιθέαται (<i>p</i>. προτίθενται) HDT. <i>4, 26</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προτιθημαι - προτίθημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4389":"<h1>protrepomai</h1>\n<p>Strong n° 4389 <i>Prononciation [prot-rep'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>presser en avant, exhorter, encourager</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·τρέπω</b> <span>(<i>f</i>. -τρέψω, <i>etc</i>.)</span><br><b>   I</b> tourner en avant, pousser en avant, <i>acc</i>. GAL. ;<br><b>   II</b> <i>fig. :</i><br><b>      1</b> pousser, exciter, exhorter : τινά, ISOCR. <i>107</i> c ; ARSTT. <i>Nic. 3, 5, 7,</i> qqn ; <i>p. opp. à</i> κωλύω, SOPH. <i>O.R. 1446 ;</i> πρός τι, PLAT. <i>Leg. 711</i> b, <i>etc. ; ou</i> εἴς τι, PLAT. <i>Euthyd. 274</i> e ; <i>ou</i> ἐπί τι, PLAT. <i>Euthyd. 307</i> a, <i>etc. ;</i> ISOCR. <i>16</i> c, <i>etc</i>. qqn à qqe ch. ; τινά <i>avec l’inf</i>. HDT. <i>9, 90 ;</i> SOPH. <i>Ant. 270,</i> exhorter qqn à faire qqe ch. ; τινὰ ὥστε, THC. <i>8, 63,</i> pousser qqn à, <i>etc. ; au pass</i>. être poussé à, XÉN. <i>Mem. 1, 1, 4 ;</i><br><b>      2</b> pousser jusqu’à, réduire : τινα, SOPH. <i>El. 1193,</i> qqn ;<br><b><i>Moy</i>. προτρέπομαι</b> <span>(<i>f</i>. προτρέψομαι, <i>ao.1</i> προετρεψάμην, <i>ao.2</i> προετραπόμην, <i>ao.2 pass</i>. προετράπην)</span><br><b>   I <i>intr.</i></b> se tourner vers, se diriger vers : ἐπὶ γαῖαν, OD. <i>11, 18 ; 12, 381,</i> vers la terre ; ἐπὶ νηῶν, IL. <i>5, 700,</i> s’enfuir sur les vaisseaux ; <i>fig</i>. ἄχει, IL. <i>6, 336,</i> s’abandonner au chagrin ;<br><b>   II <i>tr</i>.<br>      1</b> exhorter, exciter : τινα ἐπί τι, XÉN. <i>Mem. 1, 4, 1 ;</i> πρός τι, XÉN. <i>Mem. 4, 5, 1 ; ou</i> εἴς τι, XÉN. <i>Cyr. 2, 2, 14 ;</i> ESCHN. <i>27, 13,</i> qqn à qqe ch. ; τινα <i>avec l’inf</i>. ESCHL. <i>Pr. 990 ;</i> SOPH. <i>O.R. 358, etc</i>. exhorter <i>ou</i> décider qqn à, <i>etc. ; abs</i>. SOPH. <i>O.R. 1446 ;</i><br><b>      2</b> attirer à soi, <i>càd</i>. exciter l’attention de : τινά τι, HDT. <i>1, 31,</i> de qqn au sujet de qqe ch. ;<br><b>      3</b> attirer à soi, <i>càd</i>. se concilier : τινά, SEXT. qqn ;<br><b>      4</b> bouleverser, PLUT. <i>M. 624</i> c.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προτρεπομαι - προτρέπω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4390":"<h1>protrecho</h1>\n<p>Strong n° 4390 <i>Prononciation [prot-rekh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>courir au devant, dépasser</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·τρέχω</b> <span>(<i>f</i>. -δραμοῦμαι, <i>ao</i>. προὔδραμον, <i>etc</i>.)</span><br><b>      1</b> courir en avant, XÉN. <i>An. 1, 5, 2 ;</i> ANT. <i>122, 1 ;</i><br><b>      2</b> devancer en courant, <i>gén</i>. XÉN. <i>An. 5, 2, 4 ; fig</i>. courir plus vite que, <i>gén</i>. ISOCR. <i>11</i> a ; devancer de beaucoup, <i>gén</i>. TH. <i>H.P. 8, 7, 7</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προτρεχω - προτρέχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4391":"<h1>prouparcho</h1>\n<p>Strong n° 4391 <i>Prononciation [pro-oop-ar'-kho]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être avant que, exister antérieurement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·ϋπάρχω :<br>      1 <i>intr.</i></b> être avant, exister avant, <i>gén</i>. ARSTT. <i>Mot. an. 5, 2 ; abs</i>. être auparavant, se trouver là auparavant, THC. <i>2, 85 ; 4, 126 ;</i> PLAT. <i>Prot. 317</i> d, <i>etc. ;</i> οἱ νόμοι οἱ προϋπάρχοντες, ARSTT. <i>Pol. 4, 5, 4,</i> les lois existantes ; οἱ προϋπάρχοντες ὕπατοι, POL. <i>3, 106, 2,</i> les consuls désignés ; τὰ προϋπάρξαντα, DÉM. <i>12, 16,</i> les faits antérieurs ;<br><b>      2 <i>tr.</i></b> entreprendre le premier, donner l’exemple <i>ou</i> le signal de : τινός, THC. <i>3, 40 ;</i> ISOCR. <i>89</i> c, <i>etc</i>. de qqe ch. ; <i>avec le dat. :</i> προϋπάρχειν τῷ ποιεῖν εὖ, DÉM. <i>471, 2,</i> obliger le premier par un bienfait ; τὰ προϋπηργμένα, les services rendus antérieurement à qqn, DÉM. <i>1191 ; ou</i> les antécédents (de qqn) DÉM. <i>314, 9 ;</i> ARSTT. <i>Rhet. 1, 9, 31</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προυπαρχω - προϋπάρχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4392":"<h1>prophasis</h1>\n<p>Strong n° 4392 <i>Prononciation [prof'-as-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un prétexte (une raison alléguée, une cause prétendue)</li>\n<li>montrer\n<ol type=\"a\">\n<li>sous les couleurs que l'on voudrait voir quelque chose</li>\n<li>avec prétention, avec ostentation</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρό·φασις, εως (ἡ)</b> <span>[ᾰ]</span> motif mis en avant, <i>d’où :</i><br><b>      1</b> prétexte légitime : πρ. ἀληθής, DÉM. <i>279, 21 ;</i> ἀληθέστατη, THC. <i>1, 23,</i> motif véritable, motif très véritable ; εἰκυῖα, PLAT. <i>Leg. 772</i> a ; ἐπιεικής, THC. <i>3, 9,</i> prétexte plausible ; ἐνδοῦναί τινι πρόφασιν, <i>avec l’inf</i>. ISOCR. donner à qqn comme prétexte que, <i>etc. ;</i><br><b>      2</b> <i>en mauv. part :</i> prétexte simulé, mauvaise raison, <i>p. opp. à</i> αἰτία, THC. <i>3, 13 ; à</i> λόγος εὐτράπελος, AR. <i>Vesp. 468 ;</i> αὕτη ἦν σοι πρ. <i>avec l’inf</i>. SOPH. <i>Ph. 1034,</i> voilà le prétexte que tu avais pour, <i>etc. ;</i> οὐδεμία σοι πρ. ἐστιν ὡς, XÉN. <i>Cyr. 2, 2, 15 ; ou</i> οὐκ ἔστιν οὐδεμία πρ. ἡμῖν τοῦ, <i>etc</i>. PLAT. <i>Tim. 20</i> c, tu n’as, nous n’avons aucun prétexte pour, <i>etc. ;</i> πρόφασιν διδόναι, DÉM. <i>1067, 25, etc</i>. donner prétexte de, <i>etc. ;</i> οὐκ ἐνδώσομεν πρόφασιν οὐδενί, <i>avec un inf</i>. THC. <i>2, 87,</i> nous ne donnerons prétexte à personne de, <i>etc. ;</i> πρόφασιν ἔχειν <i>avec un suj. de pers</i>. avoir un prétexte, THC. <i>3, 13 ;</i> EUR. <i>I.A. 1435, etc. ;</i> AR. <i>Vesp. 339, etc. ; avec un suj. de chose,</i> fournir un prétexte, PLAT. <i>Rsp. 469</i> c ; πρ. ἔχειν ὥστε, <i>avec l’inf</i>. XÉN. <i>Cyr. 3, 1, 27,</i> fournir un prétexte pour, <i>etc. ;</i> πρόφασιν παρέχειν, offrir un prétexte, DÉM. <i>140, 23, ou</i> produire de feintes raisons, AR. <i>Av. 581 ;</i> πρόφασιν θέσθαι, THGN. <i>364,</i> s’appuyer sur un prétexte ; πρόφασιν προτείνειν, HDT. <i>1, 156,</i> mettre un prétexte en avant ; κατασκευάζειν, XÉN. <i>Cyr. 2, 4, 17,</i> imaginer un prétexte ; πάσας προφάσεις προφασίζεσθαι, PLAT. <i>Rsp. 474</i> e, mettre en avant toutes sortes de prétextes ; πρόφασιν λαμϐάνειν, DÉM. <i>277, 28,</i> prendre un prétexte ; προφάσεως ἔχεσθαι, HDT. <i>6, 94,</i> saisir un prétexte ; μή μοι πρόφασιν, AR. <i>Ach. 345,</i> pas de prétexte ! pas d’excuse ! μὴ προφάσεις, ALEX. (ATH. <i>170</i> a) au diable les excuses ! <i>adv</i>., προφάσει, THC. <i>3, 86 ;</i> ἐπὶ προφάσει, THGN. <i>323 ;</i> THC. <i>1, 141 ; 7, 13, etc. ;</i> ἐπὶ προφάσεως, HDT. <i>7, 150 ;</i> ἀπὸ προφάσιος, HDT. <i>2, 161 ;</i> ἀπὸ προφάσεως, THC. <i>2, 23 ;</i> ἐκ προφάσεως, POL. <i>2, 17, 3 ;</i> διὰ πρόφασιν, HDT. <i>4, 145 ; 7, 230 ;</i> κατὰ πρόφασιν, HDT. <i>1, 29 ;</i> προφάσιος εἵνεκεν, HDT. <i>4, 135 ; ou</i> προφάσεως χάριν, ARSTT. <i>Pol. 4, 13,</i> sous prétexte de, <i>avec un gén. ou abs</i>. soi-disant ; <i>à l’acc. abs</i>. πρόφασιν, IL. <i>19, 262, 302 ;</i> THC. <i>3, 111 ;</i> EUR. <i>I.A. 362, etc</i>. en apparence, soi-disant ; πρόφασιν μὲν… τὸ δὲ ἀληθές, THC. <i>6, 33 ;</i> πρόφασιν μὲν… ἔργῳ δέ, LYS. <i>120, 35,</i> en apparence… mais en réalité ; ἡ Πρ. le Prétexte personnifié, PD. <i>P. 5, 35 ;</i><br><b>      3</b> ce qui explique qqe ch., occasion <i>ou</i> cause d’une maladie, ISOCR. <i>Ep. 415</i> e.<br><span><b>Étym</b>. προφαίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πορφασις - πρόφασις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G4393":"<h1>prophero</h1>\n<p>Strong n° 4393 <i>Prononciation [prof-er'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>amener, tirer</li>\n<li>faire sortir de, produire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·φέρω</b> <span>(<i>f</i>. προοίσω, <i>ao.1</i> προήνεγκα, <i>ao.2</i> προήνεγκον, <i>etc</i>.)</span><br><b>A <i>tr</i>.<br>   I</b> porter en avant, <i>càd. :</i><br><b>      1</b> apporter : νεοσσοῖσι μάστακα, IL. <i>9, 323,</i> de la nourriture à ses petits, <i>en parl. d’un oiseau ;</i> νέκυν Ἀχιλῆϊ, IL. <i>17, 121,</i> un cadavre à Achille ; σφάγια, THC. <i>6, 69,</i> amener des victimes pour le sacrifice ;<br><b>      2</b> avancer : πόδα, EUR. <i>Tr. 1334,</i> avancer le pied, s’avancer ; τινά, IL. <i>6, 347 ;</i> OD. <i>20, 64,</i> porter <i>ou</i> pousser qqn en avant, <i>en parl. d’un ouragan ; particul</i>. emporter dans un convoi funèbre, <i>acc</i>. EUR. <i>Med. 1111 ; fig</i>. faire avancer, être profitable, avantageux : εἴς τι, PD. <i>P. 2, 158 ;</i> THC. <i>1, 93,</i> pour qqe ch. ; ὁδοῦ καὶ ἔργου, HÉS. <i>O. 577,</i> faire avancer la marche et le travail ;<br><b>      3</b> mettre au jour, produire : ἔριδα, OD. <i>6, 92,</i> rivaliser d’ardeur ; τι ἐς μέσον, PLAT. <i>Leg. 396</i> a, <i>etc</i>. publier qqe ch. ; τι ἐς φάος, LUC. <i>Astr. 10,</i> produire qqe ch. à la lumière ; <i>fig</i>. πρ. μένος, IL. <i>10, 479,</i> montrer du courage ; <i>p. suite,</i> énoncer, proférer : ὀνείδεά τινι, IL. <i>2, 251,</i> des reproches contre qqn ; annoncer, proclamer, publier, <i>acc</i>. PD. <i>I. 5, 55 ;</i> parler au nom de, ESCHL. <i>Ag. 201 ;</i> mentionner, THC. <i>3, 64 ;</i> XÉN. <i>Œc. 14, 6 ;</i> PLAT. <i>Soph. 259</i> d ; <i>en parl. d’un oracle,</i> ordonner, ESCHL. <i>Ag. 964 ;</i> HDT. <i>5, 65 ;</i><br><b>      4</b> <i>en mauv. part :</i> objecter, reprocher : τί τινι, IL. <i>3, 64 ;</i> HDT. <i>1, 3 ; 4, 151 ;</i> ESCHN. <i>63, 11 ;</i> DÉM. <i>576, 13, etc</i>. faire un reproche à qqn ;<br><b>   II</b> porter devant : λύχνον τινί, DC. <i>39, 31,</i> porter une lumière devant qqn ;<br><b>B <i>intr.</i></b> l’emporter sur : τινός τινι, HDT. <i>3, 106 ; 6, 127 ;</i> THC. <i>1, 123 ; 2, 89 ; ou</i> τινὸς ἔν τινι, DC. <i>77, 11 ; ou</i> τινὸς εἴς τι, EUR. <i>Med. 1093,</i> sur qqn en qqe ch. ; <i>rar. avec l’acc</i>. τινά, ANTH. <i>9, 344,</i> l’emporter sur qqn ;<br><b><i>Moy.</i></b> :<br><b>      1</b> mettre au jour, annoncer, proclamer, alléguer, <i>acc</i>. PLAT. <i>Phil. 57</i> a ; POL. <i>4, 66, 10 ;</i> DH. <i>Dem. 17, etc. ;</i><br><b>      2</b> reprocher, <i>acc</i>. POL. <i>5, 11, 2 ;</i><br><b>      3</b> proposer : ξεινοδόκῳ ἔριδα, OD. <i>8, 210,</i> un combat à un hôte ; <i>cf</i>. IL. <i>3, 7</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans Hom. seul. au prés. ind. et sbj. 3 sg. épq</i>. προφέρῃσι, IL. <i>9, 323 et à l’impf</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-φερω - προφέρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G4394":"<h1>propheteia</h1>\n<p>Strong n° 4394 <i>Prononciation [prof-ay-ti'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prophétie\n<ol type=\"a\">\n<li>discours émanant de l'inspiration divine et déclarant les desseins de Dieu, soit pour reprendre et admonester le méchant ou pour réconforter l'affligé, et révéler des choses cachées ; spéc. par prédiction d'événements futurs</li>\n<li>utilisé dans le N.T. pour le message des prophètes de l'A.T.\n<ol>\n<li>prédiction des événements relatifs au royaume de Christ et son rapide triomphe, avec les consolations et exhortations lui appartenant, l'esprit de prophétie, l'esprit divin, desquels vient cette faculté</li>\n<li>de la dotation et du discours des enseignants Chrétiens appelés prophètes</li>\n<li>les dons et émissions de ces prophètes, mis à part pour enseigner l'évangile, et dont les prédictions s'accompliront pour le royaume de Christ</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προφητεία, ας (ἡ) :<br>      1</b> action d’interpréter la volonté des dieux, ORACL. (LUC. <i>Alex. 40), d’où</i> oracle, LUC. <i>Alex. 60 ;</i><br><b>      2</b> explication des Livres saints sous l’inspiration de l’Esprit saint, NT. <i>1Cor. 12, 10 ; 1Tim. 1, 18, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -είη, LUC. <i>ll. cc</i>.<br><span><b>Étym</b>. προφητεύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προφητεια - προφητεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n19 fois dans 19 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (5)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Timothée (2)</li>\n<li>2 Pierre (2)</li>\n<li>Apocalypse (7)</li>\n</ul>\n</td></tr>\n</table>","G4395":"<h1>propheteuo</h1>\n<p>Strong n° 4395 <i>Prononciation [prof-ate-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prophétiser, être un prophète, parler sous l'inspiration divine, prédire\n<ol type=\"a\">\n<li>prophétiser</li>\n<li>avec l'idée de prévision des événements futurs, en particulier sur le royaume de Dieu</li>\n<li>exposer, déclarer, une chose qui peut être connue seulement par révélation divine</li>\n<li>briser sous l'impulsion soudaine d'un discours élevé ou par louange des conseils divins\n<ol>\n<li>par ces messages, enseigner, réfuter, réprouver, consoler les autres</li>\n</ol>\n</li>\n<li>agir comme un prophète, remplir la fonction prophétique</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προφητεύω</b> <span>(<i>impf</i>. προεφήτευον <i>ou mieux</i> ἐπροφήτευον, <i>f</i>. προφητεύσω, <i>ao</i>. προεφήτευσα <i>ou mieux</i> ἐπροφήτευσα, <i>pf. inus. ; pass. pf</i>. προπεφήτευμαι <i>ou mieux</i> πεπροφήτευμαι)</span><br><b>      1</b> être interprète d’un dieu, PD. <i>fr. 127 Bgk ;</i> HDT. <i>7, 111 ;</i> EUR. <i>Ion 413 ;</i><br><b>      2</b> <i>p. suite,</i> annoncer l’avenir, prophétiser, <i>acc</i>. EUR. <i>Ion 369 ;</i> ARSTT. <i>Mund. 1, 2 ; abs</i>. PLAT. <i>Phædr. 244</i> d ;<br><b>      3</b> expliquer de vive voix les textes sacrés sous l’inspiration de l’Esprit saint, NT. <i>Luc. 1, 67 ; Joh. 11, 51 ; Ap. 2, 17, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. dor</i>. προφατεύσω <span>[ᾱ]</span> PD. <i>fr. 127 Bgk</i>.<br><span><b>Étym</b>. προφήτης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προφητευω - προφητεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n28 fois dans 27 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n<li>Actes (4)</li>\n<li>1 Corinthiens (11)</li>\n<li>1 Pierre (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4396":"<h1>prophetes</h1>\n<p>Strong n° 4396 <i>Prononciation [prof-ay'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dans les écrits Grecs, celui qui interprète oracles ou autres choses cachées</li>\n<li>quelqu'un qui, poussé par l'Esprit de Dieu et de là son organe ou messager, déclare solennellement ce qu'il a reçu par inspiration, concernant spécialement les futurs événements, et en particulier ceux relatifs à la cause et au royaume de Dieu et au salut de l'humanité\n<ol type=\"a\">\n<li>prophètes de l'A.T., ayant prédit le royaume, les actions et la mort de Jésus le Messie.</li>\n<li>Jean-Baptiste, le héraut de Jésus le Messie</li>\n<li>l'illustre prophète, que les Juifs espéraient avant la venue du Messie</li>\n<li>le Messie</li>\n<li>hommes remplis de l'Esprit de Dieu, qui par l'autorité de Dieu et ses commandements dans des paroles de poids poussent au salut des hommes</li>\n<li>prophètes apparaissant dans l'âge apostolique parmi les Chrétiens\n<ol>\n<li>ils sont associés aux apôtres</li>\n<li>ils ont discerné et fait ce qui est le meilleur pour la cause chrétienne, prédisant certains événements futurs (<a class=\"ref\" data-r=\"ACT11.27\">Actes 11.27</a>)</li>\n<li>dans les assemblées religieuses de Chrétiens, ils étaient poussés par le Saint Esprit pour parler, ayant le pouvoir d'instruire, de consoler, encourager, réprimander, condamner, et stimuler, leurs auditeurs</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>un poète (car un poète est censé chanter sous l'inspiration divine)\n<ol type=\"a\">\n<li>de Epiménide, poète crétois, du 7<sup>ème</sup> siècle av. J.C. (<a class=\"ref\" data-r=\"TIT1.12\">Tite 1.12</a>)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προφήτης, ου (ὁ) :<br>   I</b> interprète d’un dieu, <i>d’où :</i><br><b>      1</b> celui qui transmet <i>ou</i> explique la volonté des dieux (Tirésias, PD. <i>N. 1, 91 ;</i> Orphée, EUR. <i>Rhes. 972 ;</i> oracle de Delphes, ESCHL. <i>Eum. 19, etc. ;</i> PLAT. <i>Rsp. 366</i> b, <i>etc.) ; en parl. des cigales,</i> interprète des muses, PLAT. <i>Phædr. 262</i> d ; <i>dans les Livres saints,</i> interprète de la parole de Dieu, SPT. <i>1Reg. 9, 9 ;</i> NT. <i>1Cor. 12, 10, etc. ;</i><br><b>      2</b> interprète des paroles d’un oracle <i>ou</i> d’un devin, ESCHL. <i>Ag. 1099, etc. ;</i> PLAT. <i>Tim. 72</i> a, <i>etc. ;</i><br><b>      3</b> <i>en gén</i>. interprète des paroles d’un autre, EUR. <i>Bacch. 211 ;</i><br><b>      4</b> interprète d’une doctrine, <i>en parl. des Épicuriens, interprète de la doctrine des atomes,</i> ATH. <i>187</i> b ; <i>de Timon, interprète de la doctrine de Pyrrhon,</i> SEXT. <i>M. 1, 53, etc. ;</i><br><b>   II</b> <i>p. suite :</i><br><b>      1</b> celui qui annonce l’avenir, prophète, ESCHL. <i>Sept. 610, Ag. 409, etc. ; dans les Livres saints,</i> NT. <i>Ap. 2, 30 ; 3, 18, etc. ;</i><br><b>      2</b> qui annonce, <i>en gén</i>. PD. <i>N. 9, 120 ;</i> ANACR. <i>35, 11</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. προφάτας <span>[ᾱ]</span> PD. <i>ll. cc</i>.<br><span><b>Étym</b>. προφημί.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προφητης - προφήτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n145 fois dans 139 versets de 15 livres bibliques (NT)\n<ul>\n<li>Matthieu (38)</li>\n<li>Marc (6)</li>\n<li>Luc (29)</li>\n<li>Jean (14)</li>\n<li>Actes (30)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (6)</li>\n<li>Ephésiens (3)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (2)</li>\n<li>Apocalypse (8)</li>\n</ul>\n</td></tr>\n</table>","G4397":"<h1>prophetikos</h1>\n<p>Strong n° 4397 <i>Prononciation [prof-ay-tik-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>paroles venant d'un prophète</li>\n<li>prophétique</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προφητικός, ή, όν</b>, de prophète <i>ou</i> de prophétie, prophétique, LUC. <i>Alex. 60 ;</i> NT. <i>2Petr. 1, 19</i>.<br><span><b>Étym</b>. προφήτης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προφητικος - προφητικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4398":"<h1>prophetis</h1>\n<p>Strong n° 4398 <i>Prononciation [prof-ay'-tis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une prophétesse</li>\n<li>une femme à qui sont révélés les événements ou choses cachées, soit par l'inspiration, soit par des songes ou visions</li>\n<li>une femme qui annonce ou interprète des oracles</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προφῆτις, ιδος (ἡ)</b> <i>fém. de</i> , EUR. <i>Ion 42, 321 ;</i> PLAT. <i>Phædr. 244</i> a ; DS. <i>1, 2, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προφητις - προφῆτις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4399":"<h1>prophthano</h1>\n<p>Strong n° 4399 <i>Prononciation [prof-than'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>venir avant, anticiper, devancer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·φθάνω</b>, prévenir, devancer, <i>acc</i>. ESCHL. <i>Ag. 1028 ;</i> PLAT. <i>Rsp. 500</i> a ; <i>avec un part</i>. AR. <i>Eccl. 884 ;</i><br><b><i>Moy.</i></b> <span>(<i>ao. part</i>. προφθάμενος <span>[ᾰ]</span>)</span> <i>m. sign</i>. A. RH. <i>4, 913 ;</i> NONN. <i>Jo. 13, 19</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προφθανω - προφθάνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>"};
